#include "common.h"

/* ---------- CRC ---------- */
static uint8_t crc8_tab[256];
static uint16_t crc16_tab[256];
static uint32_t crc32le_tab[256];
static uint32_t crc32be_tab[256];
static int crc_inited;

static void crc_init(void)
{
    if (crc_inited) return;
    for (int i = 0; i < 256; i++) {
        unsigned c = i;
        for (int j = 0; j < 8; j++) c = (c & 0x80) ? ((c << 1) ^ 0x07) : (c << 1);
        crc8_tab[i] = c & 0xff;
        c = i << 8;
        for (int j = 0; j < 8; j++) c = (c & 0x8000) ? ((c << 1) ^ 0x8005) : (c << 1);
        crc16_tab[i] = c & 0xffff;
        uint32_t d = i;
        for (int j = 0; j < 8; j++) d = (d & 1) ? ((d >> 1) ^ 0xEDB88320u) : (d >> 1);
        crc32le_tab[i] = d;
        d = (uint32_t)i << 24;
        for (int j = 0; j < 8; j++) d = (d & 0x80000000u) ? ((d << 1) ^ 0x04C11DB7u) : (d << 1);
        crc32be_tab[i] = d;
    }
    crc_inited = 1;
}

uint8_t crc8_atm(uint8_t crc, const uint8_t *buf, size_t len)
{
    crc_init();
    for (size_t i = 0; i < len; i++) crc = crc8_tab[crc ^ buf[i]];
    return crc;
}

uint16_t crc16_ansi(uint16_t crc, const uint8_t *buf, size_t len)
{
    crc_init();
    for (size_t i = 0; i < len; i++) crc = (uint16_t)((crc << 8) ^ crc16_tab[((crc >> 8) ^ buf[i]) & 0xff]);
    return crc;
}

uint32_t crc32_ieee_le(uint32_t crc, const uint8_t *buf, size_t len)
{
    crc_init();
    for (size_t i = 0; i < len; i++) crc = crc32le_tab[(crc ^ buf[i]) & 0xff] ^ (crc >> 8);
    return crc;
}

uint32_t crc32_ieee(uint32_t crc, const uint8_t *buf, size_t len)
{
    crc_init();
    for (size_t i = 0; i < len; i++) crc = (crc << 8) ^ crc32be_tab[((crc >> 24) ^ buf[i]) & 0xff];
    return crc;
}

uint32_t adler32_update(uint32_t adler, const uint8_t *buf, size_t len)
{
    uint32_t s1 = adler & 0xffff, s2 = adler >> 16;
    for (size_t i = 0; i < len; i++) {
        s1 += buf[i];
        if (s1 >= 65521) s1 -= 65521;
        s2 += s1;
        if (s2 >= 65521) s2 -= 65521;
    }
    return (s2 << 16) | s1;
}

/* ---------- MD5 ---------- */
static const uint32_t md5_T[64] = {
    0xd76aa478,0xe8c7b756,0x242070db,0xc1bdceee,0xf57c0faf,0x4787c62a,0xa8304613,0xfd469501,
    0x698098d8,0x8b44f7af,0xffff5bb1,0x895cd7be,0x6b901122,0xfd987193,0xa679438e,0x49b40821,
    0xf61e2562,0xc040b340,0x265e5a51,0xe9b6c7aa,0xd62f105d,0x02441453,0xd8a1e681,0xe7d3fbc8,
    0x21e1cde6,0xc33707d6,0xf4d50d87,0x455a14ed,0xa9e3e905,0xfcefa3f8,0x676f02d9,0x8d2a4c8a,
    0xfffa3942,0x8771f681,0x6d9d6122,0xfde5380c,0xa4beea44,0x4bdecfa9,0xf6bb4b60,0xbebfbc70,
    0x289b7ec6,0xeaa127fa,0xd4ef3085,0x04881d05,0xd9d4d039,0xe6db99e5,0x1fa27cf8,0xc4ac5665,
    0xf4292244,0x432aff97,0xab9423a7,0xfc93a039,0x655b59c3,0x8f0ccc92,0xffeff47d,0x85845dd1,
    0x6fa87e4f,0xfe2ce6e0,0xa3014314,0x4e0811a1,0xf7537e82,0xbd3af235,0x2ad7d2bb,0xeb86d391 };
static const uint8_t md5_S[64] = {
    7,12,17,22,7,12,17,22,7,12,17,22,7,12,17,22,
    5,9,14,20,5,9,14,20,5,9,14,20,5,9,14,20,
    4,11,16,23,4,11,16,23,4,11,16,23,4,11,16,23,
    6,10,15,21,6,10,15,21,6,10,15,21,6,10,15,21 };

#define ROL32(x,n) (((x) << (n)) | ((x) >> (32 - (n))))

static void md5_body(uint32_t ABCD[4], const uint8_t *src)
{
    uint32_t X[16];
    for (int i = 0; i < 16; i++)
        X[i] = src[i*4] | (src[i*4+1] << 8) | (src[i*4+2] << 16) | ((uint32_t)src[i*4+3] << 24);
    uint32_t a = ABCD[0], b = ABCD[1], c = ABCD[2], d = ABCD[3];
    for (int i = 0; i < 64; i++) {
        uint32_t f; int g;
        if (i < 16) { f = (b & c) | (~b & d); g = i; }
        else if (i < 32) { f = (d & b) | (~d & c); g = (5*i + 1) & 15; }
        else if (i < 48) { f = b ^ c ^ d; g = (3*i + 5) & 15; }
        else { f = c ^ (b | ~d); g = (7*i) & 15; }
        uint32_t t = d; d = c; c = b;
        uint32_t x = a + f + md5_T[i] + X[g];
        b = b + ROL32(x, md5_S[i]);
        a = t;
    }
    ABCD[0] += a; ABCD[1] += b; ABCD[2] += c; ABCD[3] += d;
}

void md5_init(MD5Ctx *c)
{
    c->len = 0;
    c->ABCD[0] = 0x67452301; c->ABCD[1] = 0xefcdab89;
    c->ABCD[2] = 0x98badcfe; c->ABCD[3] = 0x10325476;
}

void md5_update(MD5Ctx *c, const uint8_t *src, size_t len)
{
    size_t j = c->len & 63;
    c->len += len;
    while (len > 0) {
        size_t n = 64 - j;
        if (n > len) n = len;
        memcpy(c->block + j, src, n);
        j += n; src += n; len -= n;
        if (j == 64) { md5_body(c->ABCD, c->block); j = 0; }
    }
}

void md5_final(MD5Ctx *c, uint8_t *dst)
{
    uint64_t finalcount = c->len << 3;
    uint8_t pad = 0x80;
    md5_update(c, &pad, 1);
    pad = 0;
    while ((c->len & 63) != 56) md5_update(c, &pad, 1);
    uint8_t lb[8];
    for (int i = 0; i < 8; i++) lb[i] = (uint8_t)(finalcount >> (8*i));
    md5_update(c, lb, 8);
    for (int i = 0; i < 4; i++)
        for (int k = 0; k < 4; k++) dst[i*4+k] = (uint8_t)(c->ABCD[i] >> (8*k));
}

