    if (bits == 160 || bits == 320) {
        uint32_t al, bl, cl, dl, el, ar, br, cr, dr, er, t;
        if (bits == 160) {
            al = ar = h[0]; bl = br = h[1]; cl = cr = h[2]; dl = dr = h[3]; el = er = h[4];
        } else {
            al = h[0]; bl = h[1]; cl = h[2]; dl = h[3]; el = h[4];
            ar = h[5]; br = h[6]; cr = h[7]; dr = h[8]; er = h[9];
        }
        for (int j = 0; j < 80; j++) {
            t = ROL32(al + rmd_f(j, bl, cl, dl) + X[rmd_r[j]] + rmd_K[j/16], rmd_s[j]) + el;
            al = el; el = dl; dl = ROL32(cl, 10); cl = bl; bl = t;
            t = ROL32(ar + rmd_f(79 - j, br, cr, dr) + X[rmd_rp[j]] + rmd_Kp160[j/16], rmd_sp[j]) + er;
            ar = er; er = dr; dr = ROL32(cr, 10); cr = br; br = t;
            if (bits == 320) {
                if (j == 15) { t = bl; bl = br; br = t; }
                else if (j == 31) { t = dl; dl = dr; dr = t; }
                else if (j == 47) { t = al; al = ar; ar = t; }
                else if (j == 63) { t = cl; cl = cr; cr = t; }
                else if (j == 79) { t = el; el = er; er = t; }
            }
        }
        if (bits == 160) {
            t = h[1] + cl + dr;
            h[1] = h[2] + dl + er;
            h[2] = h[3] + el + ar;
            h[3] = h[4] + al + br;
            h[4] = h[0] + bl + cr;
            h[0] = t;
        } else {
            h[0] += al; h[1] += bl; h[2] += cl; h[3] += dl; h[4] += el;
            h[5] += ar; h[6] += br; h[7] += cr; h[8] += dr; h[9] += er;
        }
    } else {
        uint32_t al, bl, cl, dl, ar, br, cr, dr, t;
        if (bits == 128) {
            al = ar = h[0]; bl = br = h[1]; cl = cr = h[2]; dl = dr = h[3];
        } else {
            al = h[0]; bl = h[1]; cl = h[2]; dl = h[3];
            ar = h[4]; br = h[5]; cr = h[6]; dr = h[7];
        }
        for (int j = 0; j < 64; j++) {
            t = ROL32(al + rmd_f(j, bl, cl, dl) + X[rmd_r[j]] + rmd_K[j/16], rmd_s[j]);
            al = dl; dl = cl; cl = bl; bl = t;
            t = ROL32(ar + rmd_f(63 - j, br, cr, dr) + X[rmd_rp[j]] + rmd_Kp128[j/16], rmd_sp[j]);
            ar = dr; dr = cr; cr = br; br = t;
            if (bits == 256) {
                if (j == 15) { t = al; al = ar; ar = t; }
                else if (j == 31) { t = bl; bl = br; br = t; }
                else if (j == 47) { t = cl; cl = cr; cr = t; }
                else if (j == 63) { t = dl; dl = dr; dr = t; }
            }
        }
        if (bits == 128) {
            t = h[1] + cl + dr;
            h[1] = h[2] + dl + ar;
            h[2] = h[3] + al + br;
            h[3] = h[0] + bl + cr;
            h[0] = t;
        } else {
            h[0] += al; h[1] += bl; h[2] += cl; h[3] += dl;
            h[4] += ar; h[5] += br; h[6] += cr; h[7] += dr;
        }
    }
