/* ---------- murmur3 (x64 128) ---------- */
typedef struct { uint64_t h1, h2; uint8_t buf[16]; int buf_len; uint64_t total; } Murmur3Ctx;

static uint64_t fmix64(uint64_t k)
{
    k ^= k >> 33; k *= 0xff51afd7ed558ccdULL; k ^= k >> 33; k *= 0xc4ceb9fe1a85ec53ULL; k ^= k >> 33;
    return k;
}
#define ROL64(x,n) (((x) << (n)) | ((x) >> (64 - (n))))
static const uint64_t mm_c1 = 0x87c37b91114253d5ULL, mm_c2 = 0x4cf5ad432745937fULL;
static uint64_t rd64le(const uint8_t *p) { uint64_t v = 0; for (int i = 7; i >= 0; i--) v = (v << 8) | p[i]; return v; }
static void murmur3_block(Murmur3Ctx *c, const uint8_t *p)
{
    uint64_t k1 = rd64le(p), k2 = rd64le(p + 8);
    k1 *= mm_c1; k1 = ROL64(k1, 31); k1 *= mm_c2; c->h1 ^= k1;
    c->h1 = ROL64(c->h1, 27); c->h1 += c->h2; c->h1 = c->h1 * 5 + 0x52dce729;
    k2 *= mm_c2; k2 = ROL64(k2, 33); k2 *= mm_c1; c->h2 ^= k2;
    c->h2 = ROL64(c->h2, 31); c->h2 += c->h1; c->h2 = c->h2 * 5 + 0x38495ab5;
}

