    case H_RMD128: rmd_block(h->h32, p, 128); break;
    case H_RMD160: rmd_block(h->h32, p, 160); break;
    case H_RMD256: rmd_block(h->h32, p, 256); break;
    case H_RMD320: rmd_block(h->h32, p, 320); break;
    case H_SHA160: sha1_block(h->h32, p); break;
    case H_SHA224: case H_SHA256: sha256_block(h->h32, p); break;
    default: sha512_block(h->h64, p); break;
    }
}

void hash_update(HashCtx *h, const uint8_t *data, size_t len)
{
    switch (h->type) {
    case H_MD5: md5_update(&h->md5, data, len); return;
    case H_CRC32: h->crc = crc32_ieee_le(h->crc, data, len); return;
    case H_ADLER32: h->crc = adler32_update(h->crc, data, len); return;
    case H_MURMUR3:
        h->mm.total += len;
        while (len > 0) {
            int n = 16 - h->mm.buf_len;
            if ((size_t)n > len) n = (int)len;
            memcpy(h->mm.buf + h->mm.buf_len, data, n);
            h->mm.buf_len += n; data += n; len -= n;
            if (h->mm.buf_len == 16) { murmur3_block(&h->mm, h->mm.buf); h->mm.buf_len = 0; }
        }
        return;
    }
    int bs = blocksize_of(h->type);
    h->total += len;
    while (len > 0) {
        int n = bs - h->buf_len;
        if ((size_t)n > len) n = (int)len;
        memcpy(h->buf + h->buf_len, data, n);
        h->buf_len += n; data += n; len -= n;
        if (h->buf_len == bs) { do_block(h, h->buf); h->buf_len = 0; }
    }
}

