        if (n > 8) { for (int i = n - 1; i >= 8; i--) k2 = (k2 << 8) | tail[i]; }
        for (int i = (n > 8 ? 8 : n) - 1; i >= 0; i--) k1 = (k1 << 8) | tail[i];
        if (n > 8) { k2 *= mm_c2; k2 = ROL64(k2, 33); k2 *= mm_c1; c->h2 ^= k2; }
        if (n > 0) { k1 *= mm_c1; k1 = ROL64(k1, 31); k1 *= mm_c2; c->h1 ^= k1; }
