        c->h1 += c->h2; c->h2 += c->h1;
        c->h1 = fmix64(c->h1); c->h2 = fmix64(c->h2);
        c->h1 += c->h2; c->h2 += c->h1;
        for (int i = 0; i < 8; i++) { res[i] = (uint8_t)(c->h1 >> (8*i)); res[8+i] = (uint8_t)(c->h2 >> (8*i)); }
