        int bs = blocksize_of(h->type);
        int lenbytes = bs == 128 ? 16 : 8;
        uint64_t bits = h->total * 8;
        uint8_t pad[256];
        int padlen = bs - h->buf_len;
        if (padlen < 1 + lenbytes) padlen += bs;
