        hash_update(h, pad, padlen);
        h->total = save_total;
        if (h->type >= H_RMD128 && h->type <= H_RMD320) {
            for (int i = 0; i < size / 4; i++)
                for (int k = 0; k < 4; k++) res[i*4+k] = (uint8_t)(h->h32[i] >> (8*k));
