#include "common.h"

void init_put_bits(PutBitContext *s, uint8_t *buffer, int size)
{
    s->buf = buffer;
    s->buf_end = buffer + size;
    s->buf_ptr = buffer;
    s->bit_buf = 0;
    s->bit_left = 64;
}

static inline void flush_word(PutBitContext *s)
{
    uint64_t v = s->bit_buf;
    for (int i = 7; i >= 0; i--) {
        if (s->buf_ptr < s->buf_end)
            *s->buf_ptr = (uint8_t)(v >> (i * 8));
        s->buf_ptr++;
    }
}

void put_bits64(PutBitContext *s, int n, uint64_t value)
{
    if (n == 0) return;
    if (n < 64) value &= (UINT64_C(1) << n) - 1;
    if (n < s->bit_left) {
        s->bit_buf = (s->bit_buf << n) | value;
        s->bit_left -= n;
    } else {
        int rem = n - s->bit_left;
        uint64_t bb;
        if (s->bit_left == 64) bb = 0; else bb = s->bit_buf << s->bit_left;
        bb |= (rem ? (value >> rem) : value);
        s->bit_buf = bb;
        flush_word(s);
        s->bit_buf = rem ? (value & ((UINT64_C(1) << rem) - 1)) : 0;
        s->bit_left = 64 - rem;
    }
}

void put_bits(PutBitContext *s, int n, uint32_t value)
{
    put_bits64(s, n, value);
}

void put_sbits(PutBitContext *s, int n, int32_t value)
{
    put_bits64(s, n, (uint64_t)(uint32_t)value & (n >= 32 ? 0xFFFFFFFFu : ((1u << n) - 1)));
}

int put_bits_count(const PutBitContext *s)
{
    return (int)((s->buf_ptr - s->buf) * 8 + 64 - s->bit_left);
}

void flush_put_bits(PutBitContext *s)
{
    int bits = 64 - s->bit_left;
    uint64_t v = s->bit_buf;
    if (bits == 0) return;
    /* align left */
    v <<= s->bit_left;
    while (bits > 0) {
        if (s->buf_ptr < s->buf_end)
            *s->buf_ptr = (uint8_t)(v >> 56);
        s->buf_ptr++;
        v <<= 8;
        bits -= 8;
    }
    s->bit_buf = 0;
    s->bit_left = 64;
}

int put_bytes_output(const PutBitContext *s)
{
    return (int)(s->buf_ptr - s->buf);
}
