static uint32_t rmd_f(int j, uint32_t x, uint32_t y, uint32_t z)
{
    switch (j / 16) {
    case 0: return x ^ y ^ z;
    case 1: return (x & y) | (~x & z);
    case 2: return (x | ~y) ^ z;
    case 3: return (x & z) | (y & ~z);
    default: return x ^ (y | ~z);
    }
}
static const uint32_t rmd_K[5] = {0x00000000,0x5A827999,0x6ED9EBA1,0x8F1BBCDC,0xA953FD4E};
static const uint32_t rmd_Kp160[5] = {0x50A28BE6,0x5C4DD124,0x6D703EF3,0x7A6D76E9,0x00000000};
static const uint32_t rmd_Kp128[4] = {0x50A28BE6,0x5C4DD124,0x6D703EF3,0x00000000};

static void rmd_block(uint32_t *h, const uint8_t *p, int bits)
{
    uint32_t X[16];
    for (int i = 0; i < 16; i++)
        X[i] = p[i*4] | (p[i*4+1] << 8) | (p[i*4+2] << 16) | ((uint32_t)p[i*4+3] << 24);
    if (bits == 160 || bits == 320) {
        uint32_t al, bl, cl, dl, el, ar, br, cr, dr, er, t;
        if (bits == 160) {
            al = ar = h[0]; bl = br = h[1]; cl = cr = h[2]; dl = dr = h[3]; el = er = h[4];
        } else {
            al = h[0]; bl = h[1]; cl = h[2]; dl = h[3]; el = h[4];
            ar = h[5]; br = h[6]; cr = h[7]; dr = h[8]; er = h[9];
        }
        for (int j = 0; j < 80; j++) {
            t = ROL32(al + rmd_f(j, bl, cl, dl) + X[rmd_r[j]] + rmd_K[j/16], rmd_s[j]) + el;
            al = el; el = dl; dl = ROL32(cl, 10); cl = bl; bl = t;
            t = ROL32(ar + rmd_f(79 - j, br, cr, dr) + X[rmd_rp[j]] + rmd_Kp160[j/16], rmd_sp[j]) + er;
            ar = er; er = dr; dr = ROL32(cr, 10); cr = br; br = t;
            if (bits == 320) {
                if (j == 15) { t = bl; bl = br; br = t; }
                else if (j == 31) { t = dl; dl = dr; dr = t; }
                else if (j == 47) { t = al; al = ar; ar = t; }
                else if (j == 63) { t = cl; cl = cr; cr = t; }
                else if (j == 79) { t = el; el = er; er = t; }
            }
        }
        if (bits == 160) {
            t = h[1] + cl + dr;
            h[1] = h[2] + dl + er;
            h[2] = h[3] + el + ar;
            h[3] = h[4] + al + br;
            h[4] = h[0] + bl + cr;
            h[0] = t;
        } else {
            h[0] += al; h[1] += bl; h[2] += cl; h[3] += dl; h[4] += el;
            h[5] += ar; h[6] += br; h[7] += cr; h[8] += dr; h[9] += er;
        }
    } else {
        uint32_t al, bl, cl, dl, ar, br, cr, dr, t;
        if (bits == 128) {
            al = ar = h[0]; bl = br = h[1]; cl = cr = h[2]; dl = dr = h[3];
        } else {
            al = h[0]; bl = h[1]; cl = h[2]; dl = h[3];
            ar = h[4]; br = h[5]; cr = h[6]; dr = h[7];
        }
        for (int j = 0; j < 64; j++) {
            t = ROL32(al + rmd_f(j, bl, cl, dl) + X[rmd_r[j]] + rmd_K[j/16], rmd_s[j]);
            al = dl; dl = cl; cl = bl; bl = t;
            t = ROL32(ar + rmd_f(63 - j, br, cr, dr) + X[rmd_rp[j]] + rmd_Kp128[j/16], rmd_sp[j]);
            ar = dr; dr = cr; cr = br; br = t;
            if (bits == 256) {
                if (j == 15) { t = al; al = ar; ar = t; }
                else if (j == 31) { t = bl; bl = br; br = t; }
                else if (j == 47) { t = cl; cl = cr; cr = t; }
                else if (j == 63) { t = dl; dl = dr; dr = t; }
            }
        }
        if (bits == 128) {
            t = h[1] + cl + dr;
            h[1] = h[2] + dl + ar;
            h[2] = h[3] + al + br;
            h[3] = h[0] + bl + cr;
            h[0] = t;
        } else {
            h[0] += al; h[1] += bl; h[2] += cl; h[3] += dl;
            h[4] += ar; h[5] += br; h[6] += cr; h[7] += dr;
        }
    }
}

/* ---------- murmur3 (x64 128) ---------- */
typedef struct { uint64_t h1, h2; uint8_t buf[16]; int buf_len; uint64_t total; } Murmur3Ctx;

static uint64_t fmix64(uint64_t k)
{
    k ^= k >> 33; k *= 0xff51afd7ed558ccdULL; k ^= k >> 33; k *= 0xc4ceb9fe1a85ec53ULL; k ^= k >> 33;
    return k;
}
#define ROL64(x,n) (((x) << (n)) | ((x) >> (64 - (n))))
static const uint64_t mm_c1 = 0x87c37b91114253d5ULL, mm_c2 = 0x4cf5ad432745937fULL;
static uint64_t rd64le(const uint8_t *p) { uint64_t v = 0; for (int i = 7; i >= 0; i--) v = (v << 8) | p[i]; return v; }
static void murmur3_block(Murmur3Ctx *c, const uint8_t *p)
{
    uint64_t k1 = rd64le(p), k2 = rd64le(p + 8);
    k1 *= mm_c1; k1 = ROL64(k1, 31); k1 *= mm_c2; c->h1 ^= k1;
    c->h1 = ROL64(c->h1, 27); c->h1 += c->h2; c->h1 = c->h1 * 5 + 0x52dce729;
    k2 *= mm_c2; k2 = ROL64(k2, 33); k2 *= mm_c1; c->h2 ^= k2;
    c->h2 = ROL64(c->h2, 31); c->h2 += c->h1; c->h2 = c->h2 * 5 + 0x38495ab5;
}

