static int blocksize_of(int type)
{
    if (type == H_SHA512_224 || type == H_SHA512_256 || type == H_SHA384 || type == H_SHA512) return 128;
    return 64;
}

static void do_block(HashCtx *h, const uint8_t *p)
{
    switch (h->type) {
    case H_RMD128: rmd_block(h->h32, p, 128); break;
    case H_RMD160: rmd_block(h->h32, p, 160); break;
    case H_RMD256: rmd_block(h->h32, p, 256); break;
    case H_RMD320: rmd_block(h->h32, p, 320); break;
    case H_SHA160: sha1_block(h->h32, p); break;
    case H_SHA224: case H_SHA256: sha256_block(h->h32, p); break;
    default: sha512_block(h->h64, p); break;
    }
}

void hash_update(HashCtx *h, const uint8_t *data, size_t len)
{
    switch (h->type) {
    case H_MD5: md5_update(&h->md5, data, len); return;
    case H_CRC32: h->crc = crc32_ieee_le(h->crc, data, len); return;
    case H_ADLER32: h->crc = adler32_update(h->crc, data, len); return;
    case H_MURMUR3:
        h->mm.total += len;
        while (len > 0) {
            int n = 16 - h->mm.buf_len;
            if ((size_t)n > len) n = (int)len;
            memcpy(h->mm.buf + h->mm.buf_len, data, n);
            h->mm.buf_len += n; data += n; len -= n;
            if (h->mm.buf_len == 16) { murmur3_block(&h->mm, h->mm.buf); h->mm.buf_len = 0; }
        }
        return;
    }
    int bs = blocksize_of(h->type);
    h->total += len;
    while (len > 0) {
        int n = bs - h->buf_len;
        if ((size_t)n > len) n = (int)len;
        memcpy(h->buf + h->buf_len, data, n);
        h->buf_len += n; data += n; len -= n;
        if (h->buf_len == bs) { do_block(h, h->buf); h->buf_len = 0; }
    }
}

void hash_final_hex(HashCtx *h, char *out)
{
    uint8_t res[64];
    int size = hash_size(h);
    switch (h->type) {
    case H_MD5: md5_final(&h->md5, res); break;
    case H_CRC32: {
        uint32_t v = h->crc ^ 0; /* ffmpeg outputs crc as big endian of state without final xor? */
        v = ~h->crc;
        res[0] = v >> 24; res[1] = v >> 16; res[2] = v >> 8; res[3] = v;
        break; }
    case H_ADLER32: {
        uint32_t v = h->crc;
        res[0] = v >> 24; res[1] = v >> 16; res[2] = v >> 8; res[3] = v;
        break; }
    case H_MURMUR3: {
        Murmur3Ctx *c = &h->mm;
        uint64_t k1 = 0, k2 = 0;
        uint8_t *tail = c->buf;
        int n = c->buf_len;
        if (n > 8) { for (int i = n - 1; i >= 8; i--) k2 = (k2 << 8) | tail[i]; }
        for (int i = (n > 8 ? 8 : n) - 1; i >= 0; i--) k1 = (k1 << 8) | tail[i];
        if (n > 8) { k2 *= mm_c2; k2 = ROL64(k2, 33); k2 *= mm_c1; c->h2 ^= k2; }
        if (n > 0) { k1 *= mm_c1; k1 = ROL64(k1, 31); k1 *= mm_c2; c->h1 ^= k1; }
        c->h1 ^= c->total; c->h2 ^= c->total;
        c->h1 += c->h2; c->h2 += c->h1;
        c->h1 = fmix64(c->h1); c->h2 = fmix64(c->h2);
        c->h1 += c->h2; c->h2 += c->h1;
        for (int i = 0; i < 8; i++) { res[i] = (uint8_t)(c->h1 >> (8*i)); res[8+i] = (uint8_t)(c->h2 >> (8*i)); }
        break; }
    default: {
        int bs = blocksize_of(h->type);
        int lenbytes = bs == 128 ? 16 : 8;
        uint64_t bits = h->total * 8;
        uint8_t pad[256];
        int padlen = bs - h->buf_len;
