#include "lpc.h"

#define MAX_VARS 32
#define MAX_VARS_ALIGN 36

typedef struct LLSModel {
    double covariance[MAX_VARS_ALIGN][MAX_VARS_ALIGN];
    double coeff[MAX_VARS][MAX_VARS];
    double variance[MAX_VARS];
    int indep_count;
} LLSModel;

static void init_lls(LLSModel *m, int indep_count)
{
    memset(m, 0, sizeof(*m));
    m->indep_count = indep_count;
}

static void update_lls(LLSModel *m, const double *var)
{
    for (int i = 0; i <= m->indep_count; i++)
        for (int j = i; j <= m->indep_count; j++)
            m->covariance[i][j] += var[i] * var[j];
}

static double evaluate_lls(LLSModel *m, const double *param, int order)
{
    double out = 0;
    for (int i = 0; i <= order; i++)
        out += param[i] * m->coeff[order][i];
    return out;
}

static void solve_lls(LLSModel *m, double threshold, unsigned short min_order)
{
    int i, j, k;
    double (*factor)[MAX_VARS_ALIGN] = (void *)&m->covariance[1][0];
    double (*covar)[MAX_VARS_ALIGN] = (void *)&m->covariance[1][1];
    double *covar_y = m->covariance[0];
    int count = m->indep_count;

    for (i = 0; i < count; i++) {
        for (j = i; j < count; j++) {
            double sum = covar[i][j];
            for (k = 0; k <= i - 1; k++)
                sum -= factor[i][k] * factor[j][k];
            if (i == j) {
                if (sum < threshold)
                    sum = 1.0;
                factor[i][i] = sqrt(sum);
            } else {
                factor[j][i] = sum / factor[i][i];
            }
        }
    }

    for (i = 0; i < count; i++) {
        double sum = covar_y[i + 1];
        for (k = 0; k <= i - 1; k++)
            sum -= factor[i][k] * m->coeff[0][k];
        m->coeff[0][i] = sum / factor[i][i];
    }

    for (j = count - 1; j >= min_order; j--) {
        for (i = j; i >= 0; i--) {
            double sum = m->coeff[0][i];
            for (k = i + 1; k <= j; k++)
                sum -= factor[k][i] * m->coeff[j][k];
            m->coeff[j][i] = sum / factor[i][i];
        }
        m->variance[j] = covar_y[0];
        for (i = 0; i <= j; i++) {
            double sum = m->coeff[j][i] * covar[i][i] - 2 * covar_y[i + 1];
            for (k = 0; k < i; k++)
                sum += 2 * m->coeff[j][k] * covar[k][i];
            m->variance[j] += m->coeff[j][i] * sum;
        }
    }
}

static void apply_welch_window(const int32_t *data, int len, double *w_data)
{
    int i, n2;
    double w, c;

    if (len == 1) {
        w_data[0] = 0.0;
        return;
    }
    n2 = len >> 1;
    c = 2.0 / (len - 1.0);

    if (len & 1) {
        for (i = 0; i < n2; i++) {
            w = c * i - 1.0;
            w = 1.0 - (w * w);
            w_data[i] = data[i] * w;
            w_data[len - 1 - i] = data[len - 1 - i] * w;
        }
        w_data[n2] = data[n2];
        return;
    }

    w_data += n2;
    data += n2;
    for (i = 0; i < n2; i++) {
        w = c * (i + 0.5);
        w = 1.0 - (w * w);
        w_data[-i - 1] = data[-i - 1] * w;
        w_data[+i] = data[+i] * w;
    }
}

static void compute_autocorr(const double *data, int len, int lag, double *autoc)
{
    int i, j;
    for (j = 0; j < lag; j += 2) {
        double sum0 = 1.0, sum1 = 1.0;
        for (i = j; i < len; i++) {
            sum0 += data[i] * data[i - j];
            sum1 += data[i] * data[i - j - 1];
        }
        autoc[j] = sum0;
        autoc[j + 1] = sum1;
    }
    if (j == lag) {
        double sum = 1.0;
        for (i = j - 1; i < len; i += 2) {
            sum += data[i] * data[i - j] + data[i + 1] * data[i - j + 1];
        }
        autoc[j] = sum;
    }
}

static int compute_lpc_coefs(const double *autoc, int max_order, double *lpc, int lpc_stride)
{
    int i, j;
    double err;
    double *lpc_last = lpc;

    err = *autoc++;
    for (i = 0; i < max_order; i++) {
        double r = -autoc[i];
        for (j = 0; j < i; j++)
            r -= lpc_last[j] * autoc[i - j - 1];
        if (err)
            r /= err;
        err *= 1.0 - (r * r);

        lpc[i] = r;
        for (j = 0; j < (i + 1) >> 1; j++) {
            double f = lpc_last[j];
            double b = lpc_last[i - 1 - j];
            lpc[j] = f + r * b;
            lpc[i - 1 - j] = b + r * f;
        }
        lpc_last = lpc;
        lpc += lpc_stride;
    }
    return 0;
}

static void quantize_lpc_coefs(double *lpc_in, int order, int precision, int32_t *lpc_out,
                               int *shift, int min_shift, int max_shift, int zero_shift)
{
    int i;
    double cmax, error;
    int32_t qmax;
    int sh;

    qmax = (1 << (precision - 1)) - 1;

    cmax = 0.0;
    for (i = 0; i < order; i++)
        cmax = FFMAX(cmax, fabs(lpc_in[i]));

    if (cmax * (1 << max_shift) < 1.0) {
        *shift = zero_shift;
        memset(lpc_out, 0, sizeof(int32_t) * order);
        return;
    }

    sh = max_shift;
    while ((cmax * (1 << sh) > qmax) && (sh > min_shift))
        sh--;

    if (sh == 0 && cmax > qmax) {
        double scale = ((double)qmax) / cmax;
        for (i = 0; i < order; i++)
            lpc_in[i] *= scale;
    }

    error = 0;
    for (i = 0; i < order; i++) {
        error -= lpc_in[i] * (1 << sh);
        lpc_out[i] = av_clip((int)lrintf((float)error), -qmax, qmax);
        error -= lpc_out[i];
    }
    *shift = sh;
}

static int estimate_best_order(double *ref, int min_order, int max_order)
{
    int i, est;
    est = min_order;
    for (i = max_order - 1; i >= min_order - 1; i--) {
        if (ref[i] > 0.10) {
            est = i + 1;
            break;
        }
    }
    return est;
}

int lpc_init(LPCContext *s, int blocksize, int max_order, enum FFLPCType lpc_type)
{
    s->blocksize = blocksize;
    s->max_order = max_order;
    s->lpc_type = lpc_type;
    int pad = (max_order + 3) & ~3;
    s->windowed_buffer = calloc(blocksize + 2 + pad + 8, sizeof(double));
    if (!s->windowed_buffer) return AVERROR(12);
    s->windowed_samples = s->windowed_buffer + pad;
    return 0;
}

void lpc_end(LPCContext *s)
{
    free(s->windowed_buffer);
    s->windowed_buffer = NULL;
}

int lpc_calc_coefs(LPCContext *s, const int32_t *samples, int blocksize, int min_order,
                   int max_order, int precision, int32_t coefs[][MAX_LPC_ORDER], int *shift,
                   enum FFLPCType lpc_type, int lpc_passes, int omethod,
                   int min_shift, int max_shift, int zero_shift)
{
    double autoc[MAX_LPC_ORDER + 1];
    double ref[MAX_LPC_ORDER] = { 0 };
    double lpc[MAX_LPC_ORDER][MAX_LPC_ORDER];
    int i, j, pass = 0;
    int opt_order;

    memset(lpc, 0, sizeof(lpc));
    if (blocksize != s->blocksize || max_order != s->max_order || lpc_type != s->lpc_type) {
        lpc_end(s);
        lpc_init(s, blocksize, max_order, lpc_type);
    }

    if (lpc_passes <= 0)
        lpc_passes = 2;

    if (lpc_type == FF_LPC_TYPE_LEVINSON || (lpc_type == FF_LPC_TYPE_CHOLESKY && lpc_passes > 1)) {
        apply_welch_window(samples, blocksize, s->windowed_samples);
        compute_autocorr(s->windowed_samples, blocksize, max_order, autoc);
        compute_lpc_coefs(autoc, max_order, &lpc[0][0], MAX_LPC_ORDER);
        for (i = 0; i < max_order; i++)
            ref[i] = fabs(lpc[i][i]);
        pass++;
    }

    if (lpc_type == FF_LPC_TYPE_CHOLESKY) {
        static LLSModel m[2];
        double var[MAX_LPC_ORDER + 4];
        double weight = 0;
        memset(var, 0, sizeof(var));

        for (j = 0; j < max_order; j++)
            m[0].coeff[max_order - 1][j] = -lpc[max_order - 1][j];

        for (; pass < lpc_passes; pass++) {
            init_lls(&m[pass & 1], max_order);
            weight = 0;
            for (i = max_order; i < blocksize; i++) {
                for (j = 0; j <= max_order; j++)
                    var[j] = samples[i - j];
                if (pass) {
                    double eval, inv, rinv;
                    eval = evaluate_lls(&m[(pass - 1) & 1], var + 1, max_order - 1);
                    eval = (512 >> pass) + fabs(eval - var[0]);
                    inv = 1 / eval;
                    rinv = sqrt(inv);
                    for (j = 0; j <= max_order; j++)
                        var[j] *= rinv;
                    weight += inv;
                } else
                    weight++;
                update_lls(&m[pass & 1], var);
            }
            solve_lls(&m[pass & 1], 0.001, 0);
        }

        for (i = 0; i < max_order; i++) {
            for (j = 0; j < max_order; j++)
                lpc[i][j] = -m[(pass - 1) & 1].coeff[i][j];
            ref[i] = sqrt(m[(pass - 1) & 1].variance[i] / weight) * (blocksize - max_order) / 4000;
        }
        for (i = max_order - 1; i > 0; i--)
            ref[i] = ref[i - 1] - ref[i];
    }

    opt_order = max_order;

    if (omethod == ORDER_METHOD_EST) {
        opt_order = estimate_best_order(ref, min_order, max_order);
        i = opt_order - 1;
        quantize_lpc_coefs(lpc[i], i + 1, precision, coefs[i], &shift[i], min_shift, max_shift, zero_shift);
    } else {
        for (i = min_order - 1; i < max_order; i++)
            quantize_lpc_coefs(lpc[i], i + 1, precision, coefs[i], &shift[i], min_shift, max_shift, zero_shift);
    }
    return opt_order;
}
