cat > log.c <<'EOF'
#include "common.h"
#include "log.h"
#include <stdarg.h>
#include <unistd.h>

int g_log_level = AV_LOG_INFO;
int g_log_flags = 1;
int g_log_to_stdout = 0;

static char prev_line[4096];
static int repeat_count;
static int print_prefix = 1;

static const char *level_name(int level)
{
    if (level <= AV_LOG_PANIC) return "panic";
    if (level <= AV_LOG_FATAL) return "fatal";
    if (level <= AV_LOG_ERROR) return "error";
    if (level <= AV_LOG_WARNING) return "warning";
    if (level <= AV_LOG_INFO) return "info";
    if (level <= AV_LOG_VERBOSE) return "verbose";
    if (level <= AV_LOG_DEBUG) return "debug";
    return "trace";
}

void log_flush_repeat(void)
{
    if (repeat_count > 0) {
        fprintf(stderr, "    Last message repeated %d times\n", repeat_count);
        repeat_count = 0;
    }
    prev_line[0] = 0;
}

static void format_ctx_prefix(char *buf, size_t sz, void *ctx, int level)
{
    buf[0] = 0;
    if (!ctx) {
        return;
    }
    const LogClass *cls = *(const LogClass **)ctx;
    void *parent = cls->parent ? cls->parent(ctx) : NULL;
    size_t len = 0;
    if (parent) {
        const LogClass *pcls = *(const LogClass **)parent;
        len += snprintf(buf + len, sz - len, "[%s @ %p] ", pcls->item_name ? pcls->item_name(parent) : pcls->class_name, parent);
    }
    snprintf(buf + len, sz - len, "[%s @ %p] ", cls->item_name ? cls->item_name(ctx) : cls->class_name, ctx);
    (void)level;
}

void av_vlog(void *ctx, int level, const char *fmt, va_list vl)
{
    char line[8192];
    char msg[8192];
    if (g_log_to_stdout) {
        vfprintf(stdout, fmt, vl);
        return;
    }
    if (level > g_log_level)
        return;
    vsnprintf(msg, sizeof(msg), fmt, vl);
    line[0] = 0;
    size_t len = 0;
    if (print_prefix) {
        format_ctx_prefix(line, sizeof(line), ctx, level);
        len = strlen(line);
        if (g_log_flags & 2)
            len += snprintf(line + len, sizeof(line) - len, "[%s] ", level_name(level));
    }
    snprintf(line + len, sizeof(line) - len, "%s", msg);
    size_t ml = strlen(msg);
    int ends_nl = ml > 0 && (msg[ml - 1] == '\n' || msg[ml - 1] == '\r');

    if (print_prefix && (g_log_flags & 1) && !strcmp(line, prev_line) && *line && line[strlen(line) - 1] != '\r') {
        repeat_count++;
        print_prefix = ends_nl;
        return;
    }
    if (repeat_count > 0) {
        fprintf(stderr, "    Last message repeated %d times\n", repeat_count);
        repeat_count = 0;
    }
    fputs(line, stderr);
    if (print_prefix) {
        snprintf(prev_line, sizeof(prev_line), "%s", line);
    } else {
        size_t pl = strlen(prev_line);
        snprintf(prev_line + pl, sizeof(prev_line) - pl, "%s", line);
    }
    print_prefix = ends_nl;
    if (!print_prefix) {
        /* partial line; keep in prev_line for comparison */
    }
}

void av_log(void *ctx, int level, const char *fmt, ...)
{
    va_list vl;
    va_start(vl, fmt);
    av_vlog(ctx, level, fmt, vl);
    va_end(vl);
}
EOF
