#include "../../workspace/src/flacenc.h"
#include "../../workspace/src/flac_common.h"
/* usage: enctest in.raw rate channels bits(16|24) out.flac [opt=val ...] */
int main(int argc, char **argv)
{
    FILE *f = fopen(argv[1], "rb");
    int rate = atoi(argv[2]), ch = atoi(argv[3]), bits = atoi(argv[4]);
    FlacEncOpts o; flacenc_default_opts(&o);
    int frame_size = 0;
    for (int i = 6; i < argc; i++) {
        char k[64]; int v;
        if (sscanf(argv[i], "%63[^=]=%d", k, &v) != 2) continue;
        if (!strcmp(k, "level")) o.compression_level = v;
        else if (!strcmp(k, "lpc_type")) o.lpc_type = v;
        else if (!strcmp(k, "lpc_passes")) o.lpc_passes = v;
        else if (!strcmp(k, "prec")) o.lpc_coeff_precision = v;
        else if (!strcmp(k, "minpo")) o.min_prediction_order = v;
        else if (!strcmp(k, "maxpo")) o.max_prediction_order = v;
        else if (!strcmp(k, "pom")) o.prediction_order_method = v;
        else if (!strcmp(k, "minpart")) o.min_partition_order = v;
        else if (!strcmp(k, "maxpart")) o.max_partition_order = v;
        else if (!strcmp(k, "ch_mode")) o.ch_mode = v;
        else if (!strcmp(k, "exact")) o.exact_rice_parameters = v;
        else if (!strcmp(k, "mdq")) o.multi_dim_quant = v;
        else if (!strcmp(k, "fs")) frame_size = v;
    }
    int bprs = bits;
    int err;
    FlacEncodeContext *s = flacenc_init(&o, rate, ch, bits > 16, &bprs, &frame_size, ch == 1 ? 4 : ch == 2 ? 3 : 0, 0, &err, NULL);
    if (!s) { fprintf(stderr, "init failed\n"); return 1; }
    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);
    uint8_t *data = malloc(sz); fread(data, 1, sz, f); fclose(f);
    int bps_in = bits > 16 ? 3 : 2;
    long total = sz / (bps_in * ch);
    FILE *o2 = fopen(argv[5], "wb");
    uint8_t hdr[34];
    fwrite("fLaC", 1, 4, o2);
    uint8_t bh[4] = {0, 0, 0, 34}; fwrite(bh, 1, 4, o2);
    long si_pos = ftell(o2);
    flacenc_get_header(s, hdr); fwrite(hdr, 1, 34, o2);
    const char *vendor = "Lavf62.9.101";
    const char *cm = "encoder=Lavf62.9.101";
    int vlen = 4 + strlen(vendor) + 4 + 4 + strlen(cm);
    uint8_t vb[4] = {4, vlen >> 16, vlen >> 8, vlen}; fwrite(vb, 1, 4, o2);
    uint32_t l = strlen(vendor); fwrite(&l, 4, 1, o2); fwrite(vendor, 1, l, o2);
    l = 1; fwrite(&l, 4, 1, o2); l = strlen(cm); fwrite(&l, 4, 1, o2); fwrite(cm, 1, l, o2);
    uint8_t pb[4] = {0x81, 0, 0x20, 0}; fwrite(pb, 1, 4, o2);
    uint8_t *zero = calloc(1, 8192); fwrite(zero, 1, 8192, o2);
    for (long pos = 0; pos < total; pos += frame_size) {
        int n = total - pos < frame_size ? total - pos : frame_size;
        void *buf;
        if (bits > 16) {
            int32_t *b = malloc(n * ch * 4);
            for (int i = 0; i < n * ch; i++) {
                uint8_t *p = data + (pos * ch + i) * 3;
                b[i] = (int32_t)((p[0] << 8) | (p[1] << 16) | ((uint32_t)p[2] << 24));
            }
            buf = b;
        } else {
            int16_t *b = malloc(n * ch * 2);
            memcpy(b, data + pos * ch * 2, n * ch * 2);
            buf = b;
        }
        uint8_t *out; int osz;
        flacenc_encode_frame(s, buf, n, &out, &osz);
        fwrite(out, 1, osz, o2);
        free(out); free(buf);
    }
    flacenc_finish(s, hdr);
    fseek(o2, si_pos, SEEK_SET); fwrite(hdr, 1, 34, o2);
    fclose(o2);
    return 0;
}
