#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#define MAXO 32
static int wmode, amode;
static void window(const int32_t *data, int len, double *w_data)
{
    int n2 = len >> 1; double c = 2.0 / (len - 1.0), w;
    if (wmode == 0) { // standard
        for (int i = 0; i < len; i++) { w = c * i - 1.0; w = 1.0 - w*w; w_data[i] = data[i] * w; }
    } else if (wmode == 1) { // literal c - n2 + i
        double *wd = w_data + n2; const int32_t *d = data + n2;
        for (int i = 0; i < n2; i++) { w = c - n2 + i; w = 1.0 - (w * w); wd[-i-1] = d[-i-1] * w; wd[i] = d[i] * w; }
    } else if (wmode == 2) { // half-sample
        double *wd = w_data + n2; const int32_t *d = data + n2;
        for (int i = 0; i < n2; i++) { w = c * (i + 0.5); w = 1.0 - (w * w); wd[-i-1] = d[-i-1] * w; wd[i] = d[i] * w; }
    } else if (wmode == 3) { // rectangular
        for (int i = 0; i < len; i++) w_data[i] = data[i];
    } else if (wmode == 4) { // welch with N
        for (int i = 0; i < len; i++) { w = (i - (len-1)/2.0) / (len/2.0); w = 1.0 - w*w; w_data[i] = data[i] * w; }
    } else if (wmode == 5) { // welch (N+1)
        for (int i = 0; i < len; i++) { w = (i - (len-1)/2.0) / ((len+1)/2.0); w = 1.0 - w*w; w_data[i] = data[i] * w; }
    }
}
static void autocorr(const double *data, int len, int lag, double *autoc)
{
    int i, j;
    if (amode == 0) {
        for (j = 0; j < lag; j += 2) {
            double sum0 = 1.0, sum1 = 1.0;
            for (i = j; i < len; i++) { sum0 += data[i] * data[i-j]; sum1 += data[i] * data[i-j-1]; }
            autoc[j] = sum0; autoc[j+1] = sum1;
        }
        if (j == lag) { double sum = 1.0; for (i = j-1; i < len; i += 2) sum += data[i]*data[i-j] + data[i+1]*data[i-j+1]; autoc[j] = sum; }
    } else if (amode == 1) { // plain from 0
        for (j = 0; j <= lag; j++) { double s = 0; for (i = j; i < len; i++) s += data[i]*data[i-j]; autoc[j] = s; }
    } else if (amode == 2) { // plain from 1.0
        for (j = 0; j <= lag; j++) { double s = 1.0; for (i = j; i < len; i++) s += data[i]*data[i-j]; autoc[j] = s; }
    }
}
static void levinson(const double *autoc, int max_order, double lpc[][MAXO])
{
    double err = autoc[0]; const double *ac = autoc + 1;
    double *last = lpc[0];
    for (int i = 0; i < max_order; i++) {
        double r = -ac[i];
        for (int j = 0; j < i; j++) r -= last[j] * ac[i-j-1];
        if (err) r /= err;
        err *= 1.0 - r*r;
        lpc[i][i] = r;
        for (int j = 0; j < (i+1)>>1; j++) { double f = last[j], b = last[i-1-j]; lpc[i][j] = f + r*b; lpc[i][i-1-j] = b + r*f; }
        last = lpc[i];
    }
}
static void quant(double *in, int order, int prec, int32_t *out, int *shift)
{
    int qmax = (1 << (prec-1)) - 1; double cmax = 0;
    for (int i = 0; i < order; i++) cmax = fmax(cmax, fabs(in[i]));
    int sh = 15;
    while (cmax * (1<<sh) > qmax && sh > 0) sh--;
    double err = 0;
    for (int i = 0; i < order; i++) { err -= in[i] * (1<<sh); out[i] = lrintf(err); if (out[i]>qmax) out[i]=qmax; if(out[i]<-qmax) out[i]=-qmax; err -= out[i]; }
    *shift = sh;
}
int main(int argc, char **argv)
{
    FILE *f = fopen(argv[1], "rb"); int order = atoi(argv[2]);
    wmode = atoi(argv[3]); amode = atoi(argv[4]);
    int16_t buf[100000]; int n = fread(buf, 2, 100000, f);
    if (argc > 5) n = atoi(argv[5]);
    int32_t smp[100000]; for (int i = 0; i < n; i++) smp[i] = buf[i];
    double *wb = calloc(n + 64, sizeof(double)), *wd = wb + 32;
    window(smp, n, wd);
    double ac[MAXO+1]; autocorr(wd, n, order, ac);
    double lpc[MAXO][MAXO]; memset(lpc, 0, sizeof(lpc));
    levinson(ac, order, lpc);
    int32_t q[MAXO]; int sh; quant(lpc[order-1], order, 15, q, &sh);
    printf("sh=%d [", sh); for (int i = 0; i < order; i++) printf("%d%s", q[i], i<order-1?", ":"]\n");
    return 0;
}
