#include "common.h"

/* 64-bit big-endian bit writer, behaves like a typical BitBuf=uint64 writer
 * (values are not masked, matching the reference behaviour for oversized values) */
void init_put_bits(PutBitContext *s, uint8_t *buffer, int size)
{
    s->buf = buffer;
    s->buf_end = buffer + size;
    s->buf_ptr = buffer;
    s->bit_buf = 0;
    s->bit_left = 64;
}

static inline void write_be64(PutBitContext *s, uint64_t v)
{
    if (s->buf_end - s->buf_ptr >= 8) {
        for (int i = 0; i < 8; i++)
            s->buf_ptr[i] = (uint8_t)(v >> (56 - 8 * i));
        s->buf_ptr += 8;
    }
}

void put_bits64(PutBitContext *s, int n, uint64_t value)
{
    uint64_t bit_buf = s->bit_buf;
    int bit_left = s->bit_left;
    if (n < bit_left) {
        bit_buf = (n == 64 ? 0 : (bit_buf << n)) | value;
        bit_left -= n;
    } else {
        bit_buf = bit_left == 64 ? 0 : (bit_buf << bit_left);
        bit_buf |= (n - bit_left) >= 64 ? 0 : (value >> (n - bit_left));
        write_be64(s, bit_buf);
        bit_left += 64 - n;
        bit_buf = value;
    }
    s->bit_buf = bit_buf;
    s->bit_left = bit_left;
}

void put_bits(PutBitContext *s, int n, uint32_t value)
{
    put_bits64(s, n, value);
}

/* signed value passed as int: sign-extended to 64 bits like the reference */
void put_bits_int(PutBitContext *s, int n, int value)
{
    put_bits64(s, n, (uint64_t)(int64_t)value);
}

void put_sbits(PutBitContext *s, int n, int32_t value)
{
    put_bits64(s, n, (uint64_t)(uint32_t)value & (n >= 32 ? 0xFFFFFFFFu : ((1u << n) - 1)));
}

int put_bits_count(const PutBitContext *s)
{
    return (int)((s->buf_ptr - s->buf) * 8 + 64 - s->bit_left);
}

void flush_put_bits(PutBitContext *s)
{
    if (s->bit_left < 64)
        s->bit_buf <<= s->bit_left;
    while (s->bit_left < 64) {
        if (s->buf_ptr < s->buf_end)
            *s->buf_ptr = (uint8_t)(s->bit_buf >> 56);
        s->buf_ptr++;
        s->bit_buf <<= 8;
        s->bit_left += 8;
    }
    s->bit_left = 64;
    s->bit_buf = 0;
}

int put_bytes_output(const PutBitContext *s)
{
    return (int)(s->buf_ptr - s->buf);
}
