    uint8_t c;
    if (avio_read(io, &c, 1) != 1) return 0;
    return c;
}
unsigned avio_rl16(AVIO *io) { unsigned v = avio_r8(io); v |= avio_r8(io) << 8; return v; }
unsigned avio_rl24(AVIO *io) { unsigned v = avio_rl16(io); v |= avio_r8(io) << 16; return v; }
unsigned avio_rl32(AVIO *io) { unsigned v = avio_rl16(io); v |= avio_rl16(io) << 16; return v; }
uint64_t avio_rl64(AVIO *io) { uint64_t v = avio_rl32(io); v |= (uint64_t)avio_rl32(io) << 32; return v; }
unsigned avio_rb16(AVIO *io) { unsigned v = avio_r8(io) << 8; v |= avio_r8(io); return v; }
unsigned avio_rb24(AVIO *io) { unsigned v = avio_rb16(io) << 8; v |= avio_r8(io); return v; }
unsigned avio_rb32(AVIO *io) { unsigned v = avio_rb16(io) << 16; v |= avio_rb16(io); return v; }
uint64_t avio_rb64(AVIO *io) { uint64_t v = (uint64_t)avio_rb32(io) << 32; v |= avio_rb32(io); return v; }

int64_t avio_tell(AVIO *io)
{
    if (io->write_flag) return io->write_pos;
    return io->buf_start + (int64_t)io->buf_pos;
}

int64_t avio_seek(AVIO *io, int64_t pos)
{
    int64_t cur = avio_tell(io);
    if (pos >= io->buf_start && pos <= io->buf_start + (int64_t)io->buf_len) {
        io->buf_pos = (size_t)(pos - io->buf_start);
        if (pos < io->buf_start + (int64_t)io->buf_len) io->eof_reached = io->eof_reached && 0;
        return pos;
    }
    if (pos > cur && !io->seekable) {
        avio_skip(io, pos - cur);
        return avio_tell(io);
    }
    if (!io->seekable) return -1;
    if (lseek(io->fd, pos, SEEK_SET) < 0) return -1;
    io->buf_start = pos;
    io->buf_pos = io->buf_len = 0;
    io->eof_reached = 0;
    return pos;
}

int64_t avio_skip(AVIO *io, int64_t n)
{
    if (n <= 0) {
        if (n < 0) return avio_seek(io, avio_tell(io) + n);
        return avio_tell(io);
    }
    int64_t target = avio_tell(io) + n;
    if (io->seekable && target > io->buf_start + (int64_t)io->buf_len)
        return avio_seek(io, target);
    uint8_t tmp[4096];
    while (n > 0) {
        int c = n > 4096 ? 4096 : (int)n;
        int r = avio_read(io, tmp, c);
        if (r <= 0) break;
        n -= r;
    }
    return avio_tell(io);
}

int64_t avio_size(AVIO *io)
{
    if (io->write_flag) {
        if (!io->seekable) return -1;
        return io->max_write_pos;
    }
    if (!io->seekable) return -1;
    return io->size_cache;
}

int avio_feof(AVIO *io)
{
    if (io->buf_pos < io->buf_len) return 0;
    if (!io->eof_reached) fill(io);
    return io->buf_pos >= io->buf_len && io->eof_reached;
}

void avio_flush(AVIO *io)
{
    if (!io->write_flag || !io->buf_len) return;
    size_t off = 0;
    while (off < io->buf_len) {
        ssize_t w = write(io->fd, io->buf + off, io->buf_len - off);
        if (w < 0) {
            if (errno == EINTR) continue;
            io->error = -errno;
            break;
        }
        off += w;
    }
    io->buf_len = 0;
}

void avio_write(AVIO *io, const uint8_t *src, int n)
{
    if (io->error) return;
    while (n > 0) {
        size_t space = io->buf_size - io->buf_len;
        size_t c = space < (size_t)n ? space : (size_t)n;
        memcpy(io->buf + io->buf_len, src, c);
        io->buf_len += c; src += c; n -= (int)c;
        io->write_pos += c;
        io->bytes_written += c;
        if (io->write_pos > io->max_write_pos) io->max_write_pos = io->write_pos;
        if (io->buf_len == io->buf_size) avio_flush(io);
    }
}

void avio_w8(AVIO *io, int v) { uint8_t c = v; avio_write(io, &c, 1); }
void avio_wl16(AVIO *io, unsigned v) { avio_w8(io, v); avio_w8(io, v >> 8); }
void avio_wl24(AVIO *io, unsigned v) { avio_wl16(io, v); avio_w8(io, v >> 16); }
void avio_wl32(AVIO *io, unsigned v) { avio_wl16(io, v); avio_wl16(io, v >> 16); }
void avio_wl64(AVIO *io, uint64_t v) { avio_wl32(io, (uint32_t)v); avio_wl32(io, (uint32_t)(v >> 32)); }
void avio_wb16(AVIO *io, unsigned v) { avio_w8(io, v >> 8); avio_w8(io, v); }
void avio_wb24(AVIO *io, unsigned v) { avio_w8(io, v >> 16); avio_wb16(io, v); }
void avio_wb32(AVIO *io, unsigned v) { avio_wb16(io, v >> 16); avio_wb16(io, v); }
void avio_wb64(AVIO *io, uint64_t v) { avio_wb32(io, (uint32_t)(v >> 32)); avio_wb32(io, (uint32_t)v); }

int64_t avio_wtell(AVIO *io) { return io->write_pos; }

int64_t avio_wseek(AVIO *io, int64_t pos)
{
    if (!io->seekable) return -1;
    avio_flush(io);
    if (lseek(io->fd, pos, SEEK_SET) < 0) return -1;
    io->write_pos = pos;
    return pos;
}

void avio_close(AVIO *io)
{
    if (!io) return;
    if (io->write_flag) avio_flush(io);
    if (!io->is_std) close(io->fd);
    free(io->buf);
    free(io);
}
