int chl_describe(const ChLayout *l, char *buf, int size)
{
    if (l->order == 1) {
        for (size_t i = 0; i < sizeof(std_layouts)/sizeof(std_layouts[0]); i++)
            if (std_layouts[i].mask == l->mask) {
                snprintf(buf, size, "%s", std_layouts[i].name);
                return 0;
            }
        int n = snprintf(buf, size, "%d channels (", l->nb_channels);
        int first = 1;
        for (int b = 0; b < 64; b++) {
            if (l->mask & (1ULL << b)) {
                n += snprintf(buf + n, size > n ? size - n : 0, "%s%s", first ? "" : "+", ch_names[b] ? ch_names[b] : "?");
                first = 0;
            }
        }
        snprintf(buf + n, size > n ? size - n : 0, ")");
        return 0;
    }
    snprintf(buf, size, "%d channels", l->nb_channels);
    return 0;
}

void chl_default(ChLayout *l, int n)
{
    static const uint64_t def[9] = { 0, FC, FL|FR, FL|FR|FC, FL|FR|FC|BC, FL|FR|FC|BL|BR,
                                     FL|FR|FC|LFE|BL|BR, FL|FR|FC|LFE|BC|SL|SR, FL|FR|FC|LFE|BL|BR|SL|SR };
    l->nb_channels = n;
    if (n >= 1 && n <= 8) { l->order = 1; l->mask = def[n]; }
    else { l->order = 0; l->mask = 0; }
}

int chl_from_string(ChLayout *l, const char *str)
{
    for (size_t i = 0; i < sizeof(std_layouts)/sizeof(std_layouts[0]); i++)
        if (!strcmp(std_layouts[i].name, str)) {
            l->order = 1; l->mask = std_layouts[i].mask;
            l->nb_channels = __builtin_popcountll(l->mask);
            return 0;
        }
    /* "Nc" or "N channels" */
    char *end;
    long n = strtol(str, &end, 10);
    if (end != str && n > 0 && n < 64) {
        if (!strcmp(end, "c")) { chl_default(l, (int)n); return 0; }
        if (!strcmp(end, " channels") || !*end) {
            if (!*end) { chl_default(l, (int)n); return 0; }
            l->order = 0; l->nb_channels = (int)n; l->mask = 0; return 0;
        }
    }
    /* channel names separated by + */
    uint64_t mask = 0;
    char tmp[256];
    snprintf(tmp, sizeof(tmp), "%s", str);
    char *save, *tok = strtok_r(tmp, "+|", &save);
    while (tok) {
        int found = 0;
        for (int b = 0; b < 64; b++)
            if (ch_names[b] && !strcmp(ch_names[b], tok)) { mask |= 1ULL << b; found = 1; break; }
        if (!found) return AVERROR(22);
        tok = strtok_r(NULL, "+|", &save);
    }
    if (!mask) return AVERROR(22);
    l->order = 1; l->mask = mask; l->nb_channels = __builtin_popcountll(mask);
    return 0;
}

int chl_equal(const ChLayout *a, const ChLayout *b)
{
    if (a->nb_channels != b->nb_channels || a->order != b->order) return 0;
    if (a->order == 1) return a->mask == b->mask;
    return 1;
}

int chl_channel_index(uint64_t mask, int bit)
{
    if (!(mask & (1ULL << bit))) return -1;
    return __builtin_popcountll(mask & ((1ULL << bit) - 1));
}

