        if (codecs[i].id == id) return &codecs[i];
    return NULL;
}
const CodecDesc *codec_desc_by_name(const char *name)
{
    for (size_t i = 0; i < sizeof(codecs)/sizeof(codecs[0]); i++)
        if (!strcmp(codecs[i].name, name)) return &codecs[i];
    return NULL;
}
int get_bits_per_sample(int id)
{
    const CodecDesc *d = codec_desc(id);
    if (!d || !d->is_pcm) return 0;
    if (id == CID_PCM_S24DAUD) return 24;
    return d->bits_per_sample;
