/* ---- dict ---- */
int dict_get_index(const Dict *d, const char *key)
{
    for (int i = 0; i < d->count; i++)
        if (!strcasecmp(d->e[i].key, key)) return i;
    return -1;
}
const char *dict_get(const Dict *d, const char *key)
{
    int i = dict_get_index(d, key);
    return i >= 0 ? d->e[i].value : NULL;
}
void dict_set(Dict *d, const char *key, const char *value)
{
    int i = dict_get_index(d, key);
    if (i >= 0) {
        free(d->e[i].value);
        if (!value) {
            free(d->e[i].key);
            memmove(&d->e[i], &d->e[i + 1], (d->count - i - 1) * sizeof(DictEntry));
            d->count--;
            return;
        }
        /* reference behaviour: old entry removed, new one appended at the end */
        free(d->e[i].key);
        memmove(&d->e[i], &d->e[i + 1], (d->count - i - 1) * sizeof(DictEntry));
        d->count--;
    }
    if (!value) return;
    d->e = realloc(d->e, (d->count + 1) * sizeof(DictEntry));
    d->e[d->count].key = av_strdup(key);
    d->e[d->count].value = av_strdup(value);
    d->count++;
}
void dict_set_append(Dict *d, const char *key, const char *value)
{
    d->e = realloc(d->e, (d->count + 1) * sizeof(DictEntry));
    d->e[d->count].key = av_strdup(key);
    d->e[d->count].value = av_strdup(value);
    d->count++;
}
void dict_free(Dict *d)
{
    for (int i = 0; i < d->count; i++) { free(d->e[i].key); free(d->e[i].value); }
    free(d->e);
    d->e = NULL; d->count = 0;
}
void dict_copy(Dict *dst, const Dict *src)
{
    for (int i = 0; i < src->count; i++) dict_set(dst, src->e[i].key, src->e[i].value);
}

void codecpar_copy(CodecPar *dst, const CodecPar *src)
