        memcpy(dst->extradata, src->extradata, src->extradata_size);
        memset(dst->extradata + src->extradata_size, 0, 64);
    }
}

/* ---- math ---- */
int64_t av_rescale_rnd(int64_t a, int64_t b, int64_t c, int rnd)
{
    int64_t r = 0;
    if (c <= 0 || b < 0 || !((unsigned)(rnd & ~AV_ROUND_PASS_MINMAX) <= 5 && (rnd & ~AV_ROUND_PASS_MINMAX) != 4))
        return INT64_MIN;
    if (rnd & AV_ROUND_PASS_MINMAX) {
        if (a == INT64_MIN || a == INT64_MAX) return a;
        rnd -= AV_ROUND_PASS_MINMAX;
    }
    if (a < 0)
        return -(uint64_t)av_rescale_rnd(-FFMAX(a, -INT64_MAX), b, c, rnd ^ ((rnd >> 1) & 1));
    if (rnd == AV_ROUND_NEAR_INF) r = c / 2;
    else if (rnd & 1) r = c - 1;
    __int128 t = (__int128)a * b + r;
    t /= c;
    if (t > INT64_MAX) return INT64_MIN;
    return (int64_t)t;
}
int64_t av_rescale(int64_t a, int64_t b, int64_t c) { return av_rescale_rnd(a, b, c, AV_ROUND_NEAR_INF); }
int64_t av_rescale_q_rnd(int64_t a, Rational bq, Rational cq, int rnd)
{
    int64_t b = (int64_t)bq.num * cq.den;
    int64_t c = (int64_t)cq.num * bq.den;
    return av_rescale_rnd(a, b, c, rnd);
}
int64_t av_rescale_q(int64_t a, Rational bq, Rational cq) { return av_rescale_q_rnd(a, bq, cq, AV_ROUND_NEAR_INF); }

/* ---- packets/frames ---- */
void packet_init(Packet *p)
{
    memset(p, 0, sizeof(*p));
    p->pts = p->dts = AV_NOPTS_VALUE;
    p->pos = -1;
}
void packet_free(Packet *p)
{
    free(p->data);
    free(p->new_extradata);
    packet_init(p);
}
void packet_ref_copy(Packet *dst, const Packet *src)
{
    *dst = *src;
    if (src->data) {
        dst->data = malloc(src->size + 64);
        memcpy(dst->data, src->data, src->size);
        memset(dst->data + src->size, 0, 64);
    }
    if (src->new_extradata) {
        dst->new_extradata = malloc(src->new_extradata_size);
        memcpy(dst->new_extradata, src->new_extradata, src->new_extradata_size);
    }
}

Frame *frame_alloc(int format, int nb_samples, const ChLayout *l, int sample_rate)
{
    Frame *f = calloc(1, sizeof(*f));
    f->format = format;
    f->nb_samples = nb_samples;
    f->ch_layout = *l;
    f->sample_rate = sample_rate;
    f->pts = AV_NOPTS_VALUE;
    size_t sz = (size_t)nb_samples * l->nb_channels * sf_bytes(format);
    f->data = calloc(1, sz + 64);
    return f;
}
void frame_free(Frame *f)
{
    if (!f) return;
    free(f->data);
    free(f);
}
int frame_bytes(const Frame *f) { return f->nb_samples * f->ch_layout.nb_channels * sf_bytes(f->format); }

char *av_strdup(const char *s)
{
    if (!s) return NULL;
    size_t l = strlen(s);
    char *r = malloc(l + 1);
    memcpy(r, s, l + 1);
    return r;
}

void err2str(int err, char *buf, int size)
{
    const char *s = NULL;
    switch (err) {
    case AVERROR_EOF: s = "End of file"; break;
    case AVERROR_INVALIDDATA: s = "Invalid data found when processing input"; break;
    case AVERROR_BUG: s = "Internal bug, should not have happened"; break;
    case AVERROR_DECODER_NOT_FOUND: s = "Decoder not found"; break;
    case AVERROR_ENCODER_NOT_FOUND: s = "Encoder not found"; break;
    case AVERROR_DEMUXER_NOT_FOUND: s = "Demuxer not found"; break;
    case AVERROR_MUXER_NOT_FOUND: s = "Muxer not found"; break;
    case AVERROR_OPTION_NOT_FOUND: s = "Option not found"; break;
    case AVERROR_FILTER_NOT_FOUND: s = "Filter not found"; break;
    case AVERROR_STREAM_NOT_FOUND: s = "Stream not found"; break;
    case AVERROR_PATCHWELCOME: s = "Not yet implemented in FFmpeg, patches welcome"; break;
    case AVERROR_EXIT: s = "Immediate exit requested"; break;
    }
    if (s) { snprintf(buf, size, "%s", s); return; }
    if (err < 0 && -err < 4096) { snprintf(buf, size, "%s", strerror(-err)); return; }
    snprintf(buf, size, "Error number %d occurred", err);
}
const char *av_err2str_buf(int err)
{
    static char bufs[4][128];
    static int idx;
    idx = (idx + 1) & 3;
    err2str(err, bufs[idx], sizeof(bufs[idx]));
    return bufs[idx];
}

int64_t av_gettime(void)
{
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return (int64_t)tv.tv_sec * 1000000 + tv.tv_usec;
}
double av_gettime_relative_s(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec / 1e9;
}

/* av_parse_time for durations: [-][HH:]MM:SS[.m...] or [-]S+[.m...][s|ms|us] */
int parse_time(int64_t *out, const char *timestr, int duration)
{
    const char *p = timestr;
    int negative = 0;
    int64_t t = 0;
    (void)duration;
    if (*p == '-') { negative = 1; p++; }
    else if (*p == '+') p++;
    /* try HH:MM:SS */
    const char *q;
    int64_t parts[3]; int np = 0;
    const char *s = p;
    while (1) {
        if (!isdigit((unsigned char)*s)) break;
        int64_t v = 0;
        while (isdigit((unsigned char)*s)) { v = v * 10 + (*s - '0'); s++; }
        if (np < 3) parts[np++] = v;
        if (*s == ':' && np < 3) { s++; continue; }
        break;
    }
    if (np == 0 && *s != '.') return AVERROR(22);
    if (np >= 2) {
        if (np == 3) t = parts[0] * 3600 + parts[1] * 60 + parts[2];
        else t = parts[0] * 60 + parts[1];
        if (np == 3 && (parts[1] > 59 || parts[2] > 59)) return AVERROR(22);
        if (np == 2 && parts[1] > 59) return AVERROR(22);
        t *= 1000000;
    } else {
        t = (np ? parts[0] : 0) * 1000000;
    }
    q = s;
    if (*q == '.') {
        q++;
        int64_t mul = 100000;
        while (isdigit((unsigned char)*q)) {
            t += (*q - '0') * mul;
            mul /= 10;
            q++;
        }
    }
    if (np <= 1) {
        if (!strcmp(q, "ms")) { t /= 1000; q += 2; }
        else if (!strcmp(q, "us")) { t /= 1000000; q += 2; }
        else if (!strcmp(q, "s")) { q += 1; }
    }
    if (*q) return AVERROR(22);
    *out = negative ? -t : t;
    return 0;
}
