}
static inline uint32_t gb_bits(GetBits *g, int n)
{
    uint32_t v = 0;
    /* fast path */
    while (n > 0) {
        if ((g->idx & 7) == 0 && n >= 8 && g->idx + 8 <= g->size_bits) {
            v = (v << 8) | g->buf[g->idx >> 3];
            g->idx += 8;
            n -= 8;
