{
    int type, wasted = 0;
    if (gb_bit(g)) return -1;
    type = gb_bits(g, 6);
    if (gb_bit(g)) {
        int left = g->size_bits - g->idx;
        if (left <= 0) return -1;
        wasted = 1 + gb_unary(g, bps);
        if (wasted <= 0 || wasted > bps) return -1;
        bps -= wasted;
