        int32_t coeffs[32];
        for (int i = 0; i < order; i++) coeffs[i] = gb_sbits(g, coeff_prec);
        if (decode_residuals(g, decoded, order, blocksize) < 0) return -1;
        for (int i = order; i < blocksize; i++) {
            int64_t sum = 0;
            for (int j = 0; j < order; j++) sum += (int64_t)coeffs[j] * decoded[i - 1 - j];
            decoded[i] = (int32_t)(decoded[i] + (int32_t)(sum >> qlevel));
        }
    } else {
        return -1;
    }
    if (wasted) {
        for (int i = 0; i < blocksize; i++) decoded[i] = (int32_t)((uint32_t)decoded[i] << wasted);
    }
    return 0;
}

int flac_decode_frame(const uint8_t *buf, int size, const FlacStreamInfo *si,
                      FlacFrameInfo *fi, int32_t *samples)
{
    int hlen = flac_parse_frame_header(buf, size, fi);
    if (hlen < 0) return -1;
    int bps = fi->bps ? fi->bps : si->bps;
    int bs = fi->blocksize;
    int ch = fi->channels;
    GetBits g = { buf, size * 8, hlen * 8 };
    int32_t *dec[8];
    static int32_t *scratch;
    static int scratch_size;
    if (scratch_size < bs * 8) {
        free(scratch);
        scratch_size = bs * 8;
        scratch = malloc(sizeof(int32_t) * scratch_size);
    }
    for (int c = 0; c < ch; c++) dec[c] = scratch + c * bs;
    for (int c = 0; c < ch; c++) {
        int sbps = bps;
        if (fi->ch_mode == 8 && c == 1) sbps++;
        if (fi->ch_mode == 9 && c == 0) sbps++;
        if (fi->ch_mode == 10 && c == 1) sbps++;
        if (decode_subframe(&g, dec[c], bs, sbps) < 0) return -1;
    }
    /* byte align */
    g.idx = (g.idx + 7) & ~7;
    if (g.idx / 8 + 2 > size) return -1;
    int flen = g.idx / 8 + 2;
    uint16_t crc = crc16_ansi(0, buf, flen - 2);
    if (crc != ((buf[flen - 2] << 8) | buf[flen - 1])) return -2 - flen; /* crc mismatch: encode len */
    if (samples) {
        for (int i = 0; i < bs; i++) {
            int32_t a = dec[0][i], b = ch > 1 ? dec[1][i] : 0;
            switch (fi->ch_mode) {
            case 8: /* left/side */
                samples[i * 2] = a;
                samples[i * 2 + 1] = a - b;
                break;
            case 9: /* side/right */
                samples[i * 2] = a + b;
                samples[i * 2 + 1] = b;
                break;
            case 10: { /* mid/side */
                int32_t mid = (int32_t)(((uint32_t)a << 1) | (b & 1));
                samples[i * 2] = (mid + b) >> 1;
                samples[i * 2 + 1] = (mid - b) >> 1;
                break; }
            default:
                for (int c = 0; c < ch; c++) samples[i * ch + c] = dec[c][i];
            }
        }
    }
    return flen;
}
EOF
