Stream *format_new_stream(FormatContext *s)
{
    Stream *st = calloc(1, sizeof(*st));
    st->index = s->nb_streams;
    st->start_time = AV_NOPTS_VALUE;
    st->duration = AV_NOPTS_VALUE;
    st->par.format = SF_NONE;
    s->streams = realloc(s->streams, sizeof(Stream *) * (s->nb_streams + 1));
    s->streams[s->nb_streams++] = st;
    return st;
}

int fmt_has_option(const FmtOpt *opts, const char *name)
{
    if (!opts) return 0;
    for (; opts->name; opts++) if (!strcmp(opts->name, name)) return 1;
    return 0;
}
const char *fmt_opt_get(FormatContext *s, const FmtOpt *opts, const char *name)
{
    const char *v = dict_get(&s->opts, name);
    if (v) return v;
    if (opts) for (; opts->name; opts++) if (!strcmp(opts->name, name)) return opts->def;
    return NULL;
}
int64_t fmt_opt_int(FormatContext *s, const FmtOpt *opts, const char *name)
{
    const char *v = fmt_opt_get(s, opts, name);
    if (!v) return 0;
    if (!strcmp(v, "true")) return 1;
    if (!strcmp(v, "false")) return 0;
    return strtoll(v, NULL, 0);
}

/* ------------------------------------------------------------------ */
/* RIFF / WAV                                                          */
/* ------------------------------------------------------------------ */
int wav_codec_from_tag(int tag, int bps)
{
    if (tag == 1) {
        switch (bps) {
        case 8: return CID_PCM_U8;
        case 16: return CID_PCM_S16LE;
        case 24: return CID_PCM_S24LE;
        case 32: return CID_PCM_S32LE;
        case 64: return CID_PCM_S64LE;
        }
        if (bps > 0 && bps <= 8) return CID_PCM_U8;
        if (bps > 8 && bps <= 16) return CID_PCM_S16LE;
        if (bps > 16 && bps <= 24) return CID_PCM_S24LE;
        if (bps > 24 && bps <= 32) return CID_PCM_S32LE;
        return CID_NONE;
    }
    if (tag == 3) {
        if (bps == 64) return CID_PCM_F64LE;
        return CID_PCM_F32LE;
    }
    if (tag == 6) return CID_PCM_ALAW;
    if (tag == 7) return CID_PCM_MULAW;
    if (tag == 0xF1AC) return CID_FLAC;
    return CID_NONE;
}

int wav_tag_from_codec(int id)
{
    switch (id) {
    case CID_PCM_S16LE: case CID_PCM_U8: case CID_PCM_S24LE: case CID_PCM_S32LE: case CID_PCM_S64LE:
        return 1;
    case CID_PCM_F32LE: case CID_PCM_F64LE: return 3;
    case CID_PCM_ALAW: return 6;
    case CID_PCM_MULAW: return 7;
    case CID_FLAC: return 0xF1AC;
    }
    return 0;
}

static const struct { const char *riff; const char *gen; } riff_info_conv[] = {
    { "IART", "artist" }, { "ICMT", "comment" }, { "ICOP", "copyright" }, { "ICRD", "date" },
    { "IGNR", "genre" }, { "ILNG", "language" }, { "INAM", "title" }, { "IPRD", "album" },
    { "IPRT", "track" }, { "ITRK", "track" }, { "ISFT", "encoder" }, { "ISMP", "timecode" },
    { "ITCH", "encoded_by" }, { NULL, NULL }
};

const char *riff_to_generic(const char *k)
{
    for (int i = 0; riff_info_conv[i].riff; i++)
        if (!strcmp(riff_info_conv[i].riff, k)) return riff_info_conv[i].gen;
    return k;
}
const char *generic_to_riff(const char *k)
{
    for (int i = 0; riff_info_conv[i].riff; i++)
        if (!strcasecmp(riff_info_conv[i].gen, k)) return riff_info_conv[i].riff;
    return k;
}

typedef struct WavDemux {
    int64_t data_start, data_end;
    int max_size;
    int ignore_length;
} WavDemux;

static int wav_probe(const uint8_t *p, int size)
{
    if (size <= 32) return 0;
    if (!memcmp(p + 8, "WAVE", 4)) {
        if (!memcmp(p, "RIFF", 4) || !memcmp(p, "RF64", 4) || !memcmp(p, "BW64", 4))
            return 100;
    }
    return 0;
}

static int pcm_default_packet_size(CodecPar *par)
{
    int nb_samples, max_samples, bits_per_sample;
    int64_t bitrate;
    if (par->block_align <= 0) return AVERROR(22);
    max_samples = INT_MAX / par->block_align;
    bits_per_sample = get_bits_per_sample(par->codec_id);
    bitrate = par->bit_rate;
    if (bits_per_sample > 0 && par->sample_rate > 0 && par->ch_layout.nb_channels > 0)
        bitrate = bits_per_sample * (int64_t)par->sample_rate * par->ch_layout.nb_channels;
    if (bitrate > 0) {
        nb_samples = (int)av_clip64(bitrate / 8 / 10 / par->block_align, 1, max_samples);
        nb_samples = 1 << av_log2(nb_samples);
    } else {
        nb_samples = av_clip(4096 / par->block_align, 1, max_samples);
    }
    return par->block_align * nb_samples;
}

static void read_riff_info(FormatContext *s, AVIO *pb, int64_t size)
{
    int64_t end = avio_tell(pb) + size;
    while (avio_tell(pb) + 8 <= end) {
        uint8_t tag[5] = {0};
        if (avio_read(pb, tag, 4) != 4) break;
        uint32_t len = avio_rl32(pb);
        if (len > end - avio_tell(pb)) break;
        char *val = calloc(1, len + 1);
        avio_read(pb, (uint8_t *)val, len);
        if (len & 1) avio_r8(pb);
        if (val[0]) dict_set(&s->metadata, riff_to_generic((char *)tag), val);
        free(val);
    }
    avio_seek(pb, end);
}

static int wav_read_header(FormatContext *s)
{
    AVIO *pb = s->pb;
    WavDemux *w = calloc(1, sizeof(*w));
    s->priv = w;
    uint8_t tag[4];
    avio_read(pb, tag, 4);
    int rf64 = !memcmp(tag, "RF64", 4) || !memcmp(tag, "BW64", 4);
    avio_rl32(pb);
    avio_read(pb, tag, 4); /* WAVE */
    int64_t data_size = -1, ds64_data = -1;
    int got_fmt = 0, got_data = 0;
    Stream *st = NULL;
    int64_t next;
    for (;;) {
        if (avio_read(pb, tag, 4) != 4) break;
        uint32_t size = avio_rl32(pb);
        int64_t start = avio_tell(pb);
        next = start + size + (size & 1);
        if (!memcmp(tag, "ds64", 4)) {
            avio_rl64(pb);
            ds64_data = (int64_t)avio_rl64(pb);
            avio_seek(pb, next);
        } else if (!memcmp(tag, "fmt ", 4)) {
            st = format_new_stream(s);
            st->par.codec_type = MT_AUDIO;
            int fmt_tag = avio_rl16(pb);
            int channels = avio_rl16(pb);
            int rate = avio_rl32(pb);
            int byterate = avio_rl32(pb);
            int block_align = avio_rl16(pb);
            int bps = 16;
            if (size >= 16) bps = avio_rl16(pb);
            uint64_t mask = 0;
            int has_mask = 0;
            if (fmt_tag == 0xFFFE && size >= 40) {
                avio_rl16(pb); /* cbSize */
                int valid = avio_rl16(pb);
                (void)valid;
                mask = avio_rl32(pb);
                has_mask = 1;
                int sub = avio_rl32(pb);
                fmt_tag = sub;
            }
            st->par.codec_tag = fmt_tag;
            st->par.codec_id = wav_codec_from_tag(fmt_tag, bps);
            st->par.sample_rate = rate;
            st->par.bit_rate = (int64_t)byterate * 8;
            st->par.block_align = block_align;
            st->par.bits_per_coded_sample = bps;
            if (has_mask && mask && __builtin_popcountll(mask) == channels) {
                st->par.ch_layout.order = 1;
                st->par.ch_layout.mask = mask;
                st->par.ch_layout.nb_channels = channels;
            } else {
                st->par.ch_layout.order = 0;
                st->par.ch_layout.nb_channels = channels;
                st->par.ch_layout.mask = 0;
            }
            st->time_base = (Rational){ 1, rate };
            got_fmt = 1;
            avio_seek(pb, next);
        } else if (!memcmp(tag, "data", 4)) {
            w->data_start = start;
            data_size = size;
            if (rf64 && ds64_data >= 0) data_size = ds64_data;
            got_data = 1;
            if (!pb->seekable || size == 0xFFFFFFFF) {
                w->data_end = INT64_MAX;
                if (size != 0xFFFFFFFF && !rf64) w->data_end = start + size;
                break;
            }
            w->data_end = start + data_size;
            /* look for trailing chunks (LIST) */
            next = w->data_end + (data_size & 1);
            if (avio_seek(pb, next) < 0) break;
        } else if (!memcmp(tag, "LIST", 4)) {
            uint8_t lt[4];
            avio_read(pb, lt, 4);
            if (!memcmp(lt, "INFO", 4))
                read_riff_info(s, pb, size - 4);
            avio_seek(pb, next);
        } else {
            if (avio_seek(pb, next) < 0) break;
        }
        if (got_data && avio_feof(pb)) break;
    }
    if (!got_fmt || !got_data) return AVERROR_INVALIDDATA;
    if (w->data_end == INT64_MAX && pb->seekable) w->data_end = pb->size_cache;
    if (pb->seekable && w->data_end > pb->size_cache) w->data_end = pb->size_cache;
    if (st->par.block_align > 0 && w->data_end != INT64_MAX && pb->seekable)
        st->duration = (w->data_end - w->data_start) / st->par.block_align;
    else if (!pb->seekable && w->data_end != INT64_MAX && st->par.block_align > 0)
        st->duration = AV_NOPTS_VALUE;
    avio_seek(pb, w->data_start);
    s->data_offset = w->data_start;
    if (st->par.codec_id == CID_PCM_S24LE || st->par.codec_id == CID_PCM_S32LE)
        st->par.bits_per_raw_sample = get_bits_per_sample(st->par.codec_id);
    w->max_size = (int)fmt_opt_int(s, s->ifmt->opts, "max_size");
    return 0;
}

static int wav_read_packet(FormatContext *s, Packet *pkt)
{
    WavDemux *w = s->priv;
    Stream *st = s->streams[0];
    int64_t pos = avio_tell(s->pb);
    int64_t left = w->data_end - pos;
    if (left <= 0) return AVERROR_EOF;
    int size;
    if (w->max_size > 0) {
        size = w->max_size;
        if (st->par.block_align > 1) {
            if (size < st->par.block_align) size = st->par.block_align;
            size = (size / st->par.block_align) * st->par.block_align;
        }
    } else
        size = pcm_default_packet_size(&st->par);
    if (size > left) size = (int)left;
    pkt->data = malloc(size + 64);
    int r = avio_read(s->pb, pkt->data, size);
    if (r <= 0) { free(pkt->data); pkt->data = NULL; return AVERROR_EOF; }
    if (st->par.block_align > 0) r -= r % st->par.block_align;
    if (r <= 0) { free(pkt->data); pkt->data = NULL; return AVERROR_EOF; }
    memset(pkt->data + r, 0, 64);
    pkt->size = r;
    pkt->pos = pos;
    pkt->stream_index = 0;
    pkt->flags = PKT_FLAG_KEY;
    if (st->par.block_align > 0) {
        pkt->pts = pkt->dts = (pos - w->data_start) / st->par.block_align;
        pkt->duration = r / st->par.block_align;
    }
    return 0;
}

static int wav_read_seek(FormatContext *s, int64_t ts_us)
{
    WavDemux *w = s->priv;
    Stream *st = s->streams[0];
    if (st->par.block_align <= 0) return -1;
    int64_t sample = av_rescale_rnd(ts_us, st->par.sample_rate, AV_TIME_BASE, AV_ROUND_DOWN);
    if (sample < 0) sample = 0;
    int64_t pos = w->data_start + sample * st->par.block_align;
    if (pos > w->data_end) pos = w->data_end;
    if (avio_seek(s->pb, pos) < 0) return -1;
    return 0;
}

static void wav_close(FormatContext *s) { free(s->priv); s->priv = NULL; }

static const FmtOpt wav_demux_opts[] = {
    { "ignore_length", 2, "false", 0, 1 },
    { "max_size", 0, "0", 0, 4194304 },
    { NULL }
};

const InputFormat ff_wav_demuxer = {
    "wav", "WAV / WAVE (Waveform Audio)", "wav", 0,
    wav_probe, wav_read_header, wav_read_packet, wav_read_seek, wav_close, wav_demux_opts
};

/* ------------------------------------------------------------------ */
/* FLAC                                                                */
/* ------------------------------------------------------------------ */
typedef struct FlacDemux {
    uint8_t *data;
    int64_t size;
    int64_t pos;
    FlacStreamInfo si;
    int64_t next_pts;
    int frame_count;
} FlacDemux;

static int flac_probe(const uint8_t *p, int size)
{
    if (size >= 4 + 4 + 13 && !memcmp(p, "fLaC", 4)) return 100; /* AVPROBE_SCORE_EXTENSION ... */
    if (size >= 10 && !memcmp(p, "ID3", 3)) {
        int len = ((p[6] & 0x7f) << 21) | ((p[7] & 0x7f) << 14) | ((p[8] & 0x7f) << 7) | (p[9] & 0x7f);
        len += 10;
        if (p[5] & 0x10) len += 10;
        if (len + 4 <= size && !memcmp(p + len, "fLaC", 4)) return 100;
    }
    return 0;
}

static void read_all(AVIO *pb, uint8_t **data, int64_t *size)
{
    int64_t cap = 65536, len = 0;
    uint8_t *buf = malloc(cap);
    for (;;) {
        if (len + 65536 > cap) { cap *= 2; buf = realloc(buf, cap); }
        int r = avio_read(pb, buf + len, 65536);
        if (r <= 0) break;
        len += r;
    }
    *data = buf;
    *size = len;
}

static void parse_vorbis_comment(FormatContext *s, const uint8_t *p, int len)
{
    const uint8_t *end = p + len;
    if (end - p < 4) return;
    uint32_t vl = p[0] | (p[1] << 8) | (p[2] << 16) | ((uint32_t)p[3] << 24);
    p += 4;
    if (vl > (uint32_t)(end - p)) return;
    p += vl;
    if (end - p < 4) return;
    uint32_t n = p[0] | (p[1] << 8) | (p[2] << 16) | ((uint32_t)p[3] << 24);
    p += 4;
    for (uint32_t i = 0; i < n && end - p >= 4; i++) {
        uint32_t l = p[0] | (p[1] << 8) | (p[2] << 16) | ((uint32_t)p[3] << 24);
        p += 4;
        if (l > (uint32_t)(end - p)) break;
        char *kv = calloc(1, l + 1);
        memcpy(kv, p, l);
        p += l;
        char *eq = strchr(kv, '=');
        if (eq && eq != kv) {
            *eq = 0;
            const char *k = kv;
            if (!strcasecmp(k, "TRACKNUMBER")) k = "track";
            else if (!strcasecmp(k, "DISCNUMBER")) k = "disc";
            else if (!strcasecmp(k, "DESCRIPTION")) k = "comment";
            else if (!strcasecmp(k, "ALBUMARTIST")) k = "album_artist";
            const char *old = dict_get(&s->metadata, k);
            if (old) {
                /* multiple values are joined with ';' */
                char *nv = malloc(strlen(old) + strlen(eq + 1) + 2);
                sprintf(nv, "%s;%s", old, eq + 1);
                dict_set(&s->metadata, k, nv);
                free(nv);
            } else
                dict_set(&s->metadata, k, eq + 1);
        }
        free(kv);
    }
}

static int flac_read_header(FormatContext *s)
{
    FlacDemux *f = calloc(1, sizeof(*f));
    s->priv = f;
    read_all(s->pb, &f->data, &f->size);
    int64_t p = 0;
    if (f->size >= 10 && !memcmp(f->data, "ID3", 3)) {
        const uint8_t *q = f->data;
        int len = ((q[6] & 0x7f) << 21) | ((q[7] & 0x7f) << 14) | ((q[8] & 0x7f) << 7) | (q[9] & 0x7f);
        len += 10;
        if (q[5] & 0x10) len += 10;
        p = len;
    }
    if (f->size - p < 4 || memcmp(f->data + p, "fLaC", 4)) return AVERROR_INVALIDDATA;
    p += 4;
    Stream *st = format_new_stream(s);
    st->par.codec_type = MT_AUDIO;
    st->par.codec_id = CID_FLAC;
    int got_si = 0;
    for (;;) {
        if (f->size - p < 4) return AVERROR_INVALIDDATA;
        int last = f->data[p] >> 7;
        int type = f->data[p] & 0x7f;
        int len = (f->data[p + 1] << 16) | (f->data[p + 2] << 8) | f->data[p + 3];
        p += 4;
        if (f->size - p < len) return AVERROR_INVALIDDATA;
        if (type == 0) {
            if (len < 34) return AVERROR_INVALIDDATA;
            flac_parse_streaminfo(&f->si, f->data + p);
            st->par.extradata = malloc(34 + 64);
            memcpy(st->par.extradata, f->data + p, 34);
            memset(st->par.extradata + 34, 0, 64);
            st->par.extradata_size = 34;
            got_si = 1;
        } else if (type == 4) {
            parse_vorbis_comment(s, f->data + p, len);
        }
        p += len;
        if (last) break;
    }
    if (!got_si) return AVERROR_INVALIDDATA;
    f->pos = p;
    s->data_offset = p;
    st->par.sample_rate = f->si.samplerate;
    chl_default(&st->par.ch_layout, f->si.channels);
    {
        const char *cm = dict_get(&s->metadata, "WAVEFORMATEXTENSIBLE_CHANNEL_MASK");
        if (cm) {
            uint64_t m = strtoull(cm, NULL, 0);
            if (m && __builtin_popcountll(m) == f->si.channels) {
                st->par.ch_layout.order = 1;
                st->par.ch_layout.mask = m;
            }
            dict_set(&s->metadata, "WAVEFORMATEXTENSIBLE_CHANNEL_MASK", NULL);
        }
    }
    st->par.bits_per_raw_sample = f->si.bps;
    st->par.format = f->si.bps > 16 ? SF_S32 : SF_S16;
    st->par.frame_size = 0;
    st->time_base = (Rational){ 1, f->si.samplerate ? f->si.samplerate : 1 };
    if (f->si.samples > 0)
        st->duration = f->si.samples;
    /* count frames for start_time heuristic */
    {
        int64_t q = f->pos;
        int n = 0;
        while (q < f->size && n < 2) {
            FlacFrameInfo fi;
            int r = flac_decode_frame(f->data + q, (int)(f->size - q), &f->si, &fi, NULL);
            if (r == -1) break;
            if (r < -1) r = -2 - r;
            q += r;
            n++;
        }
        s->nb_frames_probe = n;
        if (n >= 2) st->start_time = 0;
    }
    return 0;
}

static int flac_read_packet(FormatContext *s, Packet *pkt)
{
    FlacDemux *f = s->priv;
    Stream *st = s->streams[0];
    while (f->pos < f->size) {
        /* find sync */
        int64_t q = f->pos;
        FlacFrameInfo fi;
        int r = flac_decode_frame(f->data + q, (int)(f->size - q), &f->si, &fi, NULL);
        if (r < -1) r = -2 - r; /* crc error but length known */
        if (r == -1) {
            /* resync: search next sync code */
            int64_t k;
            for (k = q + 1; k + 1 < f->size; k++) {
                if (f->data[k] == 0xFF && (f->data[k + 1] & 0xFE) == 0xF8) {
                    FlacFrameInfo t;
                    if (flac_parse_frame_header(f->data + k, (int)(f->size - k), &t) > 0) break;
                }
            }
            if (k + 1 >= f->size) { f->pos = f->size; break; }
            f->pos = k;
            continue;
        }
        pkt->data = malloc(r + 64);
        memcpy(pkt->data, f->data + q, r);
        memset(pkt->data + r, 0, 64);
        pkt->size = r;
        pkt->pos = q;
        pkt->stream_index = 0;
        pkt->flags = PKT_FLAG_KEY;
        if (fi.blocking_strategy == 0) {
            int bs = f->si.min_blocksize == f->si.max_blocksize ? f->si.max_blocksize : fi.blocksize;
            if (f->si.min_blocksize != f->si.max_blocksize) bs = fi.blocksize;
            pkt->pts = fi.frame_or_sample_num * (int64_t)(f->si.max_blocksize ? bs : fi.blocksize);
        } else {
            pkt->pts = fi.frame_or_sample_num;
        }
        pkt->dts = pkt->pts;
        pkt->duration = fi.blocksize;
        f->pos = q + r;
        f->frame_count++;
        (void)st;
        return 0;
    }
    return AVERROR_EOF;
}

static int flac_read_seek(FormatContext *s, int64_t ts_us)
{
    FlacDemux *f = s->priv;
    Stream *st = s->streams[0];
    int64_t target = av_rescale(ts_us, st->par.sample_rate, AV_TIME_BASE);
    int64_t q = s->data_offset;
    int64_t best = q;
    while (q < f->size) {
        FlacFrameInfo fi;
        int r = flac_decode_frame(f->data + q, (int)(f->size - q), &f->si, &fi, NULL);
        if (r < -1) r = -2 - r;
        if (r <= 0) break;
        int64_t pts = fi.blocking_strategy ? fi.frame_or_sample_num : fi.frame_or_sample_num * f->si.max_blocksize;
        if (pts > target) break;
        best = q;
        q += r;
    }
    f->pos = best;
    return 0;
}

static void flac_close(FormatContext *s)
{
    FlacDemux *f = s->priv;
    if (f) free(f->data);
    free(f);
    s->priv = NULL;
}

