const InputFormat *find_input_format(const char *name)
{
    for (int i = 0; input_formats[i]; i++)
        if (!strcmp(input_formats[i]->name, name)) return input_formats[i];
    return NULL;
}

const InputFormat *probe_input_format(const uint8_t *buf, int size, const char *filename, int *score)
{
    const InputFormat *best = NULL;
    int best_score = 0;
    for (int i = 0; input_formats[i]; i++) {
        if (!input_formats[i]->probe) continue;
        int sc = input_formats[i]->probe(buf, size);
        if (sc > best_score) { best_score = sc; best = input_formats[i]; }
    }
    (void)filename;
    *score = best_score;
    return best;
}
