int wav_codec_from_tag(int tag, int bps)
{
    if (tag == 1) {
        switch (bps) {
        case 8: return CID_PCM_U8;
        case 16: return CID_PCM_S16LE;
        case 24: return CID_PCM_S24LE;
        case 32: return CID_PCM_S32LE;
        case 64: return CID_PCM_S64LE;
        }
        if (bps > 0 && bps <= 8) return CID_PCM_U8;
        if (bps > 8 && bps <= 16) return CID_PCM_S16LE;
        if (bps > 16 && bps <= 24) return CID_PCM_S24LE;
        if (bps > 24 && bps <= 32) return CID_PCM_S32LE;
        return CID_NONE;
    }
    if (tag == 3) {
        if (bps == 64) return CID_PCM_F64LE;
        return CID_PCM_F32LE;
    }
    if (tag == 6) return CID_PCM_ALAW;
    if (tag == 7) return CID_PCM_MULAW;
    if (tag == 0xF1AC) return CID_FLAC;
    return CID_NONE;
}

int wav_tag_from_codec(int id)
{
    switch (id) {
    case CID_PCM_S16LE: case CID_PCM_U8: case CID_PCM_S24LE: case CID_PCM_S32LE: case CID_PCM_S64LE:
        return 1;
    case CID_PCM_F32LE: case CID_PCM_F64LE: return 3;
    case CID_PCM_ALAW: return 6;
    case CID_PCM_MULAW: return 7;
    case CID_FLAC: return 0xF1AC;
    }
