static int wav_probe(const uint8_t *p, int size)
{
    if (size <= 32) return 0;
    if (!memcmp(p + 8, "WAVE", 4)) {
        if (!memcmp(p, "RIFF", 4) || !memcmp(p, "RF64", 4) || !memcmp(p, "BW64", 4))
            return 100;
    }
    return 0;
}

static int pcm_default_packet_size(CodecPar *par)
{
    int nb_samples, max_samples, bits_per_sample;
    int64_t bitrate;
    if (par->block_align <= 0) return AVERROR(22);
    max_samples = INT_MAX / par->block_align;
    bits_per_sample = get_bits_per_sample(par->codec_id);
    bitrate = par->bit_rate;
    if (bits_per_sample > 0 && par->sample_rate > 0 && par->ch_layout.nb_channels > 0)
        bitrate = bits_per_sample * (int64_t)par->sample_rate * par->ch_layout.nb_channels;
    if (bitrate > 0) {
        nb_samples = (int)av_clip64(bitrate / 8 / 10 / par->block_align, 1, max_samples);
        nb_samples = 1 << av_log2(nb_samples);
    } else {
        nb_samples = av_clip(4096 / par->block_align, 1, max_samples);
    }
    return par->block_align * nb_samples;
}

static void read_riff_info(FormatContext *s, AVIO *pb, int64_t size)
{
    int64_t end = avio_tell(pb) + size;
    while (avio_tell(pb) + 8 <= end) {
        uint8_t tag[5] = {0};
        if (avio_read(pb, tag, 4) != 4) break;
        uint32_t len = avio_rl32(pb);
        if (len > end - avio_tell(pb)) break;
        char *val = calloc(1, len + 1);
        avio_read(pb, (uint8_t *)val, len);
        if (len & 1) avio_r8(pb);
        if (val[0]) dict_set(&s->metadata, riff_to_generic((char *)tag), val);
        free(val);
    }
    avio_seek(pb, end);
}

static int wav_read_header(FormatContext *s)
{
    AVIO *pb = s->pb;
    WavDemux *w = calloc(1, sizeof(*w));
    s->priv = w;
    uint8_t tag[4];
    avio_read(pb, tag, 4);
    int rf64 = !memcmp(tag, "RF64", 4) || !memcmp(tag, "BW64", 4);
    avio_rl32(pb);
    avio_read(pb, tag, 4); /* WAVE */
    int64_t data_size = -1, ds64_data = -1;
    int got_fmt = 0, got_data = 0;
    Stream *st = NULL;
    int64_t next;
    for (;;) {
        if (avio_read(pb, tag, 4) != 4) break;
        uint32_t size = avio_rl32(pb);
        int64_t start = avio_tell(pb);
        next = start + size + (size & 1);
        if (!memcmp(tag, "ds64", 4)) {
            avio_rl64(pb);
            ds64_data = (int64_t)avio_rl64(pb);
            avio_seek(pb, next);
        } else if (!memcmp(tag, "fmt ", 4)) {
            st = format_new_stream(s);
            st->par.codec_type = MT_AUDIO;
            int fmt_tag = avio_rl16(pb);
            int channels = avio_rl16(pb);
            int rate = avio_rl32(pb);
            int byterate = avio_rl32(pb);
            int block_align = avio_rl16(pb);
            int bps = 16;
            if (size >= 16) bps = avio_rl16(pb);
            uint64_t mask = 0;
            int has_mask = 0;
            if (fmt_tag == 0xFFFE && size >= 40) {
                avio_rl16(pb); /* cbSize */
                int valid = avio_rl16(pb);
                (void)valid;
                mask = avio_rl32(pb);
                has_mask = 1;
                int sub = avio_rl32(pb);
                fmt_tag = sub;
            }
            st->par.codec_tag = fmt_tag;
            st->par.codec_id = wav_codec_from_tag(fmt_tag, bps);
            st->par.sample_rate = rate;
            st->par.bit_rate = (int64_t)byterate * 8;
            st->par.block_align = block_align;
            st->par.bits_per_coded_sample = bps;
            if (has_mask && mask && __builtin_popcountll(mask) == channels) {
                st->par.ch_layout.order = 1;
                st->par.ch_layout.mask = mask;
                st->par.ch_layout.nb_channels = channels;
            } else {
                st->par.ch_layout.order = 0;
                st->par.ch_layout.nb_channels = channels;
                st->par.ch_layout.mask = 0;
            }
            st->time_base = (Rational){ 1, rate };
            got_fmt = 1;
            avio_seek(pb, next);
        } else if (!memcmp(tag, "data", 4)) {
            w->data_start = start;
            data_size = size;
            if (rf64 && ds64_data >= 0) data_size = ds64_data;
            got_data = 1;
            if (!pb->seekable || size == 0xFFFFFFFF) {
                w->data_end = INT64_MAX;
                if (size != 0xFFFFFFFF && !rf64) w->data_end = start + size;
                break;
            }
            w->data_end = start + data_size;
            /* look for trailing chunks (LIST) */
            next = w->data_end + (data_size & 1);
            if (avio_seek(pb, next) < 0) break;
        } else if (!memcmp(tag, "LIST", 4)) {
            uint8_t lt[4];
            avio_read(pb, lt, 4);
            if (!memcmp(lt, "INFO", 4))
                read_riff_info(s, pb, size - 4);
            avio_seek(pb, next);
        } else {
            if (avio_seek(pb, next) < 0) break;
        }
        if (got_data && avio_feof(pb)) break;
    }
    if (!got_fmt || !got_data) return AVERROR_INVALIDDATA;
    if (w->data_end == INT64_MAX && pb->seekable) w->data_end = pb->size_cache;
    if (pb->seekable && w->data_end > pb->size_cache) w->data_end = pb->size_cache;
    if (st->par.block_align > 0 && w->data_end != INT64_MAX && pb->seekable)
        st->duration = (w->data_end - w->data_start) / st->par.block_align;
    else if (!pb->seekable && w->data_end != INT64_MAX && st->par.block_align > 0)
        st->duration = AV_NOPTS_VALUE;
    avio_seek(pb, w->data_start);
    s->data_offset = w->data_start;
    if (st->par.codec_id == CID_PCM_S24LE || st->par.codec_id == CID_PCM_S32LE)
        st->par.bits_per_raw_sample = get_bits_per_sample(st->par.codec_id);
    w->max_size = (int)fmt_opt_int(s, s->ifmt->opts, "max_size");
    return 0;
}

static int wav_read_packet(FormatContext *s, Packet *pkt)
{
    WavDemux *w = s->priv;
    Stream *st = s->streams[0];
    int64_t pos = avio_tell(s->pb);
    int64_t left = w->data_end - pos;
    if (left <= 0) return AVERROR_EOF;
    int size;
    if (w->max_size > 0) {
        size = w->max_size;
        if (st->par.block_align > 1) {
            if (size < st->par.block_align) size = st->par.block_align;
            size = (size / st->par.block_align) * st->par.block_align;
        }
    } else
        size = pcm_default_packet_size(&st->par);
    if (size > left) size = (int)left;
    pkt->data = malloc(size + 64);
    int r = avio_read(s->pb, pkt->data, size);
    if (r <= 0) { free(pkt->data); pkt->data = NULL; return AVERROR_EOF; }
    if (st->par.block_align > 0) r -= r % st->par.block_align;
    if (r <= 0) { free(pkt->data); pkt->data = NULL; return AVERROR_EOF; }
    memset(pkt->data + r, 0, 64);
    pkt->size = r;
    pkt->pos = pos;
    pkt->stream_index = 0;
    pkt->flags = PKT_FLAG_KEY;
    if (st->par.block_align > 0) {
        pkt->pts = pkt->dts = (pos - w->data_start) / st->par.block_align;
        pkt->duration = r / st->par.block_align;
    }
    return 0;
}

static int wav_read_seek(FormatContext *s, int64_t ts_us)
{
    WavDemux *w = s->priv;
    Stream *st = s->streams[0];
    if (st->par.block_align <= 0) return -1;
    int64_t sample = av_rescale_rnd(ts_us, st->par.sample_rate, AV_TIME_BASE, AV_ROUND_DOWN);
    if (sample < 0) sample = 0;
    int64_t pos = w->data_start + sample * st->par.block_align;
    if (pos > w->data_end) pos = w->data_end;
    if (avio_seek(s->pb, pos) < 0) return -1;
    return 0;
}

static void wav_close(FormatContext *s) { free(s->priv); s->priv = NULL; }

