/* ------------------------------------------------------------------ */
/* FLAC                                                                */
/* ------------------------------------------------------------------ */
typedef struct FlacDemux {
    uint8_t *data;
    int64_t size;
    int64_t pos;
    FlacStreamInfo si;
    int64_t next_pts;
    int frame_count;
} FlacDemux;

static int flac_probe(const uint8_t *p, int size)
{
    if (size >= 4 + 4 + 13 && !memcmp(p, "fLaC", 4)) return 100; /* AVPROBE_SCORE_EXTENSION ... */
    if (size >= 10 && !memcmp(p, "ID3", 3)) {
        int len = ((p[6] & 0x7f) << 21) | ((p[7] & 0x7f) << 14) | ((p[8] & 0x7f) << 7) | (p[9] & 0x7f);
        len += 10;
        if (p[5] & 0x10) len += 10;
        if (len + 4 <= size && !memcmp(p + len, "fLaC", 4)) return 100;
    }
    return 0;
}

static void read_all(AVIO *pb, uint8_t **data, int64_t *size)
{
    int64_t cap = 65536, len = 0;
    uint8_t *buf = malloc(cap);
    for (;;) {
        if (len + 65536 > cap) { cap *= 2; buf = realloc(buf, cap); }
        int r = avio_read(pb, buf + len, 65536);
        if (r <= 0) break;
        len += r;
    }
    *data = buf;
    *size = len;
}

static void parse_vorbis_comment(FormatContext *s, const uint8_t *p, int len)
{
    const uint8_t *end = p + len;
    if (end - p < 4) return;
    uint32_t vl = p[0] | (p[1] << 8) | (p[2] << 16) | ((uint32_t)p[3] << 24);
    p += 4;
    if (vl > (uint32_t)(end - p)) return;
    p += vl;
    if (end - p < 4) return;
    uint32_t n = p[0] | (p[1] << 8) | (p[2] << 16) | ((uint32_t)p[3] << 24);
    p += 4;
    for (uint32_t i = 0; i < n && end - p >= 4; i++) {
        uint32_t l = p[0] | (p[1] << 8) | (p[2] << 16) | ((uint32_t)p[3] << 24);
        p += 4;
        if (l > (uint32_t)(end - p)) break;
        char *kv = calloc(1, l + 1);
        memcpy(kv, p, l);
        p += l;
        char *eq = strchr(kv, '=');
        if (eq && eq != kv) {
            *eq = 0;
            const char *k = kv;
            if (!strcasecmp(k, "TRACKNUMBER")) k = "track";
            else if (!strcasecmp(k, "DISCNUMBER")) k = "disc";
            else if (!strcasecmp(k, "DESCRIPTION")) k = "comment";
            else if (!strcasecmp(k, "ALBUMARTIST")) k = "album_artist";
            const char *old = dict_get(&s->metadata, k);
            if (old) {
                /* multiple values are joined with ';' */
                char *nv = malloc(strlen(old) + strlen(eq + 1) + 2);
                sprintf(nv, "%s;%s", old, eq + 1);
                dict_set(&s->metadata, k, nv);
                free(nv);
            } else
                dict_set(&s->metadata, k, eq + 1);
        }
        free(kv);
    }
}

static int flac_read_header(FormatContext *s)
{
    FlacDemux *f = calloc(1, sizeof(*f));
    s->priv = f;
    read_all(s->pb, &f->data, &f->size);
    int64_t p = 0;
    if (f->size >= 10 && !memcmp(f->data, "ID3", 3)) {
        const uint8_t *q = f->data;
        int len = ((q[6] & 0x7f) << 21) | ((q[7] & 0x7f) << 14) | ((q[8] & 0x7f) << 7) | (q[9] & 0x7f);
        len += 10;
        if (q[5] & 0x10) len += 10;
        p = len;
    }
    if (f->size - p < 4 || memcmp(f->data + p, "fLaC", 4)) return AVERROR_INVALIDDATA;
    p += 4;
    Stream *st = format_new_stream(s);
    st->par.codec_type = MT_AUDIO;
    st->par.codec_id = CID_FLAC;
    int got_si = 0;
    for (;;) {
        if (f->size - p < 4) return AVERROR_INVALIDDATA;
        int last = f->data[p] >> 7;
        int type = f->data[p] & 0x7f;
        int len = (f->data[p + 1] << 16) | (f->data[p + 2] << 8) | f->data[p + 3];
        p += 4;
        if (f->size - p < len) return AVERROR_INVALIDDATA;
        if (type == 0) {
            if (len < 34) return AVERROR_INVALIDDATA;
            flac_parse_streaminfo(&f->si, f->data + p);
            st->par.extradata = malloc(34 + 64);
            memcpy(st->par.extradata, f->data + p, 34);
            memset(st->par.extradata + 34, 0, 64);
            st->par.extradata_size = 34;
            got_si = 1;
        } else if (type == 4) {
            parse_vorbis_comment(s, f->data + p, len);
        }
        p += len;
        if (last) break;
    }
    if (!got_si) return AVERROR_INVALIDDATA;
    f->pos = p;
    s->data_offset = p;
    st->par.sample_rate = f->si.samplerate;
    chl_default(&st->par.ch_layout, f->si.channels);
    {
        const char *cm = dict_get(&s->metadata, "WAVEFORMATEXTENSIBLE_CHANNEL_MASK");
        if (cm) {
            uint64_t m = strtoull(cm, NULL, 0);
            if (m && __builtin_popcountll(m) == f->si.channels) {
                st->par.ch_layout.order = 1;
                st->par.ch_layout.mask = m;
            }
            dict_set(&s->metadata, "WAVEFORMATEXTENSIBLE_CHANNEL_MASK", NULL);
        }
    }
    st->par.bits_per_raw_sample = f->si.bps;
    st->par.format = f->si.bps > 16 ? SF_S32 : SF_S16;
    st->par.frame_size = 0;
    st->time_base = (Rational){ 1, f->si.samplerate ? f->si.samplerate : 1 };
    if (f->si.samples > 0)
        st->duration = f->si.samples;
    /* count frames for start_time heuristic */
    {
        int64_t q = f->pos;
        int n = 0;
        while (q < f->size && n < 2) {
            FlacFrameInfo fi;
            int r = flac_decode_frame(f->data + q, (int)(f->size - q), &f->si, &fi, NULL);
            if (r == -1) break;
            if (r < -1) r = -2 - r;
            q += r;
            n++;
        }
        s->nb_frames_probe = n;
        if (n >= 2) st->start_time = 0;
    }
    return 0;
}

static int flac_read_packet(FormatContext *s, Packet *pkt)
{
    FlacDemux *f = s->priv;
    Stream *st = s->streams[0];
    while (f->pos < f->size) {
        /* find sync */
        int64_t q = f->pos;
        FlacFrameInfo fi;
        int r = flac_decode_frame(f->data + q, (int)(f->size - q), &f->si, &fi, NULL);
        if (r < -1) r = -2 - r; /* crc error but length known */
        if (r == -1) {
            /* resync: search next sync code */
            int64_t k;
            for (k = q + 1; k + 1 < f->size; k++) {
                if (f->data[k] == 0xFF && (f->data[k + 1] & 0xFE) == 0xF8) {
                    FlacFrameInfo t;
                    if (flac_parse_frame_header(f->data + k, (int)(f->size - k), &t) > 0) break;
                }
            }
            if (k + 1 >= f->size) { f->pos = f->size; break; }
            f->pos = k;
            continue;
        }
        pkt->data = malloc(r + 64);
        memcpy(pkt->data, f->data + q, r);
        memset(pkt->data + r, 0, 64);
        pkt->size = r;
        pkt->pos = q;
        pkt->stream_index = 0;
        pkt->flags = PKT_FLAG_KEY;
        if (fi.blocking_strategy == 0) {
            int bs = f->si.min_blocksize == f->si.max_blocksize ? f->si.max_blocksize : fi.blocksize;
            if (f->si.min_blocksize != f->si.max_blocksize) bs = fi.blocksize;
            pkt->pts = fi.frame_or_sample_num * (int64_t)(f->si.max_blocksize ? bs : fi.blocksize);
        } else {
            pkt->pts = fi.frame_or_sample_num;
        }
        pkt->dts = pkt->pts;
        pkt->duration = fi.blocksize;
        f->pos = q + r;
        f->frame_count++;
        (void)st;
        return 0;
    }
    return AVERROR_EOF;
}

static int flac_read_seek(FormatContext *s, int64_t ts_us)
{
    FlacDemux *f = s->priv;
    Stream *st = s->streams[0];
    int64_t target = av_rescale(ts_us, st->par.sample_rate, AV_TIME_BASE);
    int64_t q = s->data_offset;
    int64_t best = q;
    while (q < f->size) {
        FlacFrameInfo fi;
        int r = flac_decode_frame(f->data + q, (int)(f->size - q), &f->si, &fi, NULL);
        if (r < -1) r = -2 - r;
        if (r <= 0) break;
        int64_t pts = fi.blocking_strategy ? fi.frame_or_sample_num : fi.frame_or_sample_num * f->si.max_blocksize;
        if (pts > target) break;
        best = q;
        q += r;
    }
    f->pos = best;
    return 0;
}

static void flac_close(FormatContext *s)
{
    FlacDemux *f = s->priv;
    if (f) free(f->data);
    free(f);
    s->priv = NULL;
}

