static int pcm_read_header_common(FormatContext *s, int codec_id)
{
    Stream *st = format_new_stream(s);
    st->par.codec_type = MT_AUDIO;
    st->par.codec_id = codec_id;
    st->par.sample_rate = (int)fmt_opt_int(s, pcm_demux_opts, "sample_rate");
    const char *cl = fmt_opt_get(s, pcm_demux_opts, "ch_layout");
    ChLayout l;
    if (chl_from_string(&l, cl) < 0) chl_default(&l, 1);
    const char *forced_ch = dict_get(&s->opts, "__channels");
    if (forced_ch) {
        l.order = 0; l.mask = 0; l.nb_channels = atoi(forced_ch);
    }
    st->par.ch_layout = l;
    int bps = get_bits_per_sample(codec_id);
    st->par.bits_per_coded_sample = bps;
    st->par.block_align = bps * l.nb_channels / 8;
    st->par.bit_rate = (int64_t)st->par.sample_rate * l.nb_channels * bps;
    st->time_base = (Rational){ 1, st->par.sample_rate };
    if (codec_id == CID_PCM_S24LE || codec_id == CID_PCM_S24BE || codec_id == CID_PCM_S32LE || codec_id == CID_PCM_S32BE ||
        codec_id == CID_PCM_U24LE || codec_id == CID_PCM_U24BE || codec_id == CID_PCM_U32LE || codec_id == CID_PCM_U32BE)
        st->par.bits_per_raw_sample = bps;
    s->data_offset = 0;
    return 0;
}

static int raw_pcm_read_packet(FormatContext *s, Packet *pkt)
{
    Stream *st = s->streams[0];
    int size = pcm_default_packet_size(&st->par);
    if (size <= 0) return AVERROR(22);
    int64_t pos = avio_tell(s->pb);
    pkt->data = malloc(size + 64);
    int r = avio_read(s->pb, pkt->data, size);
    if (r <= 0) { free(pkt->data); pkt->data = NULL; return AVERROR_EOF; }
    r -= r % st->par.block_align;
    if (r <= 0) { free(pkt->data); pkt->data = NULL; return AVERROR_EOF; }
    memset(pkt->data + r, 0, 64);
    pkt->size = r;
    pkt->pos = pos;
    pkt->stream_index = 0;
    pkt->flags = PKT_FLAG_KEY;
    pkt->pts = pkt->dts = pos / st->par.block_align;
    pkt->duration = r / st->par.block_align;
    return 0;
}

static int raw_pcm_read_seek(FormatContext *s, int64_t ts_us)
{
    Stream *st = s->streams[0];
    int64_t sample = av_rescale_rnd(ts_us, st->par.sample_rate, AV_TIME_BASE, AV_ROUND_DOWN);
    if (sample < 0) sample = 0;
    if (avio_seek(s->pb, sample * st->par.block_align) < 0) return -1;
    return 0;
}

