static int lavfi_read_header(FormatContext *s)
{
    LavfiSource *src = NULL;
    int ret = lavfi_open(&src, s->url, s->log_ctx);
    if (ret < 0) return ret;
    s->priv = src;
    Stream *st = format_new_stream(s);
    st->par.codec_type = MT_AUDIO;
    st->par.codec_id = lavfi_codec_id(src);
    st->par.sample_rate = lavfi_sample_rate(src);
    st->par.ch_layout = lavfi_layout(src);
    int bps = get_bits_per_sample(st->par.codec_id);
    st->par.bits_per_coded_sample = bps;
    st->par.block_align = bps * st->par.ch_layout.nb_channels / 8;
    st->par.bit_rate = (int64_t)bps * st->par.sample_rate * st->par.ch_layout.nb_channels;
    st->par.format = lavfi_sample_fmt(src);
    st->time_base = (Rational){ 1, st->par.sample_rate };
    st->start_time = 0;
    return 0;
}

static int lavfi_read_packet(FormatContext *s, Packet *pkt)
{
    return lavfi_read(s->priv, pkt);
}

static void lavfi_close(FormatContext *s)
{
    lavfi_free(s->priv);
    s->priv = NULL;
}

