cat > lavfi.c <<'EOF'
#include "lavfi.h"
#include "format.h"
#include "expr.h"

enum { SRC_SINE, SRC_ANULL, SRC_AEVAL };

struct LavfiSource {
    int type;
    int sample_rate;
    ChLayout layout;
    int64_t duration; /* in samples, 0 = infinite */
    int nb_samples;
    int64_t pts;
    /* sine */
    int16_t *sin;
    uint32_t phi, dphi, phi_beep, dphi_beep;
    int beep_period, beep_index, beep_length;
    /* aeval */
    Expr *exprs[8];
    int nb_exprs;
    int sample_fmt;
};

#define LOG_PERIOD 15
#define AMPLITUDE 4095
#define AMPLITUDE_SHIFT 3

static void make_sin_table(int16_t *sin)
{
    unsigned half_pi = 1 << (LOG_PERIOD - 2);
    unsigned ampls = AMPLITUDE << AMPLITUDE_SHIFT;
    uint64_t unit2 = (uint64_t)(ampls * ampls) << 32;
    unsigned step, i, c, s, k, new_k, n2;
    sin[0] = 0;
    sin[half_pi] = ampls;
    for (step = half_pi; step > 1; step /= 2) {
        k = 0x10000;
        for (i = 0; i < half_pi / 2; i += step) {
            s = sin[i] + sin[i + step];
            c = sin[half_pi - i] + sin[half_pi - i - step];
            n2 = s * s + c * c;
            while (1) {
                new_k = (k + unit2 / ((uint64_t)k * n2) + 1) >> 1;
                if (k == new_k)
                    break;
                k = new_k;
            }
            sin[i + step / 2] = (k * s + 0x7FFF) >> 16;
            sin[half_pi - i - step / 2] = (k * c + 0x8000) >> 16;
        }
    }
    for (i = 0; i <= half_pi; i++)
        sin[i] = (sin[i] + (1 << (AMPLITUDE_SHIFT - 1))) >> AMPLITUDE_SHIFT;
    for (i = 0; i < half_pi; i++)
        sin[half_pi * 2 - i] = sin[i];
    for (i = 0; i < 2 * half_pi; i++)
        sin[i + 2 * half_pi] = -sin[i];
}

int parse_filter_opts(const char *args, const char *const *shorthand, char keys[][64], char vals[][256], int max)
{
    int n = 0, pos = 0;
    const char *p = args;
    int shorthand_ok = 1;
    while (p && *p && n < max) {
        char tok[512];
        int tl = 0;
        int depth = 0;
        while (*p && (depth || *p != ':')) {
            if (*p == '\\' && p[1]) { tok[tl++] = p[1]; p += 2; continue; }
            if (*p == '\'') { p++; while (*p && *p != '\'') { if (tl < 511) tok[tl++] = *p; p++; } if (*p) p++; continue; }
            if (*p == '(') depth++;
            if (*p == ')') depth--;
            if (tl < 511) tok[tl++] = *p;
            p++;
        }
        tok[tl] = 0;
        if (*p == ':') p++;
        char *eq = NULL;
        /* find '=' not inside parentheses */
        int d = 0;
        for (char *q = tok; *q; q++) {
            if (*q == '(') d++;
            else if (*q == ')') d--;
            else if (*q == '=' && d == 0) { eq = q; break; }
        }
        if (eq && shorthand_ok >= 0) {
            *eq = 0;
            snprintf(keys[n], 64, "%s", tok);
            snprintf(vals[n], 256, "%s", eq + 1);
            shorthand_ok = -1;
        } else if (!eq && shorthand_ok >= 0 && shorthand && shorthand[pos]) {
            snprintf(keys[n], 64, "%s", shorthand[pos]);
            snprintf(vals[n], 256, "%s", tok);
            pos++;
        } else if (eq) {
            *eq = 0;
            snprintf(keys[n], 64, "%s", tok);
            snprintf(vals[n], 256, "%s", eq + 1);
        } else {
            return AVERROR(22);
        }
        n++;
    }
    return n;
}

static int parse_duration_samples(const char *v, int64_t *us)
{
    return parse_time(us, v, 1);
}

int lavfi_open(LavfiSource **out, const char *spec, void *logctx)
{
    LavfiSource *s = calloc(1, sizeof(*s));
    char name[64];
    const char *args = strchr(spec, '=');
    int nl = args ? (int)(args - spec) : (int)strlen(spec);
    if (nl >= 64) nl = 63;
    memcpy(name, spec, nl); name[nl] = 0;
    if (args) args++;
    char keys[32][64], vals[32][256];
    int n;
    s->nb_samples = 1024;
    if (!strcmp(name, "sine")) {
        static const char *const sh[] = { "frequency", "beep_factor", "sample_rate", "duration", "samples_per_frame", NULL };
        double freq = 440, beep = 0;
        int64_t dur = 0;
        s->type = SRC_SINE;
        s->sample_rate = 44100;
        n = args ? parse_filter_opts(args, sh, keys, vals, 32) : 0;
        if (n < 0) { free(s); return n; }
        for (int i = 0; i < n; i++) {
            const char *k = keys[i], *v = vals[i];
            if (!strcmp(k, "frequency") || !strcmp(k, "f")) freq = strtod(v, NULL);
            else if (!strcmp(k, "beep_factor") || !strcmp(k, "b")) beep = strtod(v, NULL);
            else if (!strcmp(k, "sample_rate") || !strcmp(k, "r")) s->sample_rate = atoi(v);
            else if (!strcmp(k, "duration") || !strcmp(k, "d")) {
                if (parse_duration_samples(v, &dur) < 0) {
                    av_log(NULL, AV_LOG_ERROR, "Unable to parse option value \"%s\" as duration\n", v);
                    free(s); return AVERROR(22);
                }
            }
            else if (!strcmp(k, "samples_per_frame")) s->nb_samples = atoi(v);
            else {
                av_log(NULL, AV_LOG_ERROR, "Option '%s' not found\n", k);
                free(s); return AVERROR_OPTION_NOT_FOUND;
            }
        }
