        s->sin = malloc(sizeof(int16_t) << LOG_PERIOD);
        make_sin_table(s->sin);
        s->dphi = (uint32_t)(int64_t)(ldexp(freq, 32) / s->sample_rate + 0.5);
        if (beep) {
            s->beep_period = s->sample_rate;
            s->beep_length = s->beep_period / 25;
            s->dphi_beep = (uint32_t)(int64_t)(ldexp(beep * freq, 32) / s->sample_rate + 0.5);
        }
        s->duration = dur ? av_rescale(dur, s->sample_rate, AV_TIME_BASE) : 0;
        s->sample_fmt = SF_S16;
    } else if (!strcmp(name, "anullsrc")) {
        static const char *const sh[] = { "channel_layout", "sample_rate", "nb_samples", "duration", NULL };
        int64_t dur = -1;
        s->type = SRC_ANULL;
        s->sample_rate = 44100;
        chl_default(&s->layout, 2);
        n = args ? parse_filter_opts(args, sh, keys, vals, 32) : 0;
        if (n < 0) { free(s); return n; }
        for (int i = 0; i < n; i++) {
            const char *k = keys[i], *v = vals[i];
            if (!strcmp(k, "channel_layout") || !strcmp(k, "cl")) chl_from_string(&s->layout, v);
            else if (!strcmp(k, "sample_rate") || !strcmp(k, "r")) s->sample_rate = atoi(v);
            else if (!strcmp(k, "nb_samples") || !strcmp(k, "n")) s->nb_samples = atoi(v);
            else if (!strcmp(k, "duration") || !strcmp(k, "d")) parse_duration_samples(v, &dur);
            else { free(s); return AVERROR_OPTION_NOT_FOUND; }
        }
        s->duration = dur >= 0 ? av_rescale(dur, s->sample_rate, AV_TIME_BASE) : 0;
        if (dur == 0) s->duration = -1;
        s->sample_fmt = SF_U8;
    } else if (!strcmp(name, "aevalsrc")) {
        static const char *const sh[] = { "exprs", "channel_layout", "duration", "nb_samples", "sample_rate", NULL };
        int64_t dur = -1;
        s->type = SRC_AEVAL;
        s->sample_rate = 44100;
        char exprs[1024] = "";
        char cl[64] = "";
        n = args ? parse_filter_opts(args, sh, keys, vals, 32) : 0;
        if (n < 0) { free(s); return n; }
        for (int i = 0; i < n; i++) {
            const char *k = keys[i], *v = vals[i];
            if (!strcmp(k, "exprs")) snprintf(exprs, sizeof(exprs), "%s", v);
            else if (!strcmp(k, "channel_layout") || !strcmp(k, "c")) snprintf(cl, sizeof(cl), "%s", v);
            else if (!strcmp(k, "sample_rate") || !strcmp(k, "s")) s->sample_rate = atoi(v);
            else if (!strcmp(k, "nb_samples") || !strcmp(k, "n")) s->nb_samples = atoi(v);
            else if (!strcmp(k, "duration") || !strcmp(k, "d")) parse_duration_samples(v, &dur);
            else { free(s); return AVERROR_OPTION_NOT_FOUND; }
        }
        /* split exprs by '|' */
        char *save, *tok = strtok_r(exprs, "|", &save);
        while (tok && s->nb_exprs < 8) {
            static const char *const vars[] = { "ch", "n", "s", "t", NULL };
            if (expr_parse(&s->exprs[s->nb_exprs], tok, vars) < 0) { free(s); return AVERROR(22); }
            s->nb_exprs++;
            tok = strtok_r(NULL, "|", &save);
        }
        if (!s->nb_exprs) { free(s); return AVERROR(22); }
        if (cl[0]) chl_from_string(&s->layout, cl);
        else chl_default(&s->layout, s->nb_exprs);
        s->duration = dur >= 0 ? av_rescale(dur, s->sample_rate, AV_TIME_BASE) : 0;
        s->sample_fmt = SF_DBL;
    } else {
        av_log(logctx, AV_LOG_ERROR, "No such filter: '%s'\n", name);
        free(s);
        return AVERROR_FILTER_NOT_FOUND;
    }
    *out = s;
    return 0;
}

int lavfi_codec_id(LavfiSource *s)
{
    switch (s->sample_fmt) {
    case SF_U8: return CID_PCM_U8;
    case SF_S16: return CID_PCM_S16LE;
    case SF_DBL: return CID_PCM_F64LE;
    }
    return CID_PCM_S16LE;
}
int lavfi_sample_rate(LavfiSource *s) { return s->sample_rate; }
ChLayout lavfi_layout(LavfiSource *s) { return s->layout; }
int lavfi_sample_fmt(LavfiSource *s) { return s->sample_fmt; }

int lavfi_read(LavfiSource *s, Packet *pkt)
{
    int nb = s->nb_samples;
    if (s->duration < 0) return AVERROR_EOF;
    if (s->duration > 0) {
        int64_t left = s->duration - s->pts;
        if (left <= 0) return AVERROR_EOF;
        if (nb > left) nb = (int)left;
    }
    int ch = s->layout.nb_channels;
    int bps = sf_bytes(s->sample_fmt);
    pkt->size = nb * ch * bps;
    pkt->data = calloc(1, pkt->size + 64);
    if (s->type == SRC_SINE) {
        int16_t *samples = (int16_t *)pkt->data;
        for (int i = 0; i < nb; i++) {
            samples[i] = s->sin[s->phi >> (32 - LOG_PERIOD)];
            s->phi += s->dphi;
            if (s->beep_index < s->beep_length) {
                samples[i] += s->sin[s->phi_beep >> (32 - LOG_PERIOD)] * 2;
                s->phi_beep += s->dphi_beep;
            }
            if (++s->beep_index == s->beep_period)
                s->beep_index = 0;
        }
    } else if (s->type == SRC_ANULL) {
        memset(pkt->data, 0x80, pkt->size);
    } else if (s->type == SRC_AEVAL) {
        double *d = (double *)pkt->data;
        for (int i = 0; i < nb; i++) {
            double t = (double)(s->pts + i) / s->sample_rate;
            for (int c = 0; c < ch; c++) {
                double vars[4] = { c, (double)(s->pts + i), s->sample_rate, t };
                Expr *e = s->exprs[c < s->nb_exprs ? c : s->nb_exprs - 1];
                d[i * ch + c] = expr_eval(e, vars);
            }
        }
    }
    pkt->pts = pkt->dts = s->pts;
    pkt->duration = nb;
    pkt->flags = PKT_FLAG_KEY;
    pkt->stream_index = 0;
    s->pts += nb;
    return 0;
}

void lavfi_free(LavfiSource *s)
{
    if (!s) return;
    free(s->sin);
    for (int i = 0; i < s->nb_exprs; i++) expr_free(s->exprs[i]);
    free(s);
}
EOF
echo ok"}

