int lavfi_codec_id(LavfiSource *s)
{
    switch (s->sample_fmt) {
    case SF_U8: return CID_PCM_U8;
    case SF_S16: return CID_PCM_S16LE;
    case SF_DBL: return CID_PCM_F64LE;
