    p->s++;
    Expr *a = parse_expr(p), *b = NULL, *c = NULL;
    skip_ws(p);
    if (*p->s == ',') { p->s++; b = parse_expr(p); skip_ws(p); }
    if (*p->s == ',') { p->s++; c = parse_expr(p); skip_ws(p); }
    if (*p->s != ')') { expr_free(a); expr_free(b); expr_free(c); return NULL; }
    p->s++;
    Expr *e = NULL;
    static const struct { const char *n; double (*f)(double); } f1[] = {
        {"sin",sin},{"cos",cos},{"tan",tan},{"asin",asin},{"acos",acos},{"atan",atan},{"sinh",sinh},{"cosh",cosh},
        {"tanh",tanh},{"exp",exp},{"log",log},{"sqrt",sqrt},{"abs",fabs},{"floor",floor},{"ceil",ceil},{"trunc",f_trunc},
        {"round",f_round},{"not",f_not},{"squish",f_squish},{"gauss",f_gauss},{"isnan",f_isnan},{"isinf",f_isinf},{"sgn",f_sgn},
        {"cbrt",cbrt}};
    static const struct { const char *n; double (*f)(double, double); } f2[] = {
        {"gt",f_gt},{"lt",f_lt},{"gte",f_gte},{"lte",f_lte},{"eq",f_eq},{"min",f_min},{"max",f_max},{"mod",f_mod},
        {"hypot",f_hypot},{"pow",f_pow},{"atan2",f_atan2}};
    for (size_t i = 0; i < sizeof(f1)/sizeof(f1[0]); i++)
        if (!strcmp(name, f1[i].n)) { e = new_e(E_FUNC1); e->f1 = f1[i].f; e->a = a; expr_free(b); expr_free(c); return e; }
    for (size_t i = 0; i < sizeof(f2)/sizeof(f2[0]); i++)
        if (!strcmp(name, f2[i].n)) { e = new_e(E_FUNC2); e->f2 = f2[i].f; e->a = a; e->b = b; expr_free(c); return e; }
    if (!strcmp(name, "if")) { e = new_e(E_IF); e->a = a; e->b = b; e->c = c; return e; }
    if (!strcmp(name, "ifnot")) { e = new_e(E_IFNOT); e->a = a; e->b = b; e->c = c; return e; }
    if (!strcmp(name, "random")) { e = new_e(E_RAND); e->a = a; return e; }
    if (!strcmp(name, "ld")) { e = new_e(E_LD); e->a = a; return e; }
    if (!strcmp(name, "st")) { e = new_e(E_ST); e->a = a; e->b = b; return e; }
    if (!strcmp(name, "clip")) { e = new_e(E_CLIP); e->a = a; e->b = b; e->c = c; return e; }
    if (!strcmp(name, "between")) { e = new_e(E_BETWEEN); e->a = a; e->b = b; e->c = c; return e; }
    expr_free(a); expr_free(b); expr_free(c);
    return NULL;
}

static Expr *parse_factor(Parser *p);
static Expr *parse_pow(Parser *p)
{
    Expr *e = parse_primary(p);
    if (!e) return NULL;
    skip_ws(p);
    while (*p->s == '^') {
        p->s++;
        Expr *r = parse_factor(p);
        if (!r) { expr_free(e); return NULL; }
        Expr *n = new_e(E_POW); n->a = e; n->b = r; e = n;
        skip_ws(p);
    }
    return e;
}
static Expr *parse_factor(Parser *p)
{
    skip_ws(p);
    int sign = 1;
    while (*p->s == '+' || *p->s == '-') { if (*p->s == '-') sign = -sign; p->s++; skip_ws(p); }
    Expr *e = parse_pow(p);
    if (!e) return NULL;
    if (sign < 0) { Expr *n = new_e(E_NEG); n->a = e; e = n; }
    return e;
}
static Expr *parse_term(Parser *p)
{
    Expr *e = parse_factor(p);
    if (!e) return NULL;
    skip_ws(p);
    while (*p->s == '*' || *p->s == '/') {
        int t = *p->s == '*' ? E_MUL : E_DIV;
        p->s++;
        Expr *r = parse_factor(p);
        if (!r) { expr_free(e); return NULL; }
        Expr *n = new_e(t); n->a = e; n->b = r; e = n;
        skip_ws(p);
    }
    return e;
}
static Expr *parse_subexpr(Parser *p)
{
    Expr *e = parse_term(p);
    if (!e) return NULL;
    skip_ws(p);
    while (*p->s == '+' || *p->s == '-') {
        int t = *p->s == '+' ? E_ADD : E_SUB;
        p->s++;
        Expr *r = parse_term(p);
        if (!r) { expr_free(e); return NULL; }
        Expr *n = new_e(t); n->a = e; n->b = r; e = n;
        skip_ws(p);
    }
    return e;
}
static Expr *parse_expr(Parser *p)
{
    Expr *e = parse_subexpr(p);
    if (!e) return NULL;
    skip_ws(p);
    while (*p->s == ';') {
        p->s++;
        Expr *r = parse_subexpr(p);
        if (!r) { expr_free(e); return NULL; }
        Expr *n = new_e(E_SEQ); n->a = e; n->b = r; e = n;
        skip_ws(p);
    }
    return e;
}

int expr_parse(Expr **out, const char *s, const char *const *vars)
{
    Parser p = { s, vars, regs_global };
    Expr *e = parse_expr(&p);
    skip_ws(&p);
    if (!e || *p.s) { expr_free(e); return -22; }
    *out = e;
    return 0;
}

static double regs[10];
double expr_eval(Expr *e, const double *vars)
{
    switch (e->type) {
    case E_VALUE: return e->value;
    case E_VAR: return vars[e->var];
    case E_NEG: return -expr_eval(e->a, vars);
    case E_ADD: return expr_eval(e->a, vars) + expr_eval(e->b, vars);
    case E_SUB: return expr_eval(e->a, vars) - expr_eval(e->b, vars);
    case E_MUL: return expr_eval(e->a, vars) * expr_eval(e->b, vars);
    case E_DIV: { double b = expr_eval(e->b, vars); double a = expr_eval(e->a, vars); return b ? a / b : a * INFINITY; }
    case E_POW: return pow(expr_eval(e->a, vars), expr_eval(e->b, vars));
    case E_FUNC1: return e->f1(expr_eval(e->a, vars));
    case E_FUNC2: return e->f2(expr_eval(e->a, vars), e->b ? expr_eval(e->b, vars) : 0);
    case E_SEQ: expr_eval(e->a, vars); return expr_eval(e->b, vars);
    case E_IF: return expr_eval(e->a, vars) ? expr_eval(e->b, vars) : (e->c ? expr_eval(e->c, vars) : 0);
    case E_IFNOT: return !expr_eval(e->a, vars) ? expr_eval(e->b, vars) : (e->c ? expr_eval(e->c, vars) : 0);
    case E_RAND: {
        int idx = av_clip((int)expr_eval(e->a, vars), 0, 9);
        uint64_t r = (uint64_t)regs[idx];
        r = r * 1664525 + 1013904223;
        regs[idx] = (double)r;
        return e->value = (double)(r & 0xffffffff) / 4294967295.0; }
    case E_LD: return regs[av_clip((int)expr_eval(e->a, vars), 0, 9)];
    case E_ST: { double v = expr_eval(e->b, vars); regs[av_clip((int)expr_eval(e->a, vars), 0, 9)] = v; return v; }
    case E_CLIP: { double x = expr_eval(e->a, vars), lo = expr_eval(e->b, vars), hi = expr_eval(e->c, vars); return x < lo ? lo : x > hi ? hi : x; }
    case E_BETWEEN: { double x = expr_eval(e->a, vars); return x >= expr_eval(e->b, vars) && x <= expr_eval(e->c, vars); }
    }
    return 0;
}

int expr_parse_and_eval(double *res, const char *s)
{
    Expr *e;
    int r = expr_parse(&e, s, NULL);
    if (r < 0) return r;
    *res = expr_eval(e, NULL);
    expr_free(e);
    return 0;
}
