typedef struct FlacMux {
    uint8_t streaminfo[34];
    int have_si;
} FlacMux;

static const FmtOpt flac_mux_opts[] = {
    { "write_header", 2, "true", 0, 1 },
    { NULL }
};

static int flac_init(FormatContext *s)
{
    int audio = -1;
    for (int i = 0; i < s->nb_streams; i++) {
        Stream *st = s->streams[i];
        if (st->par.codec_type == MT_AUDIO) {
            if (audio >= 0 || st->par.codec_id != CID_FLAC) {
                av_log(s, AV_LOG_ERROR, "Invalid audio stream. Exactly one FLAC audio stream is required.\n");
                return AVERROR(22);
            }
            audio = i;
        } else {
            av_log(s, AV_LOG_ERROR, "Only audio streams and pictures are allowed in FLAC.\n");
            return AVERROR(22);
        }
    }
    if (audio < 0) {
        av_log(s, AV_LOG_ERROR, "No audio stream present.\n");
        return AVERROR(22);
    }
    s->streams[audio]->time_base = (Rational){ 1, s->streams[audio]->par.sample_rate };
    s->priv = calloc(1, sizeof(FlacMux));
    return 0;
}

static int64_t vorbiscomment_length(Dict *m, const char *vendor)
{
    int64_t len = 8 + strlen(vendor);
    for (int i = 0; i < m->count; i++)
        len += 4 + strlen(m->e[i].key) + 1 + strlen(m->e[i].value);
    return len;
}

static void metadata_conv_vorbis(Dict *m)
{
    static const char *conv[][2] = { { "ALBUMARTIST", "album_artist" }, { "TRACKNUMBER", "track" },
                                     { "DISCNUMBER", "disc" }, { "DESCRIPTION", "comment" } };
    Dict out = { 0 };
    for (int i = 0; i < m->count; i++) {
        const char *k = m->e[i].key;
        for (int j = 0; j < 4; j++)
            if (!strcasecmp(k, conv[j][1])) { k = conv[j][0]; break; }
        dict_set(&out, k, m->e[i].value);
    }
    dict_free(m);
    *m = out;
}

static int flac_is_native_layout(uint64_t mask)
{
    static const uint64_t native[] = { 0x4, 0x3, 0x7, 0x33, 0x37, 0x3f, 0x70f, 0x63f };
    for (int i = 0; i < 8; i++) if (native[i] == mask) return 1;
    return 0;
}

static int flac_write_header(FormatContext *s)
{
    FlacMux *c = s->priv;
    Stream *st = s->streams[0];
    if (!fmt_opt_int(s, flac_mux_opts, "write_header")) return 0;
    if (!st->par.extradata || st->par.extradata_size < 34) return AVERROR_INVALIDDATA;
    uint8_t hdr[8] = { 'f', 'L', 'a', 'C', 0, 0, 0, 0x22 };
    avio_write(s->pb, hdr, 8);
    avio_write(s->pb, st->par.extradata, 34);
    memcpy(c->streaminfo, st->par.extradata, 34);
    if (st->par.ch_layout.order == 1 && !(st->par.ch_layout.mask & ~0x3ffffULL) &&
        !flac_is_native_layout(st->par.ch_layout.mask)) {
        if (dict_get(&s->metadata, "WAVEFORMATEXTENSIBLE_CHANNEL_MASK")) {
            av_log(s, AV_LOG_WARNING, "A WAVEFORMATEXTENSIBLE_CHANNEL_MASK is "
                   "already present, this muxer will not overwrite it.\n");
        } else {
            char buf[32];
            snprintf(buf, sizeof(buf), "0x%"PRIx64, st->par.ch_layout.mask);
            dict_set(&s->metadata, "WAVEFORMATEXTENSIBLE_CHANNEL_MASK", buf);
        }
    }
    const char *vendor = s->bitexact ? "ffmpeg" : LIBAVFORMAT_IDENT;
    metadata_conv_vorbis(&s->metadata);
    int64_t len = vorbiscomment_length(&s->metadata, vendor);
    avio_w8(s->pb, 0x04);
    avio_wb24(s->pb, (unsigned)len);
    avio_wl32(s->pb, (unsigned)strlen(vendor));
    avio_write(s->pb, (const uint8_t *)vendor, (int)strlen(vendor));
    avio_wl32(s->pb, s->metadata.count);
    for (int i = 0; i < s->metadata.count; i++) {
        size_t l1 = strlen(s->metadata.e[i].key), l2 = strlen(s->metadata.e[i].value);
        avio_wl32(s->pb, (unsigned)(l1 + 1 + l2));
        avio_write(s->pb, (const uint8_t *)s->metadata.e[i].key, (int)l1);
        avio_w8(s->pb, '=');
        avio_write(s->pb, (const uint8_t *)s->metadata.e[i].value, (int)l2);
    }
    /* padding */
    avio_w8(s->pb, 0x81);
    avio_wb24(s->pb, 8192);
    uint8_t zero[1024] = { 0 };
    for (int i = 0; i < 8; i++) avio_write(s->pb, zero, 1024);
    return 0;
}

static int flac_write_packet(FormatContext *s, Packet *pkt)
{
    FlacMux *c = s->priv;
    if (pkt->new_extradata && pkt->new_extradata_size == 34) {
        memcpy(c->streaminfo, pkt->new_extradata, 34);
        c->have_si = 1;
    }
    if (pkt->size)
        avio_write(s->pb, pkt->data, pkt->size);
    return 0;
}

static int flac_write_trailer(FormatContext *s)
{
    FlacMux *c = s->priv;
    if (!fmt_opt_int(s, flac_mux_opts, "write_header")) return 0;
    if (s->pb->seekable) {
        int64_t end = avio_wtell(s->pb);
        avio_wseek(s->pb, 8);
        avio_write(s->pb, c->streaminfo, 34);
        avio_wseek(s->pb, end);
    } else {
        av_log(s, AV_LOG_WARNING, "unable to rewrite FLAC header.\n");
    }
    return 0;
}

static void flac_deinit(FormatContext *s) { free(s->priv); s->priv = NULL; }

