    return avio_wtell(pb);
}
static void end_tag(AVIO *pb, int64_t start)
{
    int64_t pos = avio_wtell(pb);
    if (pos & 1) { avio_w8(pb, 0); }
    if (avio_wseek(pb, start - 4) >= 0) {
        avio_wl32(pb, (uint32_t)(pos - start));
        avio_wseek(pb, (pos + 1) & ~1);
