static void framehash_common_header(FormatContext *s)
{
    if (s->nb_streams && !s->bitexact)
        avio_printf(s->pb, "#software: %s\n", LIBAVFORMAT_IDENT);
    for (int i = 0; i < s->nb_streams; i++) {
        Stream *st = s->streams[i];
        char buf[256];
        avio_printf(s->pb, "#tb %d: %d/%d\n", i, st->time_base.num, st->time_base.den);
        avio_printf(s->pb, "#media_type %d: %s\n", i, media_type_string(st->par.codec_type));
        const CodecDesc *d = codec_desc(st->par.codec_id);
        avio_printf(s->pb, "#codec_id %d: %s\n", i, d ? d->name : "none");
        if (st->par.codec_type == MT_AUDIO) {
            chl_describe(&st->par.ch_layout, buf, sizeof(buf));
            avio_printf(s->pb, "#sample_rate %d: %d\n", i, st->par.sample_rate);
            avio_printf(s->pb, "#channel_layout_name %d: %s\n", i, buf);
        }
    }
}

static int framehash_write_header(FormatContext *s)
{
    HashMux *c = s->priv;
    avio_printf(s->pb, "#format: frame checksums\n");
    avio_printf(s->pb, "#version: %d\n", c->format_version);
    avio_printf(s->pb, "#hash: %s\n", hash_name(c->h[0]));
    for (int i = 0; i < s->nb_streams; i++) {
        CodecPar *par = &s->streams[i]->par;
        if (par->extradata) {
            char hex[200];
            avio_printf(s->pb, "#extradata %d, %31d, ", i, par->extradata_size);
            hash_init(c->h[0]);
            hash_update(c->h[0], par->extradata, par->extradata_size);
            hash_final_hex(c->h[0], hex);
            avio_printf(s->pb, "%s\n", hex);
        }
    }
    framehash_common_header(s);
    avio_printf(s->pb, "#stream#, dts,        pts, duration,     size, hash\n");
    return 0;
}

static int framehash_write_packet(FormatContext *s, Packet *pkt)
{
    HashMux *c = s->priv;
    char hex[200];
    hash_init(c->h[0]);
    hash_update(c->h[0], pkt->data, pkt->size);
    hash_final_hex(c->h[0], hex);
    avio_printf(s->pb, "%d, %10"PRId64", %10"PRId64", %8"PRId64", %8d, %s",
                pkt->stream_index, pkt->dts, pkt->pts, pkt->duration, pkt->size, hex);
    if (c->format_version > 1 && pkt->new_extradata) {
        avio_printf(s->pb, ", S=%d", 1);
        hash_init(c->h[0]);
        hash_update(c->h[0], pkt->new_extradata, pkt->new_extradata_size);
        hash_final_hex(c->h[0], hex);
        avio_printf(s->pb, ", %8d, %s", pkt->new_extradata_size, hex);
    }
    avio_printf(s->pb, "\n");
    return 0;
}

static int framehash_init_cb(FormatContext *s) { return hash_common_init(s, 0); }

