static int framecrc_write_header(FormatContext *s)
{
    for (int i = 0; i < s->nb_streams; i++) {
        CodecPar *par = &s->streams[i]->par;
        if (par->extradata) {
            uint32_t crc = adler32_update(0, par->extradata, par->extradata_size);
            avio_printf(s->pb, "#extradata %d: %8d, 0x%08"PRIx32"\n", i, par->extradata_size, crc);
        }
    }
    framehash_common_header(s);
    return 0;
}
static int framecrc_write_packet(FormatContext *s, Packet *pkt)
{
    uint32_t crc = adler32_update(0, pkt->data, pkt->size);
    char buf[512];
    int n = snprintf(buf, sizeof(buf), "%d, %10"PRId64", %10"PRId64", %8"PRId64", %8d, 0x%08"PRIx32,
                     pkt->stream_index, pkt->dts, pkt->pts, pkt->duration, pkt->size, crc);
    if (pkt->flags != PKT_FLAG_KEY)
        n += snprintf(buf + n, sizeof(buf) - n, ", F=0x%0X", pkt->flags);
    if (pkt->new_extradata) {
        n += snprintf(buf + n, sizeof(buf) - n, ", S=%d", 1);
        uint32_t sc = adler32_update(0, pkt->new_extradata, pkt->new_extradata_size);
        n += snprintf(buf + n, sizeof(buf) - n, ", %s, %8d, 0x%08"PRIx32, "New Extradata", pkt->new_extradata_size, sc);
    }
    n += snprintf(buf + n, sizeof(buf) - n, "\n");
    avio_write(s->pb, (uint8_t *)buf, n);
    return 0;
}
