    flac_init, flac_write_header, flac_write_packet, flac_write_trailer, flac_deinit, flac_mux_opts, 0
};

/* ---------------- WAV ---------------- */
typedef struct WavMux {
    int64_t data;
    int64_t fact_pos;
    int64_t minpts, maxpts, last_duration;
} WavMux;

static const FmtOpt wav_mux_opts[] = {
    { "write_bext", 2, "false", 0, 1 },
    { "write_peak", 0, "0", 0, 2 },
    { "rf64", 0, "0", -1, 1 },
    { "peak_block_size", 0, "256", 0, 65536 },
    { "peak_format", 0, "2", 1, 2 },
    { "peak_ppv", 0, "2", 1, 2 },
    { NULL }
};

static int wav_init(FormatContext *s)
{
    if (s->nb_streams != 1) {
        av_log(s, AV_LOG_ERROR, "WAVE files have exactly one stream\n");
        return AVERROR(22);
    }
    Stream *st = s->streams[0];
    if (!st->par.codec_tag) st->par.codec_tag = wav_tag_from_codec(st->par.codec_id);
    st->time_base = (Rational){ 1, st->par.sample_rate };
    s->priv = calloc(1, sizeof(WavMux));
    return 0;
}

static int64_t start_tag(AVIO *pb, const char *tag)
{
    avio_write(pb, (const uint8_t *)tag, 4);
    avio_wl32(pb, 0xFFFFFFFF);
    return avio_wtell(pb);
}
static void end_tag(AVIO *pb, int64_t start)
{
    int64_t pos = avio_wtell(pb);
    if (pos & 1) { avio_w8(pb, 0); }
    if (avio_wseek(pb, start - 4) >= 0) {
        avio_wl32(pb, (uint32_t)(pos - start));
        avio_wseek(pb, (pos + 1) & ~1);
    }
}

static int put_wav_header(FormatContext *s, AVIO *pb, CodecPar *par)
{
    int bps, blkalign, bytespersec;
    int64_t hdrstart = avio_wtell(pb);
    int is_mono_stereo = par->ch_layout.order == 1 && (par->ch_layout.mask == 0x4 || par->ch_layout.mask == 0x3);
    int waveformatextensible = (par->ch_layout.order == 1 && !is_mono_stereo) ||
                               par->sample_rate > 48000 ||
                               get_bits_per_sample(par->codec_id) > 16;
    if (!par->codec_tag || par->codec_tag > 0xffff) return -1;
    if (waveformatextensible) avio_wl16(pb, 0xfffe);
    else avio_wl16(pb, par->codec_tag);
    avio_wl16(pb, par->ch_layout.nb_channels);
    avio_wl32(pb, par->sample_rate);
    if (!(bps = get_bits_per_sample(par->codec_id))) {
        if (par->bits_per_coded_sample) bps = par->bits_per_coded_sample;
        else bps = 16;
    }
    if (bps != par->bits_per_coded_sample && par->bits_per_coded_sample)
        av_log(s, AV_LOG_WARNING, "requested bits_per_coded_sample (%d) and actually stored (%d) differ\n",
               par->bits_per_coded_sample, bps);
    if (par->block_align != 0) blkalign = par->block_align;
    else {
        int g = bps % 8 == 0 ? 8 : (bps % 4 == 0 ? 4 : (bps % 2 == 0 ? 2 : 1));
        blkalign = bps * par->ch_layout.nb_channels / g;
    }
    if (par->codec_id == CID_PCM_U8 || par->codec_id == CID_PCM_S24LE || par->codec_id == CID_PCM_S32LE ||
        par->codec_id == CID_PCM_F32LE || par->codec_id == CID_PCM_F64LE || par->codec_id == CID_PCM_S16LE)
        bytespersec = par->sample_rate * blkalign;
    else
        bytespersec = (int)(par->bit_rate / 8);
    avio_wl32(pb, bytespersec);
    avio_wl16(pb, blkalign);
    avio_wl16(pb, bps);
    int extra = par->extradata_size;
    if (waveformatextensible) {
        int write_channel_mask = par->ch_layout.order == 1 && par->ch_layout.mask < 0x40000;
        avio_wl16(pb, extra + 22);
        avio_wl16(pb, bps);
        avio_wl32(pb, write_channel_mask ? (uint32_t)par->ch_layout.mask : 0);
        avio_wl32(pb, par->codec_tag);
        avio_wl32(pb, 0x00100000);
        avio_wl32(pb, 0xAA000080);
        avio_wl32(pb, 0x719B3800);
    } else if (par->codec_tag != 0x0001 || extra) {
        avio_wl16(pb, extra);
    }
    if (extra) avio_write(pb, par->extradata, extra);
    int64_t hdrsize = avio_wtell(pb) - hdrstart;
    if (hdrsize & 1) { hdrsize++; avio_w8(pb, 0); }
    return (int)hdrsize;
}

static const char *riff_tags[] = {
    "IARL", "IART", "IAS1", "IAS2", "IAS3", "IAS4", "IAS5", "IAS6", "IAS7",
    "IAS8", "IAS9", "ICMS", "ICMT", "ICOP", "ICRD", "ICRP", "IDIM", "IDPI",
    "IENG", "IGNR", "IKEY", "ILGT", "ILNG", "IMED", "INAM", "IPLT", "IPRD",
    "IPRT", "ITRK", "ISBJ", "ISFT", "ISHP", "ISMP", "ISRC", "ISRF", "ITCH",
    NULL
};

static void riff_write_info(FormatContext *s)
{
    AVIO *pb = s->pb;
    /* convert metadata keys to riff */
    Dict out = { 0 };
    for (int i = 0; i < s->metadata.count; i++)
        dict_set(&out, generic_to_riff(s->metadata.e[i].key), s->metadata.e[i].value);
    dict_free(&s->metadata);
    s->metadata = out;
    int has = 0;
    for (int i = 0; riff_tags[i]; i++) {
        for (int j = 0; j < s->metadata.count; j++)
            if (!strcmp(s->metadata.e[j].key, riff_tags[i])) has = 1;
    }
    if (!has) return;
    int64_t list_pos = start_tag(pb, "LIST");
    avio_write(pb, (const uint8_t *)"INFO", 4);
    for (int i = 0; riff_tags[i]; i++) {
        for (int j = 0; j < s->metadata.count; j++) {
            if (!strcmp(s->metadata.e[j].key, riff_tags[i])) {
                const char *str = s->metadata.e[j].value;
                size_t len = strlen(str);
                if (len > 0) {
                    len++;
                    avio_write(pb, (const uint8_t *)riff_tags[i], 4);
                    avio_wl32(pb, (unsigned)len);
                    avio_write(pb, (const uint8_t *)str, (int)len);
                    if (len & 1) avio_w8(pb, 0);
                }
                break;
            }
        }
    }
    end_tag(pb, list_pos);
}

static int wav_write_header(FormatContext *s)
{
    WavMux *w = s->priv;
    AVIO *pb = s->pb;
    int rf64 = (int)fmt_opt_int(s, wav_mux_opts, "rf64");
    if (rf64 == 1) {
        avio_write(pb, (const uint8_t *)"RF64", 4);
        avio_wl32(pb, 0xFFFFFFFF);
    } else {
        avio_write(pb, (const uint8_t *)"RIFF", 4);
        avio_wl32(pb, 0xFFFFFFFF);
    }
    avio_write(pb, (const uint8_t *)"WAVE", 4);
    if (rf64 != 0) {
        avio_write(pb, (const uint8_t *)(rf64 == 1 ? "ds64" : "JUNK"), 4);
        avio_wl32(pb, 28);
        for (int i = 0; i < 28; i++) avio_w8(pb, 0);
    }
    int64_t fmt = start_tag(pb, "fmt ");
    if (put_wav_header(s, pb, &s->streams[0]->par) < 0) {
        const CodecDesc *d = codec_desc(s->streams[0]->par.codec_id);
        av_log(s, AV_LOG_ERROR, "Codec %s not supported in WAVE format\n", d ? d->name : "none");
        return AVERROR(38);
    }
    end_tag(pb, fmt);
    if (s->streams[0]->par.codec_tag != 0x01 && pb->seekable) {
        w->fact_pos = start_tag(pb, "fact");
        avio_wl32(pb, 0);
        end_tag(pb, w->fact_pos);
    }
    w->maxpts = w->last_duration = 0;
    w->minpts = INT64_MAX;
    riff_write_info(s);
    w->data = start_tag(pb, "data");
    return 0;
}

static int wav_write_packet(FormatContext *s, Packet *pkt)
{
    WavMux *w = s->priv;
    avio_write(s->pb, pkt->data, pkt->size);
    if (pkt->pts != AV_NOPTS_VALUE) {
        if (pkt->pts < w->minpts) w->minpts = pkt->pts;
        if (pkt->pts > w->maxpts) w->maxpts = pkt->pts;
    }
    w->last_duration = pkt->duration;
    return 0;
}

static int wav_write_trailer(FormatContext *s)
{
    WavMux *w = s->priv;
    AVIO *pb = s->pb;
    if (pb->seekable) {
        if (avio_wtell(pb) - w->data < UINT32_MAX)
            end_tag(pb, w->data);
        int64_t file_size = avio_wtell(pb);
        if (file_size - 8 <= UINT32_MAX) {
            avio_wseek(pb, 4);
            avio_wl32(pb, (uint32_t)(file_size - 8));
            avio_wseek(pb, file_size);
        }
        if (s->streams[0]->par.codec_tag != 0x01) {
            int64_t ns = w->maxpts - w->minpts + w->last_duration;
            avio_wseek(pb, w->fact_pos);
            avio_wl32(pb, (uint32_t)ns);
            avio_wseek(pb, file_size);
        }
    }
    return 0;
}

static void wav_deinit(FormatContext *s) { free(s->priv); s->priv = NULL; }

