    wav_init, wav_write_header, wav_write_packet, wav_write_trailer, wav_deinit, wav_mux_opts, 0
};

/* ---------------- hash muxers ---------------- */
typedef struct HashMux {
    HashCtx *h[32];
    int per_stream;
    int format_version;
    uint32_t crc;
} HashMux;

static const FmtOpt hash_md5_opts[] = { { "hash", 1, "md5", 0, 0 }, { NULL } };
static const FmtOpt hash_sha_opts[] = { { "hash", 1, "sha256", 0, 0 }, { NULL } };
static const FmtOpt fhash_md5_opts[] = { { "hash", 1, "md5", 0, 0 }, { "format_version", 0, "2", 1, 2 }, { NULL } };
static const FmtOpt fhash_sha_opts[] = { { "hash", 1, "sha256", 0, 0 }, { "format_version", 0, "2", 1, 2 }, { NULL } };

static int hash_common_init(FormatContext *s, int per_stream)
{
    HashMux *c = calloc(1, sizeof(*c));
    s->priv = c;
    const char *hname = fmt_opt_get(s, s->ofmt->opts, "hash");
    c->per_stream = per_stream;
    int n = per_stream ? s->nb_streams : 1;
    for (int i = 0; i < n && i < 32; i++) {
        c->h[i] = hash_alloc(hname);
        if (!c->h[i]) return AVERROR(22);
        hash_init(c->h[i]);
    }
    if (fmt_has_option(s->ofmt->opts, "format_version"))
        c->format_version = (int)fmt_opt_int(s, s->ofmt->opts, "format_version");
    for (int i = 0; i < s->nb_streams; i++)
        if (s->streams[i]->par.codec_type == MT_AUDIO && s->streams[i]->par.sample_rate)
            s->streams[i]->time_base = (Rational){ 1, s->streams[i]->par.sample_rate };
    return 0;
}
static int hash_init_cb(FormatContext *s) { return hash_common_init(s, 0); }
static int streamhash_init_cb(FormatContext *s) { return hash_common_init(s, 1); }

static int hash_write_packet(FormatContext *s, Packet *pkt)
{
    HashMux *c = s->priv;
    int j = c->per_stream ? pkt->stream_index : 0;
    hash_update(c->h[j], pkt->data, pkt->size);
    return 0;
}

static int hash_write_trailer(FormatContext *s)
{
    HashMux *c = s->priv;
    int n = c->per_stream ? s->nb_streams : 1;
    for (int i = 0; i < n; i++) {
        char hex[200];
        hash_final_hex(c->h[i], hex);
        if (c->per_stream) {
            const char *mt = media_type_string(s->streams[i]->par.codec_type);
            avio_printf(s->pb, "%d,%c,%s=%s\n", i, mt ? mt[0] : '?', hash_name(c->h[i]), hex);
        } else
            avio_printf(s->pb, "%s=%s\n", hash_name(c->h[i]), hex);
    }
    return 0;
}

static void hash_deinit(FormatContext *s)
{
    HashMux *c = s->priv;
    if (!c) return;
    for (int i = 0; i < 32; i++) if (c->h[i]) hash_free(c->h[i]);
    free(c);
    s->priv = NULL;
}

