/* crc / framecrc */
static int crc_init_cb(FormatContext *s)
{
    HashMux *c = calloc(1, sizeof(*c));
    s->priv = c;
    c->crc = 1;
    for (int i = 0; i < s->nb_streams; i++)
        if (s->streams[i]->par.codec_type == MT_AUDIO && s->streams[i]->par.sample_rate)
            s->streams[i]->time_base = (Rational){ 1, s->streams[i]->par.sample_rate };
    return 0;
}
static int crc_write_packet(FormatContext *s, Packet *pkt)
{
    HashMux *c = s->priv;
    c->crc = adler32_update(c->crc, pkt->data, pkt->size);
    return 0;
}
static int crc_write_trailer(FormatContext *s)
{
    HashMux *c = s->priv;
    avio_printf(s->pb, "CRC=0x%08"PRIx32"\n", c->crc);
    return 0;
}
static void crc_deinit(FormatContext *s) { free(s->priv); s->priv = NULL; }

const OutputFormat ff_crc_muxer = {
    "crc", "CRC testing", NULL, NULL, CID_PCM_S16LE, CID_RAWVIDEO, FMT_NOTIMESTAMPS,
    crc_init_cb, NULL, crc_write_packet, crc_write_trailer, crc_deinit, NULL, 0
};

static int framecrc_write_header(FormatContext *s)
{
    for (int i = 0; i < s->nb_streams; i++) {
        CodecPar *par = &s->streams[i]->par;
        if (par->extradata) {
            uint32_t crc = adler32_update(0, par->extradata, par->extradata_size);
            avio_printf(s->pb, "#extradata %d: %8d, 0x%08"PRIx32"\n", i, par->extradata_size, crc);
        }
    }
    framehash_common_header(s);
    return 0;
}
static int framecrc_write_packet(FormatContext *s, Packet *pkt)
{
    uint32_t crc = adler32_update(0, pkt->data, pkt->size);
    char buf[512];
