    if (pkt->flags != PKT_FLAG_KEY)
        n += snprintf(buf + n, sizeof(buf) - n, ", F=0x%0X", pkt->flags);
    if (pkt->new_extradata) {
        n += snprintf(buf + n, sizeof(buf) - n, ", S=%d", 1);
        uint32_t sc = adler32_update(0, pkt->new_extradata, pkt->new_extradata_size);
        n += snprintf(buf + n, sizeof(buf) - n, ", %s, %8d, 0x%08"PRIx32, "New Extradata", pkt->new_extradata_size, sc);
