        if (!strcmp(output_formats[i]->name, name)) return output_formats[i];
    return NULL;
}

static int match_ext(const char *filename, const char *exts)
{
    if (!exts || !filename) return 0;
    const char *ext = strrchr(filename, '.');
    if (!ext) return 0;
    ext++;
    char buf[128];
    snprintf(buf, sizeof(buf), "%s", exts);
    char *save, *tok = strtok_r(buf, ",", &save);
    while (tok) {
        if (!strcasecmp(tok, ext)) return 1;
        tok = strtok_r(NULL, ",", &save);
    }
    return 0;
}

const OutputFormat *guess_output_format(const char *filename)
{
    const OutputFormat *best = NULL;
    int best_score = 0;
    for (int i = 0; output_formats[i]; i++) {
        int score = 0;
        if (match_ext(filename, output_formats[i]->extensions)) score += 50;
        if (score > best_score) { best_score = score; best = output_formats[i]; }
    }
    return best;
}
