static int16_t alaw2linear(uint8_t a_val)
{
    int t, seg;
    a_val ^= 0x55;
    t = a_val & 0x0f;
    seg = ((unsigned)a_val & 0x70) >> 4;
    if (seg) t = (t + t + 1 + 32) << (seg + 2);
    else t = (t + t + 1) << 3;
    return (a_val & 0x80) ? t : -t;
}
static int16_t ulaw2linear(uint8_t u_val)
{
    int t;
    u_val = ~u_val;
    t = ((u_val & 0x0f) << 3) + 0x84;
    t <<= ((unsigned)u_val & 0x70) >> 4;
    return (u_val & 0x80) ? (0x84 - t) : (t - 0x84);
}

int decoder_output_format(const CodecPar *par)
{
    if (par->codec_id == CID_FLAC) {
        int bps = par->bits_per_raw_sample;
        if (par->extradata_size >= 34) {
            FlacStreamInfo si;
            flac_parse_streaminfo(&si, par->extradata);
            bps = si.bps;
        }
        return bps > 16 ? SF_S32 : SF_S16;
    }
    const CodecDesc *d = codec_desc(par->codec_id);
    if (d && d->is_pcm) return d->pcm_sf;
    return SF_NONE;
}

DecCtx *decoder_open(const Decoder *d, const CodecPar *par, int *err)
{
    DecCtx *c = calloc(1, sizeof(*c));
    c->dec = d;
    codecpar_copy(&c->par, par);
    c->sample_fmt = decoder_output_format(par);
    if (d->id == CID_FLAC) {
        if (par->extradata_size >= 34) {
            flac_parse_streaminfo(&c->si, par->extradata);
            c->have_si = 1;
            c->bits_per_raw_sample = c->si.bps;
        }
    } else {
        if (c->sample_fmt == SF_S32 || c->sample_fmt == SF_S32P)
            c->bits_per_raw_sample = get_bits_per_sample(d->id);
    }
    *err = 0;
    return c;
}

static inline uint32_t rd32(const uint8_t *p, int be)
{
    return be ? ((uint32_t)p[0] << 24 | p[1] << 16 | p[2] << 8 | p[3]) : ((uint32_t)p[3] << 24 | p[2] << 16 | p[1] << 8 | p[0]);
}
static inline uint64_t rd64(const uint8_t *p, int be)
{
    uint64_t v = 0;
    if (be) for (int i = 0; i < 8; i++) v = (v << 8) | p[i];
    else for (int i = 7; i >= 0; i--) v = (v << 8) | p[i];
    return v;
}

Frame *decoder_decode(DecCtx *c, const Packet *pkt, int *err)
{
    *err = 0;
    int id = c->dec->id;
    int ch = c->par.ch_layout.nb_channels;
    if (id == CID_FLAC) {
        FlacFrameInfo fi;
        if (!c->have_si) { *err = AVERROR_INVALIDDATA; return NULL; }
        int need = 65536 * 8;
        if (c->flacbuf_size < need) { free(c->flacbuf); c->flacbuf = malloc(need * sizeof(int32_t)); c->flacbuf_size = need; }
        int r = flac_decode_frame(pkt->data, pkt->size, &c->si, &fi, c->flacbuf);
        if (r < -1) {
            av_log(c, AV_LOG_ERROR, "CRC error at PTS %"PRId64"\n", pkt->pts);
            *err = AVERROR_INVALIDDATA;
            return NULL;
        }
        if (r < 0) { *err = AVERROR_INVALIDDATA; return NULL; }
        int bps = fi.bps ? fi.bps : c->si.bps;
        Frame *f = frame_alloc(c->sample_fmt, fi.blocksize, &c->par.ch_layout, c->par.sample_rate);
        int n = fi.blocksize * fi.channels;
        if (c->sample_fmt == SF_S16) {
            int16_t *o = (int16_t *)f->data;
            int sh = 16 - bps;
            for (int i = 0; i < n; i++) o[i] = (int16_t)((uint32_t)c->flacbuf[i] << sh);
        } else {
            int32_t *o = (int32_t *)f->data;
            int sh = 32 - bps;
            for (int i = 0; i < n; i++) o[i] = (int32_t)((uint32_t)c->flacbuf[i] << sh);
        }
        f->pts = pkt->pts;
        f->bits_per_raw_sample = bps;
        return f;
    }
    const CodecDesc *d = codec_desc(id);
    int bps = d->bits_per_sample / 8;
    int ns = pkt->size / (bps * ch);
    if (ns <= 0) { *err = AVERROR_INVALIDDATA; return NULL; }
    int fmt = c->sample_fmt;
    int planar_src = (id == CID_PCM_S16LE_PLANAR || id == CID_PCM_S16BE_PLANAR || id == CID_PCM_S8_PLANAR ||
                      id == CID_PCM_S24LE_PLANAR || id == CID_PCM_S32LE_PLANAR);
    Frame *f = frame_alloc(fmt, ns, &c->par.ch_layout, c->par.sample_rate);
    const uint8_t *p = pkt->data;
    int n = ns * ch;
    for (int k = 0; k < n; k++) {
        int i = k;
        if (planar_src) { int c2 = k / ns, s2 = k % ns; i = s2 * ch + c2; }
        const uint8_t *q = p + (size_t)k * bps;
        switch (id) {
        case CID_PCM_S16LE: case CID_PCM_S16LE_PLANAR: ((int16_t *)f->data)[i] = (int16_t)(q[0] | (q[1] << 8)); break;
        case CID_PCM_S16BE: case CID_PCM_S16BE_PLANAR: ((int16_t *)f->data)[i] = (int16_t)(q[1] | (q[0] << 8)); break;
        case CID_PCM_U16LE: ((int16_t *)f->data)[i] = (int16_t)((q[0] | (q[1] << 8)) - 0x8000); break;
        case CID_PCM_U16BE: ((int16_t *)f->data)[i] = (int16_t)((q[1] | (q[0] << 8)) - 0x8000); break;
        case CID_PCM_S8: case CID_PCM_S8_PLANAR: ((uint8_t *)f->data)[i] = q[0] + 128; break;
        case CID_PCM_U8: ((uint8_t *)f->data)[i] = q[0]; break;
        case CID_PCM_ALAW: ((int16_t *)f->data)[i] = alaw2linear(q[0]); break;
        case CID_PCM_MULAW: ((int16_t *)f->data)[i] = ulaw2linear(q[0]); break;
        case CID_PCM_S32LE: case CID_PCM_S32LE_PLANAR: ((int32_t *)f->data)[i] = (int32_t)rd32(q, 0); break;
        case CID_PCM_S32BE: ((int32_t *)f->data)[i] = (int32_t)rd32(q, 1); break;
        case CID_PCM_U32LE: ((int32_t *)f->data)[i] = (int32_t)(rd32(q, 0) - 0x80000000u); break;
        case CID_PCM_U32BE: ((int32_t *)f->data)[i] = (int32_t)(rd32(q, 1) - 0x80000000u); break;
        case CID_PCM_S24LE: case CID_PCM_S24LE_PLANAR: ((int32_t *)f->data)[i] = (int32_t)(((uint32_t)q[0] << 8) | ((uint32_t)q[1] << 16) | ((uint32_t)q[2] << 24)); break;
        case CID_PCM_S24BE: ((int32_t *)f->data)[i] = (int32_t)(((uint32_t)q[2] << 8) | ((uint32_t)q[1] << 16) | ((uint32_t)q[0] << 24)); break;
        case CID_PCM_U24LE: ((int32_t *)f->data)[i] = (int32_t)((((uint32_t)q[0] << 8) | ((uint32_t)q[1] << 16) | ((uint32_t)q[2] << 24)) - 0x80000000u); break;
        case CID_PCM_U24BE: ((int32_t *)f->data)[i] = (int32_t)((((uint32_t)q[2] << 8) | ((uint32_t)q[1] << 16) | ((uint32_t)q[0] << 24)) - 0x80000000u); break;
        case CID_PCM_F32LE: { uint32_t v = rd32(q, 0); float fl; memcpy(&fl, &v, 4); ((float *)f->data)[i] = fl; break; }
        case CID_PCM_F32BE: { uint32_t v = rd32(q, 1); float fl; memcpy(&fl, &v, 4); ((float *)f->data)[i] = fl; break; }
        case CID_PCM_F64LE: { uint64_t v = rd64(q, 0); double dd; memcpy(&dd, &v, 8); ((double *)f->data)[i] = dd; break; }
        case CID_PCM_F64BE: { uint64_t v = rd64(q, 1); double dd; memcpy(&dd, &v, 8); ((double *)f->data)[i] = dd; break; }
        case CID_PCM_S64LE: ((int64_t *)f->data)[i] = (int64_t)rd64(q, 0); break;
        case CID_PCM_S64BE: ((int64_t *)f->data)[i] = (int64_t)rd64(q, 1); break;
        }
    }
    f->pts = pkt->pts;
    f->bits_per_raw_sample = c->bits_per_raw_sample;
    return f;
}

