        int is_s32 = c->sample_fmt == SF_S32;
        c->flacctx = flacenc_init(&o, c->sample_rate, c->ch_layout.nb_channels, is_s32, &c->bits_per_raw_sample,
                                  &c->frame_size, c->ch_layout.order == 1 ? c->ch_layout.mask : 0, c->strict, &err, logctx);
        if (!c->flacctx) return err;
        c->extradata = malloc(34 + 64);
        memset(c->extradata, 0, 34 + 64);
        flacenc_get_header(c->flacctx, c->extradata);
        c->extradata_size = 34;
        c->next_pts = 0;
        return 0;
    }
    const CodecDesc *d = codec_desc(c->enc->id);
    c->bits_per_coded_sample = d->bits_per_sample;
    c->block_align = c->ch_layout.nb_channels * d->bits_per_sample / 8;
    c->bit_rate = (int64_t)c->block_align * 8 * c->sample_rate;
    c->frame_size = 0;
    if (c->enc->id == CID_PCM_S24LE || c->enc->id == CID_PCM_S24BE || c->enc->id == CID_PCM_U24LE ||
        c->enc->id == CID_PCM_U24BE || c->enc->id == CID_PCM_S24LE_PLANAR)
        c->bits_per_raw_sample = 24;
    return 0;
}

static inline void wr32(uint8_t *p, uint32_t v, int be)
{
    if (be) { p[0] = v >> 24; p[1] = v >> 16; p[2] = v >> 8; p[3] = v; }
    else { p[0] = v; p[1] = v >> 8; p[2] = v >> 16; p[3] = v >> 24; }
}
static inline void wr64(uint8_t *p, uint64_t v, int be)
{
    for (int i = 0; i < 8; i++) {
        if (be) p[i] = (uint8_t)(v >> (56 - 8 * i));
        else p[i] = (uint8_t)(v >> (8 * i));
    }
}

static uint8_t linear2alaw(int pcm_val)
{
    int mask, seg;
    unsigned aval;
    pcm_val >>= 3;
    if (pcm_val >= 0) { mask = 0xD5; } else { mask = 0x55; pcm_val = -pcm_val - 1; }
    static const int seg_end[8] = { 0x1F, 0x3F, 0x7F, 0xFF, 0x1FF, 0x3FF, 0x7FF, 0xFFF };
    for (seg = 0; seg < 8; seg++) if (pcm_val <= seg_end[seg]) break;
    if (seg >= 8) return (uint8_t)(0x7F ^ mask);
    aval = (unsigned)seg << 4;
    if (seg < 2) aval |= (pcm_val >> 1) & 0xf;
    else aval |= (pcm_val >> seg) & 0xf;
    return aval ^ mask;
}
static uint8_t linear2ulaw(int pcm_val)
{
    int mask, seg;
    unsigned uval;
    pcm_val >>= 2;
    if (pcm_val < 0) { pcm_val = -pcm_val; mask = 0x7F; } else mask = 0xFF;
    if (pcm_val > 8159) pcm_val = 8159;
    pcm_val += (0x84 >> 2);
    static const int seg_uend[8] = { 0x3F, 0x7F, 0xFF, 0x1FF, 0x3FF, 0x7FF, 0xFFF, 0x1FFF };
    for (seg = 0; seg < 8; seg++) if (pcm_val <= seg_uend[seg]) break;
    if (seg >= 8) return (uint8_t)(0x7F ^ mask);
    uval = (unsigned)(seg << 4) | ((pcm_val >> (seg + 1)) & 0xF);
    return uval ^ mask;
}

static uint8_t alaw_tab[16384], ulaw_tab[16384];
static int law_init;
static void build_law(void)
{
    if (law_init) return;
    /* table built from int16 >> 2 like reference */
    for (int i = 0; i < 16384; i++) {
        int v = (int16_t)(i << 2);
        (void)v;
    }
    law_init = 1;
}

int encoder_encode(EncCtx *c, const Frame *frame, Packet **pkts, int *nb_pkts)
{
    if (c->enc->id == CID_FLAC) {
        if (!frame) {
            if (c->flushed) return 0;
            uint8_t si[34];
            flacenc_finish(c->flacctx, si);
            memcpy(c->extradata, si, 34);
            Packet p; packet_init(&p);
            p.data = calloc(1, 64);
            p.size = 0;
            p.pts = p.dts = c->next_pts;
            p.duration = 0;
            p.flags = PKT_FLAG_KEY;
            p.new_extradata = malloc(34);
            memcpy(p.new_extradata, si, 34);
            p.new_extradata_size = 34;
            *pkts = realloc(*pkts, sizeof(Packet) * (*nb_pkts + 1));
            (*pkts)[(*nb_pkts)++] = p;
            c->flushed = 1;
            return 0;
        }
        uint8_t *out; int osz;
        int r = flacenc_encode_frame(c->flacctx, frame->data, frame->nb_samples, &out, &osz);
        if (r < 0) return r;
        Packet p; packet_init(&p);
        p.data = realloc(out, osz + 64);
        memset(p.data + osz, 0, 64);
        p.size = osz;
        p.pts = p.dts = frame->pts;
        p.duration = frame->nb_samples;
        p.flags = PKT_FLAG_KEY;
        c->next_pts = frame->pts + frame->nb_samples;
        *pkts = realloc(*pkts, sizeof(Packet) * (*nb_pkts + 1));
        (*pkts)[(*nb_pkts)++] = p;
        return 0;
    }
    if (!frame) return 0;
    build_law();
    const CodecDesc *d = codec_desc(c->enc->id);
    int bps = d->bits_per_sample / 8;
    int ch = c->ch_layout.nb_channels;
    int ns = frame->nb_samples;
    int n = ns * ch;
    Packet p; packet_init(&p);
    p.size = n * bps;
    p.data = calloc(1, p.size + 64);
    int id = c->enc->id;
    int planar = (id == CID_PCM_S16LE_PLANAR || id == CID_PCM_S16BE_PLANAR || id == CID_PCM_S8_PLANAR ||
                  id == CID_PCM_S24LE_PLANAR || id == CID_PCM_S32LE_PLANAR);
    for (int k = 0; k < n; k++) {
        int i = k;
        int o = k;
        if (planar) { int s2 = k / ch, c2 = k % ch; o = c2 * ns + s2; }
        uint8_t *q = p.data + (size_t)o * bps;
        switch (id) {
        case CID_PCM_S16LE: case CID_PCM_S16LE_PLANAR: { int16_t v = ((int16_t *)frame->data)[i]; q[0] = v; q[1] = v >> 8; break; }
        case CID_PCM_S16BE: case CID_PCM_S16BE_PLANAR: { int16_t v = ((int16_t *)frame->data)[i]; q[1] = v; q[0] = v >> 8; break; }
        case CID_PCM_U16LE: { uint16_t v = ((int16_t *)frame->data)[i] + 0x8000; q[0] = v; q[1] = v >> 8; break; }
        case CID_PCM_U16BE: { uint16_t v = ((int16_t *)frame->data)[i] + 0x8000; q[1] = v; q[0] = v >> 8; break; }
        case CID_PCM_S8: case CID_PCM_S8_PLANAR: q[0] = ((uint8_t *)frame->data)[i] - 128; break;
        case CID_PCM_U8: q[0] = ((uint8_t *)frame->data)[i]; break;
        case CID_PCM_ALAW: q[0] = linear2alaw(((int16_t *)frame->data)[i]); break;
        case CID_PCM_MULAW: q[0] = linear2ulaw(((int16_t *)frame->data)[i]); break;
        case CID_PCM_S32LE: case CID_PCM_S32LE_PLANAR: wr32(q, ((int32_t *)frame->data)[i], 0); break;
        case CID_PCM_S32BE: wr32(q, ((int32_t *)frame->data)[i], 1); break;
        case CID_PCM_U32LE: wr32(q, (uint32_t)((int32_t *)frame->data)[i] + 0x80000000u, 0); break;
        case CID_PCM_U32BE: wr32(q, (uint32_t)((int32_t *)frame->data)[i] + 0x80000000u, 1); break;
        case CID_PCM_S24LE: case CID_PCM_S24LE_PLANAR: { uint32_t v = (uint32_t)((int32_t *)frame->data)[i] >> 8; q[0] = v; q[1] = v >> 8; q[2] = v >> 16; break; }
        case CID_PCM_S24BE: { uint32_t v = (uint32_t)((int32_t *)frame->data)[i] >> 8; q[2] = v; q[1] = v >> 8; q[0] = v >> 16; break; }
        case CID_PCM_U24LE: { uint32_t v = ((uint32_t)((int32_t *)frame->data)[i] + 0x80000000u) >> 8; q[0] = v; q[1] = v >> 8; q[2] = v >> 16; break; }
        case CID_PCM_U24BE: { uint32_t v = ((uint32_t)((int32_t *)frame->data)[i] + 0x80000000u) >> 8; q[2] = v; q[1] = v >> 8; q[0] = v >> 16; break; }
        case CID_PCM_F32LE: { uint32_t v; memcpy(&v, &((float *)frame->data)[i], 4); wr32(q, v, 0); break; }
        case CID_PCM_F32BE: { uint32_t v; memcpy(&v, &((float *)frame->data)[i], 4); wr32(q, v, 1); break; }
        case CID_PCM_F64LE: { uint64_t v; memcpy(&v, &((double *)frame->data)[i], 8); wr64(q, v, 0); break; }
        case CID_PCM_F64BE: { uint64_t v; memcpy(&v, &((double *)frame->data)[i], 8); wr64(q, v, 1); break; }
        case CID_PCM_S64LE: wr64(q, ((int64_t *)frame->data)[i], 0); break;
        case CID_PCM_S64BE: wr64(q, ((int64_t *)frame->data)[i], 1); break;
        }
    }
    p.pts = p.dts = frame->pts;
    p.duration = ns;
    p.flags = PKT_FLAG_KEY;
    *pkts = realloc(*pkts, sizeof(Packet) * (*nb_pkts + 1));
    (*pkts)[(*nb_pkts)++] = p;
    return 0;
}

void encoder_close(EncCtx *c)
{
    if (!c) return;
    flacenc_free(c->flacctx);
    c->flacctx = NULL;
    free(c->extradata);
    c->extradata = NULL;
}
