        case SF_S64: LOOP(int64_t, p[i]); break;
        case SF_FLT: LOOP(float, p[i] * (1.0f / (UINT64_C(1) << 63))); break;
        case SF_DBL: LOOP(double, p[i] * (1.0 / (UINT64_C(1) << 63))); break;
        }
        break; }
    case SF_FLT: {
        const float *p = (const float *)in;
        switch (b) {
        case SF_U8: LOOP(uint8_t, av_clip_uint8((int)lrintf(p[i] * (1 << 7)) + 0x80)); break;
        case SF_S16: LOOP(int16_t, av_clip_int16((int)lrintf(p[i] * (1 << 15)))); break;
        case SF_S32: LOOP(int32_t, av_clipl_int32(llrintf(p[i] * (1U << 31)))); break;
        case SF_S64: for (i = 0; i < n; i++) {
                float v = p[i] * (float)(INT64_C(1) << 63);
                ((int64_t *)out)[i] = v >= 9.2233720e18f ? INT64_MAX : v <= -9.2233720e18f ? INT64_MIN : llrintf(v);
            } break;
        case SF_FLT: LOOP(float, p[i]); break;
        case SF_DBL: LOOP(double, p[i]); break;
        }
        break; }
    case SF_DBL: {
        const double *p = (const double *)in;
        switch (b) {
        case SF_U8: LOOP(uint8_t, av_clip_uint8((int)lrint(p[i] * (1 << 7)) + 0x80)); break;
        case SF_S16: LOOP(int16_t, av_clip_int16((int)lrint(p[i] * (1 << 15)))); break;
        case SF_S32: LOOP(int32_t, av_clipl_int32(llrint(p[i] * (1U << 31)))); break;
        case SF_S64: for (i = 0; i < n; i++) {
                double v = p[i] * (double)(INT64_C(1) << 63);
                ((int64_t *)out)[i] = v >= 9.223372036854775807e18 ? INT64_MAX : v <= -9.223372036854775807e18 ? INT64_MIN : llrint(v);
            } break;
        case SF_FLT: LOOP(float, (float)p[i]); break;
        case SF_DBL: LOOP(double, p[i]); break;
        }
        break; }
    }
#undef LOOP
}

/* ---- rematrix ---- */
#define C_FL 0
#define C_FR 1
#define C_FC 2
#define C_LFE 3
#define C_BL 4
#define C_BR 5
#define C_FLC 6
#define C_FRC 7
#define C_BC 8
#define C_SL 9
#define C_SR 10

static int has(uint64_t m, int c) { return (m >> c) & 1; }

static void build_matrix(const ChLayout *in, const ChLayout *out, double mat[64][64], int is_int_out)
{
    double matrix[64][64] = { { 0 } };
    uint64_t in_m = in->mask, out_m = out->mask;
    uint64_t unaccounted;
    double center_mix_level = M_SQRT1_2, surround_mix_level = M_SQRT1_2, lfe_mix_level = 0;
    if (in->order != 1) { chl_default((ChLayout *)&(ChLayout){0}, 0); }
    for (int i = 0; i < 64; i++)
        if (has(in_m, i) && has(out_m, i)) matrix[i][i] = 1.0;
    unaccounted = in_m & ~out_m;

    if (unaccounted & (1ULL << C_FC)) {
        if ((out_m & 3) == 3) {
            if (in_m & 3) {
                matrix[C_FL][C_FC] += center_mix_level;
                matrix[C_FR][C_FC] += center_mix_level;
            } else {
                matrix[C_FL][C_FC] += M_SQRT1_2;
                matrix[C_FR][C_FC] += M_SQRT1_2;
            }
        }
    }
    if ((unaccounted & 3) == 3 || (unaccounted & 3)) {
        if (has(out_m, C_FC) && (unaccounted & 3)) {
            matrix[C_FC][C_FL] += M_SQRT1_2;
            matrix[C_FC][C_FR] += M_SQRT1_2;
            if (has(in_m, C_FC))
                matrix[C_FC][C_FC] = center_mix_level * sqrt(2);
        }
    }
    if (unaccounted & (1ULL << C_BC)) {
        if (has(out_m, C_BL)) {
            matrix[C_BL][C_BC] += M_SQRT1_2;
            matrix[C_BR][C_BC] += M_SQRT1_2;
        } else if (has(out_m, C_SL)) {
            matrix[C_SL][C_BC] += M_SQRT1_2;
            matrix[C_SR][C_BC] += M_SQRT1_2;
        } else if (has(out_m, C_FL)) {
            matrix[C_FL][C_BC] += surround_mix_level * M_SQRT1_2;
            matrix[C_FR][C_BC] += surround_mix_level * M_SQRT1_2;
        } else if (has(out_m, C_FC)) {
            matrix[C_FC][C_BC] += surround_mix_level * M_SQRT1_2;
        }
    }
    if (unaccounted & (1ULL << C_BL)) {
        if (has(out_m, C_BC)) {
            matrix[C_BC][C_BL] += M_SQRT1_2;
            matrix[C_BC][C_BR] += M_SQRT1_2;
        } else if (has(out_m, C_SL)) {
            if (has(in_m, C_SL)) {
                matrix[C_SL][C_BL] += M_SQRT1_2;
                matrix[C_SR][C_BR] += M_SQRT1_2;
            } else {
                matrix[C_SL][C_BL] += 1.0;
                matrix[C_SR][C_BR] += 1.0;
            }
        } else if (has(out_m, C_FL)) {
            matrix[C_FL][C_BL] += surround_mix_level;
            matrix[C_FR][C_BR] += surround_mix_level;
        } else if (has(out_m, C_FC)) {
            matrix[C_FC][C_BL] += surround_mix_level * M_SQRT1_2;
            matrix[C_FC][C_BR] += surround_mix_level * M_SQRT1_2;
        }
    }
    if (unaccounted & (1ULL << C_SL)) {
        if (has(out_m, C_BL)) {
            if (has(in_m, C_BL)) {
                matrix[C_BL][C_SL] += M_SQRT1_2;
                matrix[C_BR][C_SR] += M_SQRT1_2;
            } else {
                matrix[C_BL][C_SL] += 1.0;
                matrix[C_BR][C_SR] += 1.0;
            }
        } else if (has(out_m, C_BC)) {
            matrix[C_BC][C_SL] += M_SQRT1_2;
            matrix[C_BC][C_SR] += M_SQRT1_2;
        } else if (has(out_m, C_FL)) {
            matrix[C_FL][C_SL] += surround_mix_level;
            matrix[C_FR][C_SR] += surround_mix_level;
        } else if (has(out_m, C_FC)) {
            matrix[C_FC][C_SL] += surround_mix_level * M_SQRT1_2;
            matrix[C_FC][C_SR] += surround_mix_level * M_SQRT1_2;
        }
    }
    if (unaccounted & (1ULL << C_FLC)) {
        if (has(out_m, C_FL)) {
            matrix[C_FL][C_FLC] += 1.0;
            matrix[C_FR][C_FRC] += 1.0;
        } else if (has(out_m, C_FC)) {
            matrix[C_FC][C_FLC] += M_SQRT1_2;
            matrix[C_FC][C_FRC] += M_SQRT1_2;
        }
    }
    if (unaccounted & (1ULL << C_LFE)) {
        if (has(out_m, C_FC)) {
            matrix[C_FC][C_LFE] += lfe_mix_level;
        } else if (has(out_m, C_FL)) {
            matrix[C_FL][C_LFE] += lfe_mix_level * M_SQRT1_2;
            matrix[C_FR][C_LFE] += lfe_mix_level * M_SQRT1_2;
        }
    }

    double maxcoef = 0;
    int oi = 0;
    for (int i = 0; i < 64; i++) {
        if (!has(out_m, i)) continue;
        double sum = 0;
        int ii = 0;
        for (int j = 0; j < 64; j++) {
            if (!has(in_m, j)) continue;
            mat[oi][ii] = matrix[i][j];
            sum += fabs(mat[oi][ii]);
            ii++;
        }
        if (sum > maxcoef) maxcoef = sum;
        oi++;
    }
    double maxval = is_int_out ? 1.0 : INT_MAX;
    if (maxcoef > maxval) {
        maxcoef /= maxval;
        for (int i = 0; i < 64; i++)
            for (int j = 0; j < 64; j++)
                mat[i][j] /= maxcoef;
    }
}

Frame *swr_convert_frame(const Frame *in, int out_fmt, const ChLayout *out_layout)
{
    ChLayout il = in->ch_layout, ol = *out_layout;
    int need_remix = il.nb_channels != ol.nb_channels || (il.order == 1 && ol.order == 1 && il.mask != ol.mask);
    if (!need_remix) {
        Frame *o = frame_alloc(out_fmt, in->nb_samples, out_layout, in->sample_rate);
        convert_samples(in->data, in->format, o->data, out_fmt, (size_t)in->nb_samples * il.nb_channels);
        o->pts = in->pts;
        o->duration = in->duration;
        return o;
    }
    if (il.order != 1) chl_default(&il, il.nb_channels);
    if (ol.order != 1) chl_default(&ol, ol.nb_channels);
    int in_b = sf_bytes(in->format), out_b = sf_bytes(out_fmt);
    int int_fmt;
    if (in_b <= 2 && out_b <= 2) int_fmt = SF_S16;
    else if (in_b <= 4) int_fmt = SF_FLT;
    else int_fmt = SF_DBL;
    int is_int_out = sf_packed(out_fmt) < SF_FLT || sf_packed(int_fmt) < SF_FLT;
    static double mat[64][64];
    memset(mat, 0, sizeof(mat));
    build_matrix(&il, &ol, mat, is_int_out);
    int ns = in->nb_samples;
    int ich = il.nb_channels, och = ol.nb_channels;
    /* convert input to internal */
    uint8_t *mid = malloc((size_t)ns * ich * sf_bytes(int_fmt) + 64);
    convert_samples(in->data, in->format, mid, int_fmt, (size_t)ns * ich);
    uint8_t *mout = calloc(1, (size_t)ns * och * sf_bytes(int_fmt) + 64);
    if (int_fmt == SF_S16) {
        int imat[64][64];
        for (int o = 0; o < och; o++) {
            double rem = 0;
            for (int j = 0; j < ich; j++) {
                double target = mat[o][j] * 32768 + rem;
                imat[o][j] = (int)lrintf((float)target);
                rem += target - imat[o][j];
            }
        }
        int maxsum = 0;
        for (int o = 0; o < och; o++) {
            int sum = 0;
            for (int j = 0; j < ich; j++) sum += abs(imat[o][j]);
            if (sum > maxsum) maxsum = sum;
        }
        const int16_t *src = (const int16_t *)mid;
        int16_t *dst = (int16_t *)mout;
        for (int o = 0; o < och; o++) {
            for (int s = 0; s < ns; s++) {
                int64_t acc = 0;
                for (int j = 0; j < ich; j++)
                    if (imat[o][j]) acc += (int64_t)src[s * ich + j] * imat[o][j];
                int v = (int)((acc + 16384) >> 15);
                if (maxsum > 32768) v = av_clip_int16(v);
                dst[s * och + o] = (int16_t)v;
            }
        }
    } else if (int_fmt == SF_FLT) {
        const float *src = (const float *)mid;
        float *dst = (float *)mout;
        for (int o = 0; o < och; o++) {
            int nz = 0, idx[64];
            for (int j = 0; j < ich; j++) if (mat[o][j] != 0) idx[nz++] = j;
            for (int s = 0; s < ns; s++) {
                float v;
                if (nz == 1) v = (float)mat[o][idx[0]] * src[s * ich + idx[0]];
                else if (nz == 2) v = (float)mat[o][idx[0]] * src[s * ich + idx[0]] + (float)mat[o][idx[1]] * src[s * ich + idx[1]];
                else {
                    v = 0;
                    for (int k = 0; k < nz; k++) v += (float)mat[o][idx[k]] * src[s * ich + idx[k]];
                }
                dst[s * och + o] = v;
            }
        }
    } else {
        const double *src = (const double *)mid;
        double *dst = (double *)mout;
        for (int o = 0; o < och; o++) {
            int nz = 0, idx[64];
            for (int j = 0; j < ich; j++) if (mat[o][j] != 0) idx[nz++] = j;
            for (int s = 0; s < ns; s++) {
                double v;
                if (nz == 1) v = mat[o][idx[0]] * src[s * ich + idx[0]];
                else if (nz == 2) v = mat[o][idx[0]] * src[s * ich + idx[0]] + mat[o][idx[1]] * src[s * ich + idx[1]];
                else {
                    v = 0;
                    for (int k = 0; k < nz; k++) v += mat[o][idx[k]] * src[s * ich + idx[k]];
                }
                dst[s * och + o] = v;
            }
        }
    }
    Frame *o = frame_alloc(out_fmt, ns, out_layout, in->sample_rate);
    convert_samples(mout, int_fmt, o->data, out_fmt, (size_t)ns * och);
    free(mid);
    free(mout);
    o->pts = in->pts;
    o->duration = in->duration;
    return o;
}
EOF
echo ok

