#include "filters.h"
#include "swr.h"
#include "expr.h"
#include "lavfi.h"

enum { F_ANULL, F_VOLUME, F_ATRIM, F_APAD, F_AFORMAT, F_AFADE, F_ARESAMPLE, F_ASETNSAMPLES };

struct AFilter {
    int type;
    char name[32];
    /* volume */
    double volume;
    int precision; /* 0 fixed 1 float 2 double */
    int volume_i;
    /* trim */
    int64_t start_us, end_us, dur_us, start_sample, end_sample;
    int64_t t_start, t_end; /* samples, resolved */
    int64_t t_seen;
    int trim_done;
    /* apad */
    int64_t pad_len, whole_len, pad_dur_us, whole_dur_us;
    int packet_size;
    int64_t total_samples;
    int64_t next_pts;
    int pad_eof_done;
    /* aformat */
    int fmts[16];
    int nb_fmts;
    int rates[16];
    int nb_rates;
    ChLayout layouts[16];
    int nb_layouts;
    /* afade */
    int fade_type; /* 0 in 1 out */
    int64_t fade_start_sample, fade_nb_samples, fade_st_us, fade_d_us;
    int curve;
    /* resample */
    int rs_rate;
    /* negotiated */
    int in_fmt, in_rate;
    ChLayout in_layout;
    int out_fmt;
};

static int parse_volume_expr(const char *s, double *v)
{
    /* allow dB suffix */
    char buf[256];
    snprintf(buf, sizeof(buf), "%s", s);
    size_t l = strlen(buf);
    if (l > 2 && !strcmp(buf + l - 2, "dB")) {
        buf[l - 2] = 0;
        double d;
        if (expr_parse_and_eval(&d, buf) < 0) return -1;
        *v = exp2(3.32192809488736234787 * (d / 20));
        return 0;
    }
    return expr_parse_and_eval(v, buf) < 0 ? -1 : 0;
}

static AFilter *make_filter(const char *name, const char *args, void *logctx, int *err)
{
    AFilter *f = calloc(1, sizeof(*f));
    char keys[32][64], vals[32][256];
    int n = 0;
    *err = 0;
    snprintf(f->name, sizeof(f->name), "%s", name);
    if (!strcmp(name, "anull") || !strcmp(name, "acopy")) {
        f->type = F_ANULL;
    } else if (!strcmp(name, "volume")) {
        static const char *const sh[] = { "volume", "precision", "eval", "replaygain", NULL };
        f->type = F_VOLUME;
        f->volume = 1.0;
        f->precision = 1;
        n = args ? parse_filter_opts(args, sh, keys, vals, 32) : 0;
        for (int i = 0; i < n; i++) {
            if (!strcmp(keys[i], "volume")) {
                if (parse_volume_expr(vals[i], &f->volume) < 0) { *err = AVERROR(22); break; }
            } else if (!strcmp(keys[i], "precision")) {
                if (!strcmp(vals[i], "fixed")) f->precision = 0;
                else if (!strcmp(vals[i], "float")) f->precision = 1;
                else if (!strcmp(vals[i], "double")) f->precision = 2;
                else f->precision = atoi(vals[i]);
            }
        }
        if (f->precision == 0) {
            f->volume_i = (int)(f->volume * 256 + 0.5);
            f->volume = f->volume_i / 256.0;
        }
    } else if (!strcmp(name, "atrim")) {
        static const char *const sh[] = { "start", "end", NULL };
        f->type = F_ATRIM;
        f->start_us = f->end_us = f->dur_us = INT64_MAX;
        f->start_sample = f->end_sample = -1;
        n = args ? parse_filter_opts(args, sh, keys, vals, 32) : 0;
        for (int i = 0; i < n; i++) {
            int64_t t;
            if (!strcmp(keys[i], "start") || !strcmp(keys[i], "starti")) { if (parse_time(&t, vals[i], 1) < 0) { *err = AVERROR(22); break; } f->start_us = t; }
            else if (!strcmp(keys[i], "end") || !strcmp(keys[i], "endi")) { if (parse_time(&t, vals[i], 1) < 0) { *err = AVERROR(22); break; } f->end_us = t; }
            else if (!strcmp(keys[i], "duration") || !strcmp(keys[i], "durationi")) { if (parse_time(&t, vals[i], 1) < 0) { *err = AVERROR(22); break; } f->dur_us = t; }
            else if (!strcmp(keys[i], "start_sample")) f->start_sample = atoll(vals[i]);
            else if (!strcmp(keys[i], "end_sample")) f->end_sample = atoll(vals[i]);
        }
    } else if (!strcmp(name, "apad")) {
        static const char *const sh[] = { "packet_size", "pad_len", "whole_len", "pad_dur", "whole_dur", NULL };
        f->type = F_APAD;
        f->packet_size = 4096;
        f->pad_len = f->whole_len = -1;
        f->pad_dur_us = f->whole_dur_us = -1;
        n = args ? parse_filter_opts(args, sh, keys, vals, 32) : 0;
        for (int i = 0; i < n; i++) {
            int64_t t;
            if (!strcmp(keys[i], "packet_size")) f->packet_size = atoi(vals[i]);
            else if (!strcmp(keys[i], "pad_len")) f->pad_len = atoll(vals[i]);
            else if (!strcmp(keys[i], "whole_len")) f->whole_len = atoll(vals[i]);
            else if (!strcmp(keys[i], "pad_dur")) { if (parse_time(&t, vals[i], 1) < 0) { *err = AVERROR(22); break; } f->pad_dur_us = t; }
            else if (!strcmp(keys[i], "whole_dur")) { if (parse_time(&t, vals[i], 1) < 0) { *err = AVERROR(22); break; } f->whole_dur_us = t; }
        }
    } else if (!strcmp(name, "aformat")) {
        static const char *const sh[] = { "sample_fmts", "sample_rates", "channel_layouts", NULL };
        f->type = F_AFORMAT;
        n = args ? parse_filter_opts(args, sh, keys, vals, 32) : 0;
        for (int i = 0; i < n; i++) {
            char *save, *tok;
            char tmp[256];
            snprintf(tmp, sizeof(tmp), "%s", vals[i]);
            if (!strcmp(keys[i], "sample_fmts") || !strcmp(keys[i], "f")) {
                for (tok = strtok_r(tmp, "|", &save); tok; tok = strtok_r(NULL, "|", &save)) {
                    int sf = sf_from_name(tok);
                    if (sf < 0) { *err = AVERROR(22); break; }
                    if (f->nb_fmts < 16) f->fmts[f->nb_fmts++] = sf;
                }
            } else if (!strcmp(keys[i], "sample_rates") || !strcmp(keys[i], "r")) {
                for (tok = strtok_r(tmp, "|", &save); tok; tok = strtok_r(NULL, "|", &save))
                    if (f->nb_rates < 16) f->rates[f->nb_rates++] = atoi(tok);
            } else if (!strcmp(keys[i], "channel_layouts") || !strcmp(keys[i], "cl")) {
                for (tok = strtok_r(tmp, "|", &save); tok; tok = strtok_r(NULL, "|", &save)) {
                    ChLayout l;
                    if (chl_from_string(&l, tok) < 0) { *err = AVERROR(22); break; }
                    if (f->nb_layouts < 16) f->layouts[f->nb_layouts++] = l;
                }
            }
        }
    } else if (!strcmp(name, "afade")) {
        static const char *const sh[] = { "type", "start_sample", "nb_samples", "start_time", "duration", "curve", NULL };
        f->type = F_AFADE;
        f->fade_nb_samples = 44100;
        f->fade_st_us = 0; f->fade_d_us = 0;
        n = args ? parse_filter_opts(args, sh, keys, vals, 32) : 0;
        for (int i = 0; i < n; i++) {
            int64_t t;
            if (!strcmp(keys[i], "type") || !strcmp(keys[i], "t")) f->fade_type = !strcmp(vals[i], "out") || !strcmp(vals[i], "1");
            else if (!strcmp(keys[i], "start_sample") || !strcmp(keys[i], "ss")) f->fade_start_sample = atoll(vals[i]);
            else if (!strcmp(keys[i], "nb_samples") || !strcmp(keys[i], "ns")) f->fade_nb_samples = atoll(vals[i]);
            else if (!strcmp(keys[i], "start_time") || !strcmp(keys[i], "st")) { parse_time(&t, vals[i], 1); f->fade_st_us = t; }
            else if (!strcmp(keys[i], "duration") || !strcmp(keys[i], "d")) { parse_time(&t, vals[i], 1); f->fade_d_us = t; }
            else if (!strcmp(keys[i], "curve") || !strcmp(keys[i], "c")) f->curve = 0;
        }
    } else if (!strcmp(name, "aresample")) {
        static const char *const sh[] = { "sample_rate", NULL };
        f->type = F_ARESAMPLE;
        n = args ? parse_filter_opts(args, sh, keys, vals, 32) : 0;
        for (int i = 0; i < n; i++)
            if (!strcmp(keys[i], "sample_rate") || !strcmp(keys[i], "osr") || !strcmp(keys[i], "out_sample_rate")) f->rs_rate = atoi(vals[i]);
    } else {
        av_log(logctx, AV_LOG_ERROR, "No such filter: '%s'\n", name);
        free(f);
        *err = AVERROR_FILTER_NOT_FOUND;
        return NULL;
    }
    if (*err) { free(f); return NULL; }
    return f;
}

int filterchain_parse(FilterChain *fc, const char *desc, void *logctx)
{
    char *dup = av_strdup(desc);
    char *p = dup;
    while (p && *p) {
        /* split on ',' not inside quotes/brackets */
        char *start = p;
        int q = 0;
        while (*p && (q || *p != ',')) {
            if (*p == '\'') q = !q;
            if (*p == '\\' && p[1]) p++;
            p++;
        }
        if (*p == ',') *p++ = 0;
        while (*start == ' ') start++;
        char *eq = strchr(start, '=');
        char *args = NULL;
        if (eq) { *eq = 0; args = eq + 1; }
        int err;
        AFilter *f = make_filter(start, args, logctx, &err);
        if (!f) { free(dup); return err; }
        fc->filters = realloc(fc->filters, sizeof(AFilter *) * (fc->nb_filters + 1));
        fc->filters[fc->nb_filters++] = f;
    }
    free(dup);
    return 0;
}

int filterchain_is_meta(FilterChain *fc)
{
    for (int i = 0; i < fc->nb_filters; i++)
        if (fc->filters[i]->type != F_ANULL && fc->filters[i]->type != F_ATRIM) return 0;
    return 1;
}

static int get_fmt_score(int dst, int src)
{
    int score = 0;
    if (sf_is_planar(dst) != sf_is_planar(src)) score++;
    if (sf_bytes(dst) < sf_bytes(src)) score += 100 * (sf_bytes(src) - sf_bytes(dst));
    else score += 10 * (sf_bytes(dst) - sf_bytes(src));
    if (sf_packed(dst) == SF_S32 && sf_packed(src) == SF_FLT) score += 20;
    if (sf_packed(dst) == SF_FLT && sf_packed(src) == SF_S32) score += 2;
    return score;
}

int pick_best_fmt(const int *list, int src)
{
    if (!list) return src;
    for (int i = 0; list[i] != SF_NONE; i++) if (list[i] == src) return src;
    int best = SF_NONE;
    for (int i = 0; list[i] != SF_NONE; i++) {
        if (best == SF_NONE) { best = list[i]; continue; }
        int s1 = get_fmt_score(best, src), s2 = get_fmt_score(list[i], src);
        best = s1 < s2 ? best : list[i];
    }
    return best;
}

static const int vol_fixed[] = { SF_U8, SF_U8P, SF_S16, SF_S16P, SF_S32, SF_S32P, SF_NONE };
static const int vol_float[] = { SF_FLT, SF_FLTP, SF_NONE };
static const int vol_double[] = { SF_DBL, SF_DBLP, SF_NONE };
static const int fade_fmts[] = { SF_S16, SF_S16P, SF_S32, SF_S32P, SF_FLT, SF_FLTP, SF_DBL, SF_DBLP, SF_NONE };

int filterchain_configure(FilterChain *fc, int in_fmt, int in_rate, const ChLayout *in_layout)
{
    fc->in_fmt = in_fmt;
    fc->in_rate = in_rate;
    fc->in_layout = *in_layout;
    int fmt = in_fmt, rate = in_rate;
    ChLayout l = *in_layout;
    for (int i = 0; i < fc->nb_filters; i++) {
        AFilter *f = fc->filters[i];
        const int *accept = NULL;
        if (f->type == F_VOLUME) accept = f->precision == 0 ? vol_fixed : f->precision == 1 ? vol_float : vol_double;
        else if (f->type == F_AFADE) accept = fade_fmts;
        else if (f->type == F_AFORMAT && f->nb_fmts) {
            static int tmp[17];
            for (int k = 0; k < f->nb_fmts; k++) tmp[k] = f->fmts[k];
            tmp[f->nb_fmts] = SF_NONE;
            accept = tmp;
        }
        if (accept) fmt = pick_best_fmt(accept, fmt);
        if (f->type == F_AFORMAT && f->nb_rates) {
            int ok = 0;
            for (int k = 0; k < f->nb_rates; k++) if (f->rates[k] == rate) ok = 1;
            if (!ok) rate = f->rates[0];
        }
        if (f->type == F_AFORMAT && f->nb_layouts) {
            int ok = 0;
            for (int k = 0; k < f->nb_layouts; k++) if (chl_equal(&f->layouts[k], &l)) ok = 1;
            if (!ok) l = f->layouts[0];
        }
        if (f->type == F_ARESAMPLE && f->rs_rate) rate = f->rs_rate;
        f->in_fmt = fmt;
        f->in_rate = rate;
        f->in_layout = l;
        f->out_fmt = fmt;
        if (f->type == F_ATRIM) {
            f->t_start = 0; f->t_end = INT64_MAX;
            if (f->start_sample >= 0) f->t_start = f->start_sample;
            if (f->start_us != INT64_MAX) f->t_start = FFMAX(f->t_start, av_rescale(f->start_us, rate, AV_TIME_BASE));
            if (f->end_sample >= 0) f->t_end = f->end_sample;
            if (f->end_us != INT64_MAX) f->t_end = FFMIN(f->t_end, av_rescale(f->end_us, rate, AV_TIME_BASE));
        }
        if (f->type == F_APAD) {
            if (f->pad_dur_us >= 0) f->pad_len = av_rescale(f->pad_dur_us, rate, AV_TIME_BASE);
            if (f->whole_dur_us >= 0) f->whole_len = av_rescale(f->whole_dur_us, rate, AV_TIME_BASE);
        }
        if (f->type == F_AFADE) {
            if (f->fade_st_us) f->fade_start_sample = av_rescale(f->fade_st_us, rate, AV_TIME_BASE);
            if (f->fade_d_us) f->fade_nb_samples = av_rescale(f->fade_d_us, rate, AV_TIME_BASE);
        }
    }
    /* output stage */
    if (fc->req_fmt != SF_NONE) {
        int list[2] = { fc->req_fmt, SF_NONE };
        fmt = pick_best_fmt(list, fmt);
    }
    fmt = pick_best_fmt(fc->enc_fmts, fmt);
    if (fc->req_rate) rate = fc->req_rate;
    if (fc->req_layout.nb_channels) l = fc->req_layout;
    fc->out_fmt = fmt;
    fc->out_rate = rate;
    fc->out_layout = l;
    fc->configured = 1;
    return 0;
}

static Frame *convert(Frame *in, int fmt, const ChLayout *l)
{
    if (in->format == fmt && chl_equal(&in->ch_layout, l)) return in;
    if (sf_packed(in->format) == sf_packed(fmt) && chl_equal(&in->ch_layout, l)) {
        in->format = fmt;
        return in;
    }
    Frame *o = swr_convert_frame(in, fmt, l);
    o->sample_rate = in->sample_rate;
    o->bits_per_raw_sample = in->bits_per_raw_sample;
    frame_free(in);
    return o;
}

static Frame *trim_frame(Frame *f, int64_t start, int64_t end)
{
    /* keep samples with pts in [start, end) */
    int64_t pts = f->pts;
    int64_t fs = pts, fe = pts + f->nb_samples;
    if (fe <= start || fs >= end) { frame_free(f); return NULL; }
    int64_t ks = FFMAX(fs, start), ke = FFMIN(fe, end);
    if (ks == fs && ke == fe) return f;
    int bps = sf_bytes(f->format) * f->ch_layout.nb_channels;
    Frame *o = frame_alloc(f->format, (int)(ke - ks), &f->ch_layout, f->sample_rate);
    memcpy(o->data, f->data + (ks - fs) * bps, (ke - ks) * bps);
    o->pts = ks;
    o->bits_per_raw_sample = f->bits_per_raw_sample;
    frame_free(f);
    return o;
}

static void apply_volume(AFilter *f, Frame *fr)
{
    size_t n = (size_t)fr->nb_samples * fr->ch_layout.nb_channels;
    if (f->volume == 1.0) return;
    switch (sf_packed(fr->format)) {
    case SF_U8: { uint8_t *d = fr->data; for (size_t i = 0; i < n; i++) d[i] = av_clip_uint8(((((int64_t)d[i] - 128) * f->volume_i + 128) >> 8) + 128); break; }
    case SF_S16: { int16_t *d = (int16_t *)fr->data; for (size_t i = 0; i < n; i++) d[i] = av_clip_int16((int)(((int64_t)d[i] * f->volume_i + 128) >> 8)); break; }
    case SF_S32: { int32_t *d = (int32_t *)fr->data; for (size_t i = 0; i < n; i++) d[i] = av_clipl_int32(((int64_t)d[i] * f->volume_i + 128) >> 8); break; }
    case SF_FLT: { float *d = (float *)fr->data; float v = (float)f->volume; for (size_t i = 0; i < n; i++) d[i] = d[i] * v; break; }
    case SF_DBL: { double *d = (double *)fr->data; for (size_t i = 0; i < n; i++) d[i] = d[i] * f->volume; break; }
    }
}

static double fade_gain(int64_t index, int64_t range)
{
    double gain = 1.0 * index / range;
    if (gain < 0) gain = 0;
    if (gain > 1) gain = 1;
    return gain;
}

static void apply_fade(AFilter *f, Frame *fr)
{
    int64_t cur = fr->pts;
    int nb = fr->nb_samples, ch = fr->ch_layout.nb_channels;
    int64_t start = f->fade_start_sample, range = f->fade_nb_samples;
    if ((!f->fade_type && cur >= start + range) || (f->fade_type && cur + nb < start)) return;
    for (int i = 0; i < nb; i++) {
        double gain;
        int64_t idx;
        if (!f->fade_type) {
            idx = cur + i - start;
            gain = (cur + i < start) ? 0.0 : fade_gain(idx, range);
        } else {
            idx = range - (cur + i - start);
            gain = (cur + i < start) ? 1.0 : fade_gain(idx, range);
        }
        for (int c = 0; c < ch; c++) {
            size_t k = (size_t)i * ch + c;
            switch (sf_packed(fr->format)) {
            case SF_S16: ((int16_t *)fr->data)[k] = (int16_t)(((int16_t *)fr->data)[k] * gain); break;
            case SF_S32: ((int32_t *)fr->data)[k] = (int32_t)(((int32_t *)fr->data)[k] * gain); break;
            case SF_FLT: ((float *)fr->data)[k] = (float)(((float *)fr->data)[k] * gain); break;
            case SF_DBL: ((double *)fr->data)[k] = ((double *)fr->data)[k] * gain; break;
            }
        }
    }
}

/* run frame through filters starting at index i; NULL frame = EOF */
static int run_filters(FilterChain *fc, int i, Frame *fr, frame_cb cb, void *opaque);

static int output_stage(FilterChain *fc, Frame *fr, frame_cb cb, void *opaque)
{
    if (!fr) return cb(opaque, NULL);
    if (fc->out_trim_start >= 0 || fc->out_trim_end >= 0) {
        int64_t s = fc->out_trim_start >= 0 ? fc->out_trim_start : INT64_MIN;
        int64_t e = fc->out_trim_end >= 0 ? fc->out_trim_end : INT64_MAX;
        fr = trim_frame(fr, s, e);
        if (!fr) return 0;
    }
    fr = convert(fr, fc->out_fmt, &fc->out_layout);
    if (fc->out_pts_offset && fr->pts != AV_NOPTS_VALUE) fr->pts -= fc->out_pts_offset;
    return cb(opaque, fr);
}

static int run_filters(FilterChain *fc, int i, Frame *fr, frame_cb cb, void *opaque)
{
    for (; i < fc->nb_filters; i++) {
        AFilter *f = fc->filters[i];
        if (!fr) {
            if (f->type == F_APAD && !f->pad_eof_done) {
                f->pad_eof_done = 1;
                int64_t total = 0;
                if (f->pad_len >= 0) total = f->pad_len;
                else if (f->whole_len >= 0) total = f->whole_len - f->total_samples;
                else total = INT64_MAX;
                while (total > 0) {
                    int n = (int)FFMIN(total, (int64_t)f->packet_size);
                    Frame *z = frame_alloc(f->in_fmt, n, &f->in_layout, f->in_rate);
                    if (sf_packed(f->in_fmt) == SF_U8) memset(z->data, 0x80, frame_bytes(z));
                    z->pts = f->next_pts;
                    f->next_pts += n;
                    total -= n;
                    int r = run_filters(fc, i + 1, z, cb, opaque);
                    if (r < 0) return r;
                    if (total > (int64_t)1 << 40) break;
                }
            }
            continue;
        }
        fr = convert(fr, f->in_fmt, &f->in_layout);
        switch (f->type) {
        case F_VOLUME: apply_volume(f, fr); break;
        case F_AFADE: apply_fade(f, fr); break;
        case F_ATRIM:
            fr = trim_frame(fr, f->t_start, f->t_end);
            if (!fr) return 0;
            break;
        case F_APAD:
            f->total_samples += fr->nb_samples;
            f->next_pts = fr->pts + fr->nb_samples;
            if (f->whole_len >= 0 && f->total_samples >= f->whole_len) f->pad_eof_done = 1;
            break;
        default: break;
        }
    }
    return output_stage(fc, fr, cb, opaque);
}

int filterchain_push(FilterChain *fc, Frame *in, frame_cb cb, void *opaque)
{
    if (in) {
        if (fc->in_trim_start >= 0 || fc->in_trim_end >= 0) {
            int64_t s = fc->in_trim_start >= 0 ? fc->in_trim_start : INT64_MIN;
            int64_t e = fc->in_trim_end >= 0 ? fc->in_trim_end : INT64_MAX;
            in = trim_frame(in, s, e);
            if (!in) return 0;
        }
        return run_filters(fc, 0, in, cb, opaque);
    }
    if (fc->eof) return 0;
    fc->eof = 1;
    return run_filters(fc, 0, NULL, cb, opaque);
}

void filterchain_free(FilterChain *fc)
{
    if (!fc) return;
    for (int i = 0; i < fc->nb_filters; i++) free(fc->filters[i]);
    free(fc->filters);
    free(fc);
}
