static const OptDef *find_option(const char *name)
{
    char base[128];
    snprintf(base, sizeof(base), "%s", name);
    char *colon = strchr(base, ':');
    if (colon) *colon = 0;
    for (int i = 0; options[i].name; i++)
        if (!strcmp(options[i].name, base)) return &options[i];
    return NULL;
}

/* ------------------------------------------------------------------ */
/* command line splitting                                              */
typedef struct OptEntry { const OptDef *def; char *key; char *val; } OptEntry;
typedef struct OptGroup { OptEntry *o; int n; char *arg; int is_input; } OptGroup;

static OptEntry *global_opts; static int nb_global_opts;
static OptGroup *groups; static int nb_groups;
static OptGroup cur_group;

static void group_add(OptGroup *g, const OptDef *def, const char *key, const char *val)
{
    g->o = realloc(g->o, sizeof(OptEntry) * (g->n + 1));
    g->o[g->n].def = def;
    g->o[g->n].key = av_strdup(key);
    g->o[g->n].val = val ? av_strdup(val) : NULL;
    g->n++;
}

static void finish_group(int is_input, const char *arg)
{
    cur_group.arg = av_strdup(arg);
    cur_group.is_input = is_input;
    groups = realloc(groups, sizeof(OptGroup) * (nb_groups + 1));
    groups[nb_groups++] = cur_group;
    memset(&cur_group, 0, sizeof(cur_group));
}

static const OptDef avopt_def = { "__avopt", OPT_FLAG_ARG | OPT_FLAG_PERFILE, O_NONE };

static int split_commandline(int argc, char **argv)
{
    int optindex = 1;
    int dashdash = -2;
    while (optindex < argc) {
        const char *opt = argv[optindex++];
        if (opt[0] == '-' && opt[1] == '-' && !opt[2]) {
            dashdash = optindex;
            continue;
        }
        if (opt[0] != '-' || !opt[1] || dashdash + 1 == optindex) {
            finish_group(0, opt);
            continue;
        }
        opt++;
        if (!strcmp(opt, "i")) {
            if (optindex >= argc) {
                av_log(NULL, AV_LOG_ERROR, "Missing argument for option '%s'.\n", opt);
                return AVERROR(22);
            }
            finish_group(1, argv[optindex++]);
            continue;
        }
        const OptDef *po = find_option(opt);
        if (po) {
            const char *arg = NULL;
            if (po->flags & OPT_FLAG_ARG) {
                if (optindex >= argc) {
                    av_log(NULL, AV_LOG_ERROR, "Missing argument for option '%s'.\n", opt);
                    return AVERROR(22);
                }
                arg = argv[optindex++];
            } else {
                arg = "1";
            }
            if (po->flags & OPT_FLAG_PERFILE) group_add(&cur_group, po, opt, arg);
            else {
                global_opts = realloc(global_opts, sizeof(OptEntry) * (nb_global_opts + 1));
                global_opts[nb_global_opts].def = po;
                global_opts[nb_global_opts].key = av_strdup(opt);
                global_opts[nb_global_opts].val = av_strdup(arg);
                nb_global_opts++;
            }
            continue;
        }
        /* AVOptions */
        if (optindex < argc) {
            char base[128];
            snprintf(base, sizeof(base), "%s", opt);
            char *colon = strchr(base, ':');
            if (colon) *colon = 0;
            if (avopt_known(base)) {
                group_add(&cur_group, &avopt_def, opt, argv[optindex++]);
                continue;
            }
        }
        /* boolean "no" prefix */
        if (!strncmp(opt, "no", 2)) {
            const OptDef *pb = find_option(opt + 2);
            if (pb && (pb->flags & OPT_FLAG_BOOL)) {
                if (pb->flags & OPT_FLAG_PERFILE) group_add(&cur_group, pb, opt + 2, "0");
                else {
                    global_opts = realloc(global_opts, sizeof(OptEntry) * (nb_global_opts + 1));
                    global_opts[nb_global_opts].def = pb;
                    global_opts[nb_global_opts].key = av_strdup(opt + 2);
                    global_opts[nb_global_opts].val = av_strdup("0");
                    nb_global_opts++;
                }
                continue;
            }
            if (!strcmp(opt, "nostdin")) { stdin_interaction = 0; continue; }
            if (!strcmp(opt, "nostats")) {
