static void dump_format(FormatContext *ic, int index, const char *url, int is_output, const char **enc_names)
{
    av_log(NULL, AV_LOG_INFO, "%s #%d, %s, %s '%s':\n", is_output ? "Output" : "Input", index,
           is_output ? ic->ofmt->name : ic->ifmt->name, is_output ? "to" : "from", url);
    dump_metadata(&ic->metadata, "  ");
    if (!is_output) {
        av_log(NULL, AV_LOG_INFO, "  Duration: ");
        if (ic->duration != AV_NOPTS_VALUE) {
            int64_t hours, mins, secs, us;
            int64_t duration = ic->duration + (ic->duration <= INT64_MAX - 5000 ? 5000 : 0);
            secs = duration / AV_TIME_BASE;
            us = duration % AV_TIME_BASE;
            mins = secs / 60;
            secs %= 60;
            hours = mins / 60;
            mins %= 60;
            av_log(NULL, AV_LOG_INFO, "%02"PRId64":%02"PRId64":%02"PRId64".%02"PRId64"", hours, mins, secs, (100 * us) / AV_TIME_BASE);
        } else {
            av_log(NULL, AV_LOG_INFO, "N/A");
        }
        if (ic->start_time != AV_NOPTS_VALUE) {
            int secs, us;
            av_log(NULL, AV_LOG_INFO, ", start: ");
            secs = (int)llabs(ic->start_time / AV_TIME_BASE);
            us = (int)llabs(ic->start_time % AV_TIME_BASE);
            av_log(NULL, AV_LOG_INFO, "%s%d.%06d", ic->start_time >= 0 ? "" : "-", secs, us);
        }
        av_log(NULL, AV_LOG_INFO, ", bitrate: ");
        if (ic->bit_rate) av_log(NULL, AV_LOG_INFO, "%"PRId64" kb/s", ic->bit_rate / 1000);
        else av_log(NULL, AV_LOG_INFO, "N/A");
        av_log(NULL, AV_LOG_INFO, "\n");
    }
    for (int i = 0; i < ic->nb_streams; i++) {
        Stream *st = ic->streams[i];
        char buf[512];
        codec_string(buf, sizeof(buf), &st->par, is_output, enc_names ? enc_names[i] : NULL);
        av_log(NULL, AV_LOG_INFO, "  Stream #%d:%d", index, i);
        const char *lang = dict_get(&st->metadata, "language");
        if (lang) av_log(NULL, AV_LOG_INFO, "(%s)", lang);
        av_log(NULL, AV_LOG_DEBUG, ", %d, %d/%d", 0, st->time_base.num, st->time_base.den);
        av_log(NULL, AV_LOG_INFO, ": %s", buf);
        av_log(NULL, AV_LOG_INFO, "\n");
        dump_metadata(&st->metadata, "    ");
    }
}
