        case O_FRAMES: speclist_add(&o->max_frames, e->key, e->val); break;
        case O_AFRAMES: speclist_add(&o->max_frames, "frames:a", e->val); break;
        case O_AB: speclist_add(&o->bitrates, "b:a", e->val); break;
        case O_B: speclist_add(&o->bitrates, e->key, e->val); break;
