        case O_VN: o->video_disable = atoi(e->val); break;
        case O_SN: o->subtitle_disable = atoi(e->val); break;
        case O_DN: o->data_disable = atoi(e->val); break;
        case O_SHORTEST: o->shortest = atoi(e->val); break;
