        case O_BITEXACT: break;
        case O_ACCURATE_SEEK: o->accurate_seek = atoi(e->val); break;
        case O_STREAM_LOOP: o->stream_loop = atoi(e->val); break;
        case O_GUESS_LAYOUT_MAX: o->guess_layout_max = atoi(e->val); break;
        default: break;
        }
        (void)err;
    }
    return 0;
}

/* find codec option value: key may be "name" or "name:spec" */
static const char *codec_opt_get(OptionsContext *o, const char *name, Stream **streams, int nb, Stream *st, int *used_idx)
{
    const char *ret = NULL;
    for (int i = 0; i < o->nb_codec_opts; i++) {
        const char *k = o->codec_opt_keys[i];
        size_t nl = strlen(name);
        if (strncmp(k, name, nl)) continue;
        if (k[nl] == 0) { ret = o->codec_opt_vals[i]; if (used_idx) *used_idx = i; }
        else if (k[nl] == ':' && (!st || stream_matches(streams, nb, st, k + nl + 1))) { ret = o->codec_opt_vals[i]; if (used_idx) *used_idx = i; }
    }
    return ret;
}
