        Stream *st = ic->streams[i];
        Rational usq = { 1, AV_TIME_BASE };
        if (st->start_time != AV_NOPTS_VALUE && st->time_base.den) {
            int64_t s1 = av_rescale_q(st->start_time, st->time_base, usq);
            start_time = FFMIN(start_time, s1);
            if (st->duration != AV_NOPTS_VALUE) {
                int64_t e1 = av_rescale_q(st->duration, st->time_base, usq) + s1;
                end_time = FFMAX(end_time, e1);
            }
        }
        if (st->duration != AV_NOPTS_VALUE) {
            int64_t d1 = av_rescale_q(st->duration, st->time_base, usq);
            duration = FFMAX(duration, d1);
        }
    }
    if (start_time != INT64_MAX) {
        ic->start_time = start_time;
        if (end_time != INT64_MIN) duration = FFMAX(duration, end_time - start_time);
    }
    if (duration != INT64_MIN && duration > 0 && ic->duration == AV_NOPTS_VALUE)
        ic->duration = duration;
    int64_t filesize = ic->pb ? avio_size(ic->pb) : -1;
    if (ic->pb && filesize > 0 && ic->duration > 0) {
        double bitrate = (double)filesize * 8.0 * AV_TIME_BASE / (double)ic->duration;
        if (bitrate >= 0 && bitrate <= (double)INT64_MAX) ic->bit_rate = (int64_t)bitrate;
