static void estimate_timings(FormatContext *ic)
{
    int has_duration = 0;
    for (int i = 0; i < ic->nb_streams; i++)
        if (ic->streams[i]->duration != AV_NOPTS_VALUE) has_duration = 1;
    if (!has_duration) {
        /* estimate from bitrate */
        if (ic->bit_rate <= 0) {
            int64_t br = 0;
            for (int i = 0; i < ic->nb_streams; i++) {
                int64_t b = ic->streams[i]->par.bit_rate;
                if (!b) {
                    int bps = get_bits_per_sample(ic->streams[i]->par.codec_id);
                    if (bps) b = (int64_t)bps * ic->streams[i]->par.sample_rate * ic->streams[i]->par.ch_layout.nb_channels;
