                br += b;
            }
            ic->bit_rate = br;
        }
        int show_warning = 0;
        if (ic->duration == AV_NOPTS_VALUE && ic->bit_rate != 0 && ic->pb) {
            int64_t filesize = avio_size(ic->pb);
