            return err;
        }
        if (!ifmt) {
            uint8_t probe[4096];
            int n = avio_peek(ic->pb, probe, sizeof(probe));
            int score = 0;
            ifmt = probe_input_format(probe, n, filename, &score);
            if (!ifmt) {
                av_log(f, AV_LOG_ERROR, "Error opening input: %s\n", av_err2str_buf(AVERROR_INVALIDDATA));
                av_log(NULL, AV_LOG_ERROR, "Error opening input file %s.\n", filename);
                return AVERROR_INVALIDDATA;
            }
        }
