    int64_t timestamp = o->start_time == AV_NOPTS_VALUE ? 0 : o->start_time;
    if (o->start_time_eof != AV_NOPTS_VALUE) {
        if (o->start_time_eof >= 0) {
            av_log(NULL, AV_LOG_ERROR, "-sseof value must be negative; aborting\n");
            return AVERROR(22);
        }
        if (ic->duration > 0) {
            f->start_time = o->start_time_eof + ic->duration;
            if (f->start_time < 0) f->start_time = 0;
            timestamp = f->start_time;
        } else
            av_log(NULL, AV_LOG_WARNING, "Cannot use -sseof, file duration not known\n");
    }
    if (ic->start_time != AV_NOPTS_VALUE) timestamp += ic->start_time;
    if (f->start_time != AV_NOPTS_VALUE && f->start_time != 0 && ifmt->read_seek) {
        if (ifmt->read_seek(ic, timestamp) < 0)
            av_log(f, AV_LOG_WARNING, "could not seek to position %0.3f\n", (double)timestamp / AV_TIME_BASE);
    }
    f->ts_offset = (o->input_ts_offset) - (copy_ts ? 0 : timestamp);

    /* streams */
    for (int i = 0; i < ic->nb_streams; i++) {
        Stream *st = ic->streams[i];
        InputStream *ist = calloc(1, sizeof(*ist));
        ist->cls = &ist_class;
        ist->file = f;
        ist->index = i;
        ist->st = st;
        const CodecDesc *d = codec_desc(st->par.codec_id);
        snprintf(ist->name, sizeof(ist->name), "%cist#%d:%d/%s", st->par.codec_type == MT_AUDIO ? 'a' : 'v', index, i, d ? d->name : "none");
        f->streams = realloc(f->streams, sizeof(InputStream *) * (f->nb_streams + 1));
        f->streams[f->nb_streams++] = ist;
        /* decoder selection */
        const char *cname = speclist_get(&o->codec_names, ic->streams, ic->nb_streams, st);
        if (cname && strcmp(cname, "copy")) {
            ist->dec = find_decoder_by_name(cname);
            if (!ist->dec) {
                av_log(ist, AV_LOG_FATAL, "Unknown decoder '%s'\n", cname);
                return AVERROR_DECODER_NOT_FOUND;
            }
        } else
            ist->dec = find_decoder(st->par.codec_id);
        if (st->par.codec_type == MT_AUDIO) {
            if (st->par.ch_layout.order == 0 && st->par.ch_layout.nb_channels > 0 &&
                st->par.ch_layout.nb_channels <= o->guess_layout_max) {
                ChLayout l;
                chl_default(&l, st->par.ch_layout.nb_channels);
                if (l.order == 1) {
                    char buf[128];
                    st->par.ch_layout = l;
                    chl_describe(&l, buf, sizeof(buf));
                    av_log(ist, AV_LOG_WARNING, "Guessed Channel Layout: %s\n", buf);
                }
            }
        }
    }
    dump_format(ic, index, filename, 0, NULL);
    input_files = realloc(input_files, sizeof(InputFile *) * (nb_input_files + 1));
    input_files[nb_input_files++] = f;
    return 0;
}
