static int codec_opt_parse(void *logctx, const CodecOptDef *o, const char *val, double defval, int64_t *out)
{
    if (o->type == CO_BOOL) {
        int n;
        static const char *t[] = { "true", "y", "yes", "enable", "enabled", "on" };
        static const char *fl[] = { "false", "n", "no", "disable", "disabled", "off" };
        if (!strcmp(val, "auto")) n = -1;
        else {
            n = -2;
            for (int i = 0; i < 6; i++) if (!strcasecmp(val, t[i])) n = 1;
            for (int i = 0; i < 6; i++) if (!strcasecmp(val, fl[i])) n = 0;
            if (n == -2) {
                char *end;
                n = (int)strtol(val, &end, 10);
                if (*end || end == val) n = -3;
            }
        }
        if (n < o->min || n > o->max) {
            av_log(logctx, AV_LOG_ERROR, "Unable to parse \"%s\" option value \"%s\" as boolean\n", o->name, val);
            return AVERROR(22);
        }
        *out = n;
        return 0;
    }
    if (o->type == CO_FLAGS) {
        int64_t cur = (int64_t)defval;
        const char *p = val;
        while (*p) {
            int cmd = 0;
            if (*p == '+' || *p == '-') cmd = *p++;
            char buf[128]; int i = 0;
            while (*p && *p != '+' && *p != '-' && i < 127) buf[i++] = *p++;
            buf[i] = 0;
            double d = -1;
            int found = 0;
            for (int k = 0; codec_consts[k].name; k++)
                if (o->unit && !strcmp(codec_consts[k].unit, o->unit) && !strcmp(codec_consts[k].name, buf)) { d = codec_consts[k].val; found = 1; }
            if (!found) {
                if (expr_parse_and_eval(&d, buf) < 0) {
                    av_log(logctx, AV_LOG_ERROR, "Unable to parse \"%s\" option value \"%s\"\n", o->name, val);
                    return AVERROR(22);
                }
            }
            if (cmd == '+') cur |= (int64_t)d;
            else if (cmd == '-') cur &= ~(int64_t)d;
            else cur = (int64_t)d;
        }
        *out = cur;
        return 0;
    }
    double d = 0;
    int found = 0;
    for (int k = 0; codec_consts[k].name; k++)
        if (o->unit && !strcmp(codec_consts[k].unit, o->unit) && !strcmp(codec_consts[k].name, val)) { d = codec_consts[k].val; found = 1; }
    if (!found) {
        if (!strcmp(val, "default")) d = defval;
        else if (!strcmp(val, "max")) d = o->max;
        else if (!strcmp(val, "min")) d = o->min;
        else if (expr_parse_and_eval(&d, val) < 0) {
            char ectx_name[8] = "Eval";
            NamedCtx ectx = { &named_class, "", logctx };
            snprintf(ectx.name, sizeof(ectx.name), "%s", ectx_name);
            av_log(&ectx, AV_LOG_ERROR, "Undefined constant or missing '(' in '%s'\n", val);
            av_log(logctx, AV_LOG_ERROR, "Unable to parse \"%s\" option value \"%s\"\n", o->name, val);
            return AVERROR(22);
        }
    }
    if (o->max < d || o->min > d) {
        av_log(logctx, AV_LOG_ERROR, "Value %f for parameter '%s' out of range [%g - %g]\n", d, o->name, o->min, o->max);
        return AVERROR(34);
    }
    *out = llrint(d);
    return 0;
}

static const CodecOptDef *find_codec_opt(const CodecOptDef *list, const char *name)
{
    for (int i = 0; list && list[i].name; i++) if (!strcmp(list[i].name, name)) return &list[i];
    return NULL;
}

/* ------------------------------------------------------------------ */
/* output files                                                        */
static int choose_encoder(OutputFile *of, OutputStream *ost, OptionsContext *o, Stream **in_streams, int nb_in)
{
    const char *cname = NULL;
    /* specifiers refer to output stream */
    for (int i = 0; i < o->codec_names.n; i++) {
        if (match_stream_specifier(ost->st, o->codec_names.o[i].spec) > 0) {
            int r = match_stream_specifier(ost->st, o->codec_names.o[i].spec);
            if (r >= 2) {
                int cnt = 0, ok = 0;
                for (int k = 0; k < of->ctx->nb_streams; k++) {
                    if (of->ctx->streams[k]->par.codec_type != ost->st->par.codec_type) continue;
                    if (of->ctx->streams[k] == ost->st) { ok = cnt == r - 2; break; }
                    cnt++;
                }
                if (!ok) continue;
            }
            cname = o->codec_names.o[i].val;
        }
    }
    (void)in_streams; (void)nb_in;
    if (cname && !strcmp(cname, "copy")) {
        ost->copy = 1;
        return 0;
    }
    if (cname) {
        ost->enc = find_encoder_by_name(cname);
        if (!ost->enc) {
            const CodecDesc *d = codec_desc_by_name(cname);
            if (d) ost->enc = find_encoder(d->id);
        }
        if (!ost->enc) {
            av_log(ost, AV_LOG_FATAL, "Unknown encoder '%s'\n", cname);
            return AVERROR_ENCODER_NOT_FOUND;
        }
        if (ost->enc && codec_desc(ost->enc->id)->type != ost->st->par.codec_type) {
            av_log(ost, AV_LOG_FATAL, "Unknown encoder '%s'\n", cname);
            return AVERROR_ENCODER_NOT_FOUND;
        }
        return 0;
    }
    int id = of->ctx->ofmt->audio_codec;
    ost->enc = find_encoder(id);
    if (!ost->enc) {
        av_log(ost, AV_LOG_FATAL, "Automatic encoder selection failed Default encoder for format %s (codec %s) is probably disabled. Please choose an encoder manually.\n",
               of->ctx->ofmt->name, codec_desc(id) ? codec_desc(id)->name : "none");
        return AVERROR_ENCODER_NOT_FOUND;
    }
    return 0;
}

static OutputStream *new_output_stream(OutputFile *of, InputStream *ist, OptionsContext *o, int *err)
{
    *err = 0;
    FormatContext *oc = of->ctx;
    Stream *st = format_new_stream(oc);
    st->par.codec_type = ist->st->par.codec_type;
    OutputStream *ost = calloc(1, sizeof(*ost));
    ost->cls = &ost_class;
    ost->file = of;
    ost->index = st->index;
    ost->st = st;
    ost->ist = ist;
    ost->last_mux_dts = AV_NOPTS_VALUE;
    ost->req_sample_fmt = SF_NONE;
    snprintf(ost->name, sizeof(ost->name), "%cost#%d:%d", st->par.codec_type == MT_AUDIO ? 'a' : 'v', of->index, st->index);
    of->streams = realloc(of->streams, sizeof(OutputStream *) * (of->nb_streams + 1));
    of->streams[of->nb_streams++] = ost;
    int ret = choose_encoder(of, ost, o, NULL, 0);
    if (ret < 0) {
        av_log(ost, AV_LOG_ERROR, "Error selecting an encoder\n");
        *err = ret;
        return NULL;
    }
    snprintf(ost->name, sizeof(ost->name), "%cost#%d:%d/%s", st->par.codec_type == MT_AUDIO ? 'a' : 'v', of->index, st->index,
             ost->copy ? "copy" : ost->enc->name);
    /* per-stream options */
    const char *v;
    if ((v = speclist_get(&o->audio_sample_rate, oc->streams, oc->nb_streams, st))) ost->req_sample_rate = atoi(v);
    if ((v = speclist_get(&o->audio_channels, oc->streams, oc->nb_streams, st))) {
        ost->req_channels = atoi(v);
        if (ost->req_channels > 0) chl_default(&ost->req_layout, ost->req_channels);
    }
    if ((v = speclist_get(&o->audio_ch_layouts, oc->streams, oc->nb_streams, st))) {
        ChLayout l;
        if (chl_from_string(&l, v) < 0) {
            av_log(ost, AV_LOG_FATAL, "Unknown channel layout: %s\n", v);
            *err = AVERROR(22);
            return NULL;
        }
        ost->req_layout = l;
    }
    if ((v = speclist_get(&o->sample_fmts, oc->streams, oc->nb_streams, st))) {
        ost->req_sample_fmt = sf_from_name(v);
        if (ost->req_sample_fmt == SF_NONE) {
            av_log(ost, AV_LOG_FATAL, "Invalid sample format '%s'\n", v);
            *err = AVERROR(22);
            return NULL;
        }
    }
    {
        char *fs = NULL;
        for (int i = 0; i < o->filters.n; i++) {
            const char *sp = o->filters.o[i].spec;
            if (!strncmp(sp, "a", 1) || !*sp || stream_matches(oc->streams, oc->nb_streams, st, sp))
                if (match_stream_specifier(st, sp) > 0 || !*sp) fs = o->filters.o[i].val;
        }
        if (fs) ost->filters = av_strdup(fs);
    }
    ost->max_frames = INT64_MAX;
    if ((v = speclist_get(&o->max_frames, oc->streams, oc->nb_streams, st))) ost->max_frames = strtoll(v, NULL, 10);
    /* stream metadata from input */
    dict_copy(&st->metadata, &ist->st->metadata);
    if (ost->copy) {
        codecpar_copy(&st->par, &ist->st->par);
        st->par.codec_tag = 0;
        st->time_base = ist->st->time_base;
    } else {
        /* encoder context defaults */
        EncCtx *e = &ost->ectx;
        memset(e, 0, sizeof(*e));
        e->enc = ost->enc;
        e->compression_level = -1;
        e->bit_rate = 128000;
        flacenc_default_opts(&e->flac);
        e->strict = g_strict;
        NamedCtx *cctx = new_named(ost->enc->name, NULL);
        ost->enc_cls = (const LogClass *)cctx;
        /* apply codec options */
        for (int i = 0; i < o->nb_codec_opts; i++) {
            const char *k = o->codec_opt_keys[i];
            char base[128];
            snprintf(base, sizeof(base), "%s", k);
            char *colon = strchr(base, ':');
            if (colon) {
                *colon = 0;
                if (!stream_matches(oc->streams, oc->nb_streams, st, colon + 1)) continue;
            }
            const CodecOptDef *cd = NULL;
            if (ost->enc->id == CID_FLAC) cd = find_codec_opt(flac_enc_opts, base);
            if (!cd) cd = find_codec_opt(generic_codec_opts, base);
            if (!cd) continue;
            int64_t val;
            double defval = 0;
            if (!strcmp(base, "flags")) defval = e->flags_bitexact ? 0x800000 : 0;
            int r = codec_opt_parse(cctx, cd, o->codec_opt_vals[i], defval, &val);
            if (r < 0) {
                av_log(cctx, AV_LOG_ERROR, "Error setting option %s to value %s.\n", base, o->codec_opt_vals[i]);
                av_log(ost, AV_LOG_ERROR, "Error applying encoder options: %s\n", av_err2str_buf(r));
                *err = r;
                return NULL;
            }
            if (!strcmp(base, "compression_level")) e->compression_level = (int)val;
            else if (!strcmp(base, "frame_size")) e->frame_size = (int)val;
            else if (!strcmp(base, "strict")) e->strict = (int)val;
            else if (!strcmp(base, "b") || !strcmp(base, "ab")) e->bit_rate = val;
            else if (!strcmp(base, "flags")) e->flags_bitexact = !!(val & 0x800000);
            else if (!strcmp(base, "lpc_coeff_precision")) e->flac.lpc_coeff_precision = (int)val;
            else if (!strcmp(base, "lpc_type")) e->flac.lpc_type = (int)val;
            else if (!strcmp(base, "lpc_passes")) e->flac.lpc_passes = (int)val;
            else if (!strcmp(base, "min_partition_order")) e->flac.min_partition_order = (int)val;
            else if (!strcmp(base, "max_partition_order")) e->flac.max_partition_order = (int)val;
            else if (!strcmp(base, "prediction_order_method")) e->flac.prediction_order_method = (int)val;
            else if (!strcmp(base, "ch_mode")) e->flac.ch_mode = (int)val;
            else if (!strcmp(base, "exact_rice_parameters")) e->flac.exact_rice_parameters = (int)val;
            else if (!strcmp(base, "multi_dim_quant")) e->flac.multi_dim_quant = (int)val;
            else if (!strcmp(base, "min_prediction_order")) e->flac.min_prediction_order = (int)val;
            else if (!strcmp(base, "max_prediction_order")) e->flac.max_prediction_order = (int)val;
        }
        if ((v = speclist_get(&o->bitrates, oc->streams, oc->nb_streams, st))) {
            double d;
            if (expr_parse_and_eval(&d, v) == 0) e->bit_rate = (int64_t)d;
        }
        ost->decoding_needed_dummy = 0;
    }
    ist->decoding_needed |= !ost->copy;
    return ost;
}
