    if ((v = speclist_get(&o->audio_ch_layouts, oc->streams, oc->nb_streams, st))) {
        ChLayout l;
        if (chl_from_string(&l, v) < 0) {
            av_log(ost, AV_LOG_FATAL, "Unknown channel layout: %s\n", v);
            *err = AVERROR(22);
            return NULL;
        }
        ost->req_layout = l;
    }
