            av_log(of, AV_LOG_FATAL, "Error initializing the muxer for %s: %s\n", filename, av_err2str_buf(AVERROR(22)));
            av_log(NULL, AV_LOG_ERROR, "Error opening output file %s.\n", g->arg);
            return AVERROR(22);
        }
    } else {
        ofmt = guess_output_format(filename);
        if (!ofmt) {
            av_log(&avfc, AV_LOG_ERROR, "Unable to choose an output format for '%s'; use a standard extension for the filename or specify the format manually.\n", filename);
            av_log(of, AV_LOG_FATAL, "Error initializing the muxer for %s: %s\n", filename, av_err2str_buf(AVERROR(22)));
            av_log(NULL, AV_LOG_ERROR, "Error opening output file %s.\n", g->arg);
            return AVERROR(22);
        }
    }
    oc->ofmt = ofmt;
    snprintf(of->name, sizeof(of->name), "out#%d/%s", index, ofmt->name);
    NamedCtx *muxctx = new_named(ofmt->name, NULL);
    oc->log_ctx = muxctx;
    oc->cls = (const LogClass *)&named_class;

    /* bitexact flags from avoptions */
    for (int i = 0; i < o->nb_codec_opts; i++) {
        if (!strcmp(o->codec_opt_keys[i], "fflags") && strstr(o->codec_opt_vals[i], "bitexact")) of->bitexact = 1;
        if (!strcmp(o->codec_opt_keys[i], "flags") && strstr(o->codec_opt_vals[i], "bitexact") && !strstr(o->codec_opt_vals[i], "-bitexact")) {
            /* codec flags: handled per stream */
        }
        if (fmt_has_option(ofmt->opts, o->codec_opt_keys[i]))
            dict_set(&oc->opts, o->codec_opt_keys[i], o->codec_opt_vals[i]);
    }
    for (int i = 0; i < g->n; i++)
        if (g->o[i].def->id == O_BITEXACT && atoi(g->o[i].val)) of->bitexact = 1;
    oc->bitexact = of->bitexact;

    /* validate format options */
    if (ofmt->opts) {
        for (int i = 0; i < oc->opts.count; i++) {
            const char *k = oc->opts.e[i].key, *v = oc->opts.e[i].value;
            for (const FmtOpt *fo = ofmt->opts; fo->name; fo++) {
                if (strcmp(fo->name, k)) continue;
                if (fo->type == 2) {
                    if (strcmp(v, "0") && strcmp(v, "1") && strcasecmp(v, "true") && strcasecmp(v, "false") &&
                        strcasecmp(v, "yes") && strcasecmp(v, "no") && strcasecmp(v, "on") && strcasecmp(v, "off")) {
                        av_log(muxctx, AV_LOG_ERROR, "Unable to parse \"%s\" option value \"%s\" as boolean\n", k, v);
                        return AVERROR(22);
                    }
                    int b = (!strcmp(v, "1") || !strcasecmp(v, "true") || !strcasecmp(v, "yes") || !strcasecmp(v, "on"));
                    dict_set(&oc->opts, k, b ? "1" : "0");
                } else if (fo->type == 1 && !strcmp(k, "hash")) {
                    HashCtx *h = hash_alloc(v);
                    if (!h) { /* error appears at header writing */ }
                    else hash_free(h);
                }
                break;
            }
        }
    }

    /* streams */
    if (o->nb_maps) {
        ret = map_streams(of, o);
        if (ret < 0) {
            av_log(NULL, AV_LOG_FATAL, "Error parsing options for output file %s.\n", g->arg);
            return ret;
        }
        /* drop removed */
        int k = 0;
        for (int i = 0; i < of->nb_streams; i++)
            if (of->streams[i]->finished != -1) of->streams[k++] = of->streams[i];
        if (k != of->nb_streams) {
            of->nb_streams = k;
            oc->nb_streams = 0;
            for (int i = 0; i < k; i++) {
                of->streams[i]->st->index = i;
                of->streams[i]->index = i;
                oc->streams[oc->nb_streams++] = of->streams[i]->st;
            }
        }
    } else if (!o->audio_disable && ofmt->audio_codec != CID_NONE) {
        /* pick best audio stream among all inputs */
        InputStream *best = NULL;
        int best_score = -1;
        for (int fi = 0; fi < nb_input_files; fi++) {
            InputFile *f = input_files[fi];
            for (int i = 0; i < f->nb_streams; i++) {
                InputStream *ist = f->streams[i];
                if (ist->st->par.codec_type != MT_AUDIO) continue;
                int score = ist->st->par.ch_layout.nb_channels + 100000000;
                if (score > best_score) { best_score = score; best = ist; }
            }
        }
        if (best) {
            int err;
            if (!new_output_stream(of, best, o, &err)) {
                av_log(NULL, AV_LOG_ERROR, "Error opening output file %s.\n", g->arg);
                return err;
            }
        }
    }
    if (!of->nb_streams && !(ofmt->flags & 0)) {
        dump_format(oc, index, filename, 1, NULL);
        av_log(of, AV_LOG_ERROR, "Output file does not contain any stream\n");
        av_log(NULL, AV_LOG_ERROR, "Error opening output file %s.\n", g->arg);
        return AVERROR(22);
    }

    /* metadata */
    {
        int copy_global = 1;
        int src_file = nb_input_files ? 0 : -1;
        for (int i = 0; i < o->nb_map_metadata; i++) {
            const char *mm = o->map_metadata[i];
            long fi = strtol(mm, NULL, 10);
            if (fi < 0) copy_global = 0;
            else if (fi < nb_input_files) src_file = (int)fi;
            if (fi < 0) {
                for (int s = 0; s < of->nb_streams; s++) dict_free(&of->streams[s]->st->metadata);
            }
        }
        /* default: copy from first input file mapped into this output */
        if (copy_global && src_file >= 0) {
            if (!o->nb_map_metadata && of->nb_streams && of->streams[0]->ist) src_file = 0;
            dict_copy(&oc->metadata, &input_files[src_file]->ctx->metadata);
        }
        for (int i = 0; i < o->metadata.n; i++) {
            const char *spec = o->metadata.o[i].spec;
            const char *kv = o->metadata.o[i].val;
            const char *eq = strchr(kv, '=');
            if (!eq) {
                av_log(NULL, AV_LOG_FATAL, "No '=' character in metadata string %s.\n", kv);
                return AVERROR(22);
            }
            char key[256];
            snprintf(key, sizeof(key), "%.*s", (int)(eq - kv), kv);
            const char *val = *(eq + 1) ? eq + 1 : NULL;
            if (!*spec || !strcmp(spec, "g")) {
                dict_set(&oc->metadata, key, val);
            } else if (spec[0] == 's') {
                const char *ss = spec[1] == ':' ? spec + 2 : "";
                for (int s = 0; s < of->nb_streams; s++)
                    if (stream_matches(oc->streams, oc->nb_streams, of->streams[s]->st, ss))
                        dict_set(&of->streams[s]->st->metadata, key, val);
            }
        }
    }

    /* open file */
    if (!(ofmt->flags & FMT_NOFILE)) {
        if (strcmp(filename, "pipe:") && strncmp(filename, "pipe:", 5) && strcmp(filename, "/dev/stdout")) {
            if (!file_overwrite && file_exists(filename)) {
                if (stdin_interaction && !no_file_overwrite) {
                    fprintf(stderr, "File '%s' already exists. Overwrite? [y/N] ", filename);
                    fflush(stderr);
                    if (!read_yesno()) {
                        av_log(NULL, AV_LOG_FATAL, "Not overwriting - exiting\n");
                        av_log(NULL, AV_LOG_ERROR, "Error opening output file %s.\n", g->arg);
                        return AVERROR_EXIT;
                    }
                } else {
                    av_log(NULL, AV_LOG_FATAL, "File '%s' already exists. Exiting.\n", filename);
                    av_log(NULL, AV_LOG_ERROR, "Error opening output file %s.\n", g->arg);
                    return AVERROR_EXIT;
                }
            }
        }
        int err = 0;
        oc->pb = avio_open_write(filename, &err);
        if (!oc->pb) {
            av_log(of, AV_LOG_FATAL, "Error opening output %s: %s\n", filename, av_err2str_buf(err));
            av_log(NULL, AV_LOG_ERROR, "Error opening output file %s.\n", g->arg);
            return err;
        }
    }
    return 0;
}
