/* ------------------------------------------------------------------ */
/* muxing                                                              */
static int64_t of_filesize(OutputFile *of)
{
    if (!of->ctx->pb) return -1;
    int64_t r = avio_size(of->ctx->pb);
    if (r <= 0) r = of->ctx->pb->bytes_written;
    return r;
}

static int write_packet_now(OutputFile *of, OutputStream *ost, Packet *pkt)
{
    FormatContext *oc = of->ctx;
    pkt->stream_index = ost->index;
    int ret = oc->ofmt->write_packet(oc, pkt);
    ost->data_size += pkt->size;
    ost->packets_written++;
    if (pkt->dts != AV_NOPTS_VALUE) {
        ost->last_mux_dts = pkt->dts;
        int64_t end = av_rescale_q(pkt->dts + pkt->duration, ost->st->time_base, (Rational){ 1, AV_TIME_BASE });
        if (end > ost->last_mux_end || !ost->packets_written) ost->last_mux_end = end;
    }
    return ret;
}

static int of_write_header(OutputFile *of);

static int of_check_init(OutputFile *of)
{
    if (of->header_written) return 0;
    for (int i = 0; i < of->nb_streams; i++) {
        OutputStream *ost = of->streams[i];
        if (!ost->copy && !ost->enc_opened) return 0;
    }
    return of_write_header(of);
}

/* simple dts interleaving across streams of one output */
static int mux_packet(OutputStream *ost, Packet *pkt)
{
    OutputFile *of = ost->file;
    if (!of->header_written || of->nb_streams > 1) {
        ost->queue = realloc(ost->queue, sizeof(Packet) * (ost->nb_queue + 1));
        ost->queue[ost->nb_queue++] = *pkt;
        memset(pkt, 0, sizeof(*pkt));
        if (!of->header_written) return 0;
        /* interleave: write while every unfinished stream has a queued packet */
        for (;;) {
            int best = -1;
            int64_t best_ts = 0;
            int all = 1;
            for (int i = 0; i < of->nb_streams; i++) {
                OutputStream *o2 = of->streams[i];
                if (!o2->nb_queue) { if (!o2->finished) all = 0; continue; }
                int64_t ts = av_rescale_q(o2->queue[0].dts, o2->st->time_base, (Rational){ 1, AV_TIME_BASE });
                if (best < 0 || ts < best_ts) { best = i; best_ts = ts; }
            }
            if (best < 0 || !all) break;
            OutputStream *o2 = of->streams[best];
            Packet p = o2->queue[0];
            memmove(o2->queue, o2->queue + 1, sizeof(Packet) * (o2->nb_queue - 1));
            o2->nb_queue--;
            int r = write_packet_now(of, o2, &p);
            packet_free(&p);
            if (r < 0) return r;
        }
        return 0;
    }
    int r = write_packet_now(of, ost, pkt);
    packet_free(pkt);
    return r;
}

static void flush_interleave(OutputFile *of)
{
    for (;;) {
        int best = -1;
        int64_t best_ts = 0;
        for (int i = 0; i < of->nb_streams; i++) {
            OutputStream *o2 = of->streams[i];
            if (!o2->nb_queue) continue;
            int64_t ts = av_rescale_q(o2->queue[0].dts, o2->st->time_base, (Rational){ 1, AV_TIME_BASE });
            if (best < 0 || ts < best_ts) { best = i; best_ts = ts; }
        }
        if (best < 0) break;
        OutputStream *o2 = of->streams[best];
        Packet p = o2->queue[0];
        memmove(o2->queue, o2->queue + 1, sizeof(Packet) * (o2->nb_queue - 1));
        o2->nb_queue--;
        write_packet_now(of, o2, &p);
        packet_free(&p);
    }
}

static int header_failed;

static int of_write_header(OutputFile *of)
{
    FormatContext *oc = of->ctx;
    const char *enc_names[64];
    for (int i = 0; i < of->nb_streams; i++) {
        OutputStream *ost = of->streams[i];
        enc_names[i] = ost->copy ? NULL : ost->enc->name;
    }
    int ret = oc->ofmt->init ? oc->ofmt->init(oc) : 0;
    if (ret < 0) {
        av_log(of, AV_LOG_ERROR, "Could not write header (incorrect codec parameters ?): %s\n", av_err2str_buf(ret));
        header_failed = ret;
        return ret;
    }
    if (!oc->bitexact) dict_set(&oc->metadata, "encoder", LIBAVFORMAT_IDENT);
    else dict_set(&oc->metadata, "encoder", NULL);
    /* hash validity */
    if (oc->ofmt->opts && fmt_has_option(oc->ofmt->opts, "hash")) {
        const char *h = fmt_opt_get(oc, oc->ofmt->opts, "hash");
        HashCtx *hc = hash_alloc(h);
        if (!hc) {
            av_log(of, AV_LOG_ERROR, "Could not write header (incorrect codec parameters ?): %s\n", av_err2str_buf(AVERROR(22)));
            header_failed = AVERROR(22);
            return AVERROR(22);
        }
        hash_free(hc);
    }
    if (oc->ofmt->write_header) {
        ret = oc->ofmt->write_header(oc);
        if (ret < 0) {
            av_log(of, AV_LOG_ERROR, "Could not write header (incorrect codec parameters ?): %s\n", av_err2str_buf(ret));
            header_failed = ret;
            return ret;
        }
    }
    of->header_written = 1;
    dump_format(oc, of->index, oc->url, 1, enc_names);
    /* flush queued packets */
    if (of->nb_streams == 1) {
        OutputStream *ost = of->streams[0];
        for (int i = 0; i < ost->nb_queue; i++) {
            write_packet_now(of, ost, &ost->queue[i]);
            packet_free(&ost->queue[i]);
        }
        ost->nb_queue = 0;
    } else {
        Packet dummy; memset(&dummy, 0, sizeof(dummy));
        (void)dummy;
        /* attempt interleave of whatever is available */
        for (;;) {
            int best = -1, all = 1;
            int64_t best_ts = 0;
            for (int i = 0; i < of->nb_streams; i++) {
                OutputStream *o2 = of->streams[i];
                if (!o2->nb_queue) { if (!o2->finished) all = 0; continue; }
                int64_t ts = av_rescale_q(o2->queue[0].dts, o2->st->time_base, (Rational){ 1, AV_TIME_BASE });
                if (best < 0 || ts < best_ts) { best = i; best_ts = ts; }
            }
            if (best < 0 || !all) break;
            OutputStream *o2 = of->streams[best];
            Packet p = o2->queue[0];
            memmove(o2->queue, o2->queue + 1, sizeof(Packet) * (o2->nb_queue - 1));
            o2->nb_queue--;
            write_packet_now(of, o2, &p);
            packet_free(&p);
        }
    }
    return 0;
}

static void mux_final_stats(OutputFile *of)
{
    uint64_t audio_size = 0, video_size = 0, extra_size = 0, total_size = 0;
    for (int j = 0; j < of->nb_streams; j++) {
        OutputStream *ost = of->streams[j];
        if (ost->st->par.codec_type == MT_AUDIO) audio_size += ost->data_size;
        else video_size += ost->data_size;
        extra_size += ost->st->par.extradata_size;
        total_size += ost->data_size;
    }
    char overhead[64] = "unknown";
    int64_t file_size = of_filesize(of);
    if (total_size && file_size > 0 && (uint64_t)file_size >= total_size)
        snprintf(overhead, sizeof(overhead), "%f%%", 100.0 * (file_size - total_size) / total_size);
    av_log(of, AV_LOG_INFO, "video:%1.0fKiB audio:%1.0fKiB subtitle:%1.0fKiB other streams:%1.0fKiB global headers:%1.0fKiB muxing overhead: %s\n",
           video_size / 1024.0, audio_size / 1024.0, 0.0, 0.0, extra_size / 1024.0, overhead);
}

static int64_t final_filesize0 = -1;

static int of_write_trailer(OutputFile *of)
{
    FormatContext *oc = of->ctx;
    int ret = 0;
    if (!of->header_written) {
        av_log(of, AV_LOG_ERROR, "Nothing was written into output file, because at least one of its streams received no packets.\n");
        return AVERROR(22);
    }
    flush_interleave(of);
    if (oc->ofmt->write_trailer) ret = oc->ofmt->write_trailer(oc);
    if (oc->pb) {
        avio_flush(oc->pb);
        if (oc->pb->error) {
            av_log(of, AV_LOG_ERROR, "Error writing trailer: %s\n", av_err2str_buf(oc->pb->error));
            ret = oc->pb->error;
        }
    }
    if (of->index == 0) final_filesize0 = of_filesize(of);
    mux_final_stats(of);
    if (oc->pb) {
        avio_close(oc->pb);
        oc->pb = NULL;
    }
    if (oc->ofmt->deinit) oc->ofmt->deinit(oc);
    return ret;
}

/* ------------------------------------------------------------------ */
/* encoding                                                            */
static int open_encoder(OutputStream *ost, const Frame *first)
{
    EncCtx *e = &ost->ectx;
    FilterChain *fc = ost->fc;
    e->sample_fmt = fc->out_fmt;
    e->sample_rate = fc->out_rate;
    e->ch_layout = fc->out_layout;
    if (!e->bits_per_raw_sample) {
        int bprs = first ? first->bits_per_raw_sample : 0;
        int in_fmt_full = !filterchain_is_meta(fc) || (fc->in_fmt != fc->out_fmt);
        if (in_fmt_full) bprs = sf_bytes(e->sample_fmt) * 8;
        else if (!bprs) bprs = sf_bytes(e->sample_fmt) * 8;
        e->bits_per_raw_sample = FFMIN(bprs, sf_bytes(e->sample_fmt) * 8);
    }
    int ret = encoder_open(e, ost->enc_cls);
    if (ret < 0) {
        NamedCtx enc_ctx_log = { &named_class, "", ost };
        snprintf(enc_ctx_log.name, sizeof(enc_ctx_log.name), "enc:%s", ost->enc->name);
        av_log(&enc_ctx_log, AV_LOG_ERROR, "Error while opening encoder - maybe incorrect parameters such as bit_rate, rate, width or height.\n");
        return ret;
    }
    ost->enc_opened = 1;
    CodecPar *par = &ost->st->par;
    par->codec_type = MT_AUDIO;
    par->codec_id = ost->enc->id;
    par->format = e->sample_fmt;
    par->sample_rate = e->sample_rate;
    par->ch_layout = e->ch_layout;
    par->bits_per_raw_sample = e->bits_per_raw_sample;
    if (ost->enc->id != CID_FLAC && !(e->bits_per_raw_sample && e->bits_per_raw_sample < sf_bytes(e->sample_fmt) * 8))
        par->bits_per_raw_sample = (ost->enc->id == CID_PCM_S24LE || ost->enc->id == CID_PCM_S24BE ||
                                    ost->enc->id == CID_PCM_U24LE || ost->enc->id == CID_PCM_U24BE ||
                                    ost->enc->id == CID_PCM_S24LE_PLANAR) ? 24 : 0;
    par->frame_size = e->frame_size;
    par->bit_rate = e->bit_rate;
    par->block_align = e->block_align;
    par->bits_per_coded_sample = e->bits_per_coded_sample;
    if (e->extradata) {
        par->extradata = malloc(e->extradata_size + 64);
        memcpy(par->extradata, e->extradata, e->extradata_size);
        memset(par->extradata + e->extradata_size, 0, 64);
        par->extradata_size = e->extradata_size;
    }
    ost->st->time_base = (Rational){ 1, e->sample_rate };
    {
        char es[128];
        snprintf(es, sizeof(es), "%s%s", (e->flags_bitexact || ost->file->bitexact) ? "Lavc " : LIBAVCODEC_IDENT " ", ost->enc->name);
        if (!dict_get(&ost->st->metadata, "encoder")) dict_set(&ost->st->metadata, "encoder", es);
    }
    return of_check_init(ost->file);
}

static int encode_and_mux(OutputStream *ost, Frame *f)
{
    Packet *pkts = NULL;
    int nb = 0;
    if (f && ost->frames_encoded >= ost->max_frames) { return 0; }
    int ret = encoder_encode(&ost->ectx, f, &pkts, &nb);
    if (f) ost->frames_encoded++;
    if (ret < 0) {
        av_log(ost, AV_LOG_ERROR, "Error encoding a frame: %s\n", av_err2str_buf(ret));
        return ret;
    }
    for (int i = 0; i < nb; i++) {
        int r = mux_packet(ost, &pkts[i]);
        if (r < 0) ret = r;
    }
    free(pkts);
    return ret;
}

/* re-chunking buffer for fixed frame size encoders */
typedef struct ChunkBuf {
    uint8_t *data;
    int nb;      /* samples buffered */
    int cap;
    int64_t pts; /* pts of first buffered sample */
    int bprs;
} ChunkBuf;
static ChunkBuf chunkbufs[256];

static int flac_predict_frame_size(OutputStream *ost, int rate)
{
    EncCtx *e = &ost->ectx;
    if (e->frame_size > 0) return e->frame_size;
    int level = e->flac.compression_level >= 0 ? e->flac.compression_level : e->compression_level;
    if (level < 0) level = 5;
    if (level > 12) return 0;
    int bt = level < 3 ? 27 : 105;
    int target = (int)(((int64_t)rate * bt) / 1000);
    int bs = 576;
    static const int tab[16] = { 0, 192, 576, 1152, 2304, 4608, 0, 0, 256, 512, 1024, 2048, 4096, 8192, 16384, 32768 };
    for (int i = 0; i < 16; i++) if (target >= tab[i] && tab[i] > bs) bs = tab[i];
    return bs;
}

static int enc_frame_size(OutputStream *ost)
{
    if (ost->enc->caps & ENC_CAP_VARIABLE_FRAME_SIZE) return 0;
    if (ost->enc_opened) return ost->ectx.frame_size;
    if (ost->enc->id == CID_FLAC) return flac_predict_frame_size(ost, ost->fc->out_rate);
    return 0;
}

static int emit_chunk(OutputStream *ost, Frame *f)
{
    int ret;
    if (!ost->enc_opened) {
        ret = open_encoder(ost, f);
        if (ret < 0) { frame_free(f); return ret; }
    }
    ret = encode_and_mux(ost, f);
    frame_free(f);
    return ret;
}

static int ost_frame_cb(void *opaque, Frame *f)
{
    OutputStream *ost = opaque;
    ChunkBuf *cb = &chunkbufs[(ost->file->index * 16 + ost->index) & 255];
    int fs = enc_frame_size(ost);
    if (!f) {
        /* EOF */
        int ret = 0;
        if (fs && cb->nb) {
            Frame *o = frame_alloc(ost->fc->out_fmt, cb->nb, &ost->fc->out_layout, ost->fc->out_rate);
            int bps = sf_bytes(ost->fc->out_fmt) * ost->fc->out_layout.nb_channels;
            memcpy(o->data, cb->data, (size_t)cb->nb * bps);
            o->pts = cb->pts;
            o->bits_per_raw_sample = cb->bprs;
            cb->nb = 0;
            ret = emit_chunk(ost, o);
            if (ret < 0) return ret;
        }
        if (!ost->enc_opened) {
            /* never received any frame */
            NamedCtx enc_ctx_log = { &named_class, "", ost };
            snprintf(enc_ctx_log.name, sizeof(enc_ctx_log.name), "enc:%s", ost->enc->name);
            if (!ost->fc->configured) {
                av_log(&enc_ctx_log, AV_LOG_ERROR, "Could not open encoder before EOF\n");
                return AVERROR(22);
            }
            ret = open_encoder(ost, NULL);
            if (ret < 0) return ret;
        }
        ret = encode_and_mux(ost, NULL);
        ost->finished = 1;
        return ret;
    }
    if (!fs) return emit_chunk(ost, f);
    int bps = sf_bytes(f->format) * f->ch_layout.nb_channels;
    if (cb->cap < cb->nb + f->nb_samples) {
        cb->cap = (cb->nb + f->nb_samples) * 2;
        cb->data = realloc(cb->data, (size_t)cb->cap * bps + 64);
    }
    if (!cb->nb) cb->pts = f->pts;
    cb->bprs = f->bits_per_raw_sample;
    memcpy(cb->data + (size_t)cb->nb * bps, f->data, (size_t)f->nb_samples * bps);
    cb->nb += f->nb_samples;
    frame_free(f);
    while (cb->nb >= fs) {
        Frame *o = frame_alloc(ost->fc->out_fmt, fs, &ost->fc->out_layout, ost->fc->out_rate);
        memcpy(o->data, cb->data, (size_t)fs * bps);
        o->pts = cb->pts;
        o->bits_per_raw_sample = cb->bprs;
        memmove(cb->data, cb->data + (size_t)fs * bps, (size_t)(cb->nb - fs) * bps);
        cb->nb -= fs;
        cb->pts += fs;
        int ret = emit_chunk(ost, o);
        if (ret < 0) return ret;
        fs = enc_frame_size(ost);
    }
    return 0;
}
