/* ------------------------------------------------------------------ */
/* transcoding                                                         */
static int setup_filters(OutputStream *ost)
{
    FilterChain *fc = calloc(1, sizeof(*fc));
    ost->fc = fc;
    fc->enc_fmts = ost->enc->sample_fmts;
    fc->req_fmt = ost->req_sample_fmt;
    fc->req_rate = ost->req_sample_rate;
    fc->req_layout = ost->req_layout;
    fc->in_trim_start = fc->in_trim_end = -1;
    fc->out_trim_start = fc->out_trim_end = -1;
    if (ost->filters) {
        NamedCtx *fgctx = new_named("", NULL);
        snprintf(fgctx->name, sizeof(fgctx->name), "af#%d:%d", ost->file->index, ost->index);
        int ret = filterchain_parse(fc, ost->filters, fgctx);
        if (ret < 0) {
            av_log(NULL, AV_LOG_ERROR, "Error opening output file %s.\n", ost->file->ctx->url);
            return ret;
        }
    }
    return 0;
}

static int send_frame_to_ost(OutputStream *ost, Frame *in)
{
    FilterChain *fc = ost->fc;
    InputFile *ifile = ost->ist->file;
    OutputFile *of = ost->file;
    if (!fc->configured) {
        filterchain_configure(fc, in->format, in->sample_rate, &in->ch_layout);
        int sr = in->sample_rate;
        if (ifile->recording_time != INT64_MAX)
            fc->in_trim_end = av_rescale(ifile->recording_time, sr, AV_TIME_BASE);
        if (ifile->start_time != AV_NOPTS_VALUE && ifile->accurate_seek)
            fc->in_trim_start = 0;
        int osr = fc->out_rate;
        int64_t ostart = 0;
        if (of->start_time != AV_NOPTS_VALUE && of->start_time > 0) {
            ostart = av_rescale(of->start_time, osr, AV_TIME_BASE);
            fc->out_trim_start = ostart;
            fc->out_pts_offset = ostart;
        }
        if (of->recording_time != INT64_MAX) {
            fc->out_trim_end = ostart + av_rescale(of->recording_time, osr, AV_TIME_BASE);
            if (fc->out_trim_start < 0) fc->out_trim_start = 0;
        }
    }
    return filterchain_push(fc, in, ost_frame_cb, ost);
}

static int process_input_packet(InputStream *ist, Packet *pkt)
{
    InputFile *f = ist->file;
    int ret = 0;
    /* stream copy */
    for (int o = 0; o < nb_output_files; o++) {
        OutputFile *of = output_files[o];
        for (int s = 0; s < of->nb_streams; s++) {
            OutputStream *ost = of->streams[s];
            if (ost->ist != ist || !ost->copy || ost->finished) continue;
            if (!pkt) { ost->finished = 1; continue; }
            Packet op;
            packet_ref_copy(&op, pkt);
            Rational usq = { 1, AV_TIME_BASE };
            int64_t start = of->start_time == AV_NOPTS_VALUE ? 0 : of->start_time;
            if (of->recording_time != INT64_MAX && op.pts != AV_NOPTS_VALUE &&
                av_rescale_q(op.pts, ist->st->time_base, usq) >= start + of->recording_time) {
                ost->finished = 1;
                packet_free(&op);
                continue;
            }
            if (f->recording_time != INT64_MAX && op.pts != AV_NOPTS_VALUE &&
                av_rescale_q(op.pts, ist->st->time_base, usq) >= f->recording_time) {
                ost->finished = 1;
                packet_free(&op);
                continue;
            }
            if (of->start_time != AV_NOPTS_VALUE && op.pts != AV_NOPTS_VALUE &&
                av_rescale_q(op.pts + op.duration, ist->st->time_base, usq) <= of->start_time) {
                packet_free(&op);
                continue;
            }
            int64_t ost_tb_start = av_rescale_q(start, usq, ost->st->time_base);
            if (op.pts != AV_NOPTS_VALUE) op.pts = av_rescale_q(op.pts, ist->st->time_base, ost->st->time_base) - ost_tb_start;
            if (op.dts != AV_NOPTS_VALUE) op.dts = av_rescale_q(op.dts, ist->st->time_base, ost->st->time_base) - ost_tb_start;
            op.duration = av_rescale_q(op.duration, ist->st->time_base, ost->st->time_base);
            if (!ost->copy_initialized) ost->copy_initialized = 1;
            int r = mux_packet(ost, &op);
            if (r < 0) ret = r;
        }
    }
    if (!ist->decoding_needed) return ret;
    if (!ist->dctx) {
        int err;
        ist->dctx = decoder_open(ist->dec, &ist->st->par, &err);
        if (!ist->dctx) return err;
        NamedCtx *dl = new_named(ist->dec->name, NULL);
        ist->dctx->cls = &named_class;
        (void)dl;
    }
    Frame *frame = NULL;
    if (pkt) {
        int err;
        frame = decoder_decode(ist->dctx, pkt, &err);
        if (!frame) {
            if (err < 0) {
                av_log(ist, AV_LOG_ERROR, "Error submitting packet to decoder: %s\n", av_err2str_buf(err));
                if (exit_on_error) return err;
            }
            return ret;
        }
        frame->ch_layout = ist->st->par.ch_layout;
        frame->sample_rate = ist->st->par.sample_rate;
    }
    for (int o = 0; o < nb_output_files; o++) {
        OutputFile *of = output_files[o];
        for (int s = 0; s < of->nb_streams; s++) {
            OutputStream *ost = of->streams[s];
            if (ost->ist != ist || ost->copy || ost->finished) continue;
            int r;
            if (frame) {
                Frame *c = frame_alloc(frame->format, frame->nb_samples, &frame->ch_layout, frame->sample_rate);
                memcpy(c->data, frame->data, frame_bytes(frame));
                c->pts = frame->pts;
                c->bits_per_raw_sample = frame->bits_per_raw_sample;
                r = send_frame_to_ost(ost, c);
            } else {
                if (!ost->fc->configured) {
                    /* configure from stream parameters */
                    filterchain_configure(ost->fc, ist->st->par.format, ist->st->par.sample_rate, &ist->st->par.ch_layout);
                }
                r = filterchain_push(ost->fc, NULL, ost_frame_cb, ost);
            }
            if (r < 0) {
                ret = r;
                ost->finished = 1;
                return r;
            }
        }
    }
    frame_free(frame);
    return ret;
}

static void print_report(int is_last_report)
{
    if (!is_last_report && print_stats <= 0) return;
    int64_t total_size = -1;
    int64_t pts = AV_NOPTS_VALUE;
    if (nb_output_files) {
        OutputFile *of = output_files[0];
        total_size = final_filesize0 >= 0 || !of->ctx->pb ? final_filesize0 : of_filesize(of);
        if (of->ctx->ofmt->flags & FMT_NOFILE) total_size = -1;
    }
    for (int o = 0; o < nb_output_files; o++)
        for (int s = 0; s < output_files[o]->nb_streams; s++) {
            OutputStream *ost = output_files[o]->streams[s];
            if (ost->packets_written) {
                if (pts == AV_NOPTS_VALUE || ost->last_mux_end > pts) pts = ost->last_mux_end;
            }
        }
    double t = av_gettime_relative_s() - transcode_start_time;
    char buf[1024];
    int n = 0;
    double bitrate = pts != AV_NOPTS_VALUE && pts && total_size >= 0 ? total_size * 8 / (pts / 1000.0) : -1;
    double speed = pts != AV_NOPTS_VALUE && t != 0.0 ? (double)pts / AV_TIME_BASE / t : -1;
    if (total_size < 0) n += snprintf(buf + n, sizeof(buf) - n, "size=N/A time=");
    else n += snprintf(buf + n, sizeof(buf) - n, "size=%8.0fKiB time=", total_size / 1024.0);
    if (pts == AV_NOPTS_VALUE) {
        n += snprintf(buf + n, sizeof(buf) - n, "N/A ");
    } else {
        int64_t ap = pts < 0 ? -pts : pts;
        int us = (int)(ap % AV_TIME_BASE);
        int secs = (int)(ap / AV_TIME_BASE % 60);
        int mins = (int)(ap / AV_TIME_BASE / 60 % 60);
        int64_t hours = ap / AV_TIME_BASE / 3600;
        n += snprintf(buf + n, sizeof(buf) - n, "%s%02"PRId64":%02d:%02d.%02d ", pts < 0 ? "-" : "", hours, mins, secs, (100 * us) / AV_TIME_BASE);
    }
    if (bitrate < 0) n += snprintf(buf + n, sizeof(buf) - n, "bitrate=N/A");
    else n += snprintf(buf + n, sizeof(buf) - n, "bitrate=%6.1fkbits/s", bitrate);
    if (speed < 0) n += snprintf(buf + n, sizeof(buf) - n, " speed=N/A");
    else n += snprintf(buf + n, sizeof(buf) - n, " speed=%4.3gx", speed);
    {
        int secs = (int)t;
        int ms = (int)((t - secs) * 1000);
        int mins = secs / 60;
        secs %= 60;
        int hours = mins / 60;
        mins %= 60;
        n += snprintf(buf + n, sizeof(buf) - n, " elapsed=%d:%02d:%02d.%02d", hours, mins, secs, ms / 10);
    }
    char end = is_last_report ? '\n' : '\r';
    if (print_stats == 1 && AV_LOG_INFO > g_log_level) {
        fprintf(stderr, "%s    %c", buf, end);
    } else
        av_log(NULL, AV_LOG_INFO, "%s    %c", buf, end);
    fflush(stderr);
}

static int transcode(void)
{
    int ret = 0;
    /* stream mapping */
    av_log(NULL, AV_LOG_INFO, "Stream mapping:\n");
    for (int o = 0; o < nb_output_files; o++) {
        OutputFile *of = output_files[o];
        for (int s = 0; s < of->nb_streams; s++) {
            OutputStream *ost = of->streams[s];
            av_log(NULL, AV_LOG_INFO, "  Stream #%d:%d -> #%d:%d", ost->ist->file->index, ost->ist->index, of->index, ost->index);
            if (ost->copy) av_log(NULL, AV_LOG_INFO, " (copy)");
            else {
                const CodecDesc *dd = codec_desc(ost->ist->st->par.codec_id);
                const char *in_codec_name = dd ? dd->name : "none";
                const char *decoder_name = ost->ist->dec ? ost->ist->dec->name : "?";
                const char *out_codec_name = codec_desc(ost->enc->id)->name;
                const char *encoder_name = ost->enc->name;
                if (!strcmp(decoder_name, in_codec_name)) decoder_name = "native";
                if (!strcmp(encoder_name, out_codec_name)) encoder_name = "native";
                av_log(NULL, AV_LOG_INFO, " (%s (%s) -> %s (%s))", in_codec_name, decoder_name, out_codec_name, encoder_name);
            }
            av_log(NULL, AV_LOG_INFO, "\n");
        }
    }
    /* filters */
    for (int o = 0; o < nb_output_files; o++) {
        OutputFile *of = output_files[o];
        for (int s = 0; s < of->nb_streams; s++) {
            OutputStream *ost = of->streams[s];
            if (!ost->copy) {
                int r = setup_filters(ost);
                if (r < 0) return r;
            }
        }
    }
    /* copy-only outputs can be initialized right away */
    for (int o = 0; o < nb_output_files; o++) {
        int r = of_check_init(output_files[o]);
        if (r < 0) {
            ret = r;
            goto finish;
        }
    }
    if (stdin_interaction)
        av_log(NULL, AV_LOG_INFO, "Press [q] to stop, [?] for help\n");

    /* main loop */
    for (;;) {
        int active = 0;
        for (int i = 0; i < nb_input_files; i++) {
            InputFile *f = input_files[i];
            if (f->eof_reached) continue;
            /* is anything still consuming this input? */
            int used = 0;
            for (int o = 0; o < nb_output_files; o++)
                for (int s = 0; s < output_files[o]->nb_streams; s++) {
                    OutputStream *ost = output_files[o]->streams[s];
                    if (ost->ist->file == f && !ost->finished) used = 1;
                }
            active = 1;
            Packet pkt;
            packet_init(&pkt);
            int r = used ? f->ctx->ifmt->read_packet(f->ctx, &pkt) : AVERROR_EOF;
            if (r < 0) {
                f->eof_reached = 1;
                for (int s = 0; s < f->nb_streams; s++) {
                    int rr = process_input_packet(f->streams[s], NULL);
                    if (rr < 0) { ret = rr; goto finish; }
                }
                continue;
            }
            InputStream *ist = f->streams[pkt.stream_index];
            if (f->ts_offset) {
                int64_t off = av_rescale_q(f->ts_offset, (Rational){ 1, AV_TIME_BASE }, ist->st->time_base);
                if (pkt.pts != AV_NOPTS_VALUE) pkt.pts += off;
                if (pkt.dts != AV_NOPTS_VALUE) pkt.dts += off;
            }
            ist->nb_packets++;
            int rr = process_input_packet(ist, &pkt);
            packet_free(&pkt);
            if (rr < 0) { ret = rr; goto finish; }
        }
        if (!active) break;
    }

finish:
    {
        int had_err = ret;
        for (int o = 0; o < nb_output_files; o++) {
            OutputFile *of = output_files[o];
            if (header_failed && !of->header_written) {
                if (!had_err) {
                    av_log(of, AV_LOG_ERROR, "Nothing was written into output file, because at least one of its streams received no packets.\n");
                }
                if (o == 0) final_filesize0 = 0;
                continue;
            }
            int r = of_write_trailer(of);
            if (r < 0 && !ret) ret = r;
        }
    }
    print_report(1);
    return ret;
}

/* ------------------------------------------------------------------ */
static void exit_program(int ret)
{
    av_log(NULL, AV_LOG_VERBOSE, "Exiting with exit code %d\n", ret);
    fflush(stdout);
    fflush(stderr);
    exit(ret);
}

static int apply_global_option(OptEntry *e, int early)
{
    switch (e->def->id) {
    case O_Y: file_overwrite = atoi(e->val); break;
    case O_N: no_file_overwrite = atoi(e->val); break;
    case O_HIDE_BANNER: hide_banner = atoi(e->val); break;
    case O_STATS: print_stats = atoi(e->val); break;
    case O_STDIN: stdin_interaction = atoi(e->val); break;
    case O_XERROR: exit_on_error = atoi(e->val); break;
    case O_COPYTS: copy_ts = atoi(e->val); break;
    case O_LOGLEVEL: {
        int r = parse_loglevel_str(e->val);
        if (r < 0) {
            if (!early) {
                av_log(NULL, AV_LOG_ERROR, "Failed to set value '%s' for option '%s': %s\n", e->val, e->key, av_err2str_buf(r));
            }
            return r;
        }
        break; }
    case O_FILTER_COMPLEX:
        av_log(NULL, AV_LOG_ERROR, "Filtergraph '%s' was specified, but -filter_complex is not supported by this build.\n", e->val);
        return AVERROR(38);
    default:
        if (e->def->flags & OPT_FLAG_EXIT) {
            g_log_to_stdout = 1;
            int r = show_help_topic(e->def->id, e->val);
            if (r == 1) { g_log_to_stdout = 0; exit(0); }
            exit_program(0);
        }
        break;
    }
    return 0;
}

int main(int argc, char **argv)
{
    int ret;
    signal(SIGPIPE, SIG_IGN);
    setvbuf(stderr, NULL, _IONBF, 0);

    /* early loglevel / banner parsing */
    int has_version = 0;
    for (int i = 1; i < argc; i++) {
        const char *a = argv[i];
        if (a[0] != '-') continue;
        if ((!strcmp(a, "-loglevel") || !strcmp(a, "-v")) && i + 1 < argc) {
            parse_loglevel_str(argv[i + 1]);
            i++;
        } else if (!strcmp(a, "-hide_banner")) {
            hide_banner = 1;
        } else if (!strcmp(a, "-version")) {
            has_version = 1;
        } else if (!strcmp(a, "-nohide_banner")) {
            hide_banner = 0;
        }
    }
    if (!hide_banner && !has_version) show_banner();

    ret = split_commandline(argc, argv);
    if (ret < 0) {
        av_log(NULL, AV_LOG_FATAL, "Error splitting the argument list: %s\n", av_err2str_buf(ret));
        exit_program(ret & 0xff);
    }
    for (int i = 0; i < nb_global_opts; i++) {
        ret = apply_global_option(&global_opts[i], 0);
        if (ret < 0) {
            av_log(NULL, AV_LOG_FATAL, "Error parsing global options: %s\n", av_err2str_buf(ret));
            exit_program(ret & 0xff);
        }
    }

    int n_in = 0, n_out = 0;
    for (int i = 0; i < nb_groups; i++) { if (groups[i].is_input) n_in++; else n_out++; }
    if (!n_in && !n_out) {
        av_log(NULL, AV_LOG_INFO, "Universal media converter\n");
        av_log(NULL, AV_LOG_INFO, "usage: ffmpeg [options] [[infile options] -i infile]... {[outfile options] outfile}...\n\n");
        av_log(NULL, AV_LOG_WARNING, "Use -h to get full help or, even better, run 'man %s'\n", "ffmpeg");
        exit_program(1);
    }

    /* inputs */
    int idx = 0;
    for (int i = 0; i < nb_groups; i++) {
        if (!groups[i].is_input) continue;
        ret = open_input_file(&groups[i], idx++);
        if (ret < 0) {
            av_log(NULL, AV_LOG_FATAL, "Error opening input files: %s\n", av_err2str_buf(ret));
            exit_program(ret & 0xff);
        }
    }
    if (!n_out) {
        av_log(NULL, AV_LOG_FATAL, "At least one output file must be specified\n");
        exit_program(1);
    }
    idx = 0;
    for (int i = 0; i < nb_groups; i++) {
        if (groups[i].is_input) continue;
        ret = open_output_file(&groups[i], idx++);
        if (ret < 0) {
            if (ret == AVERROR_EXIT) exit_program(0);
            av_log(NULL, AV_LOG_FATAL, "Error opening output files: %s\n", av_err2str_buf(ret));
            exit_program(ret & 0xff);
        }
    }
    transcode_start_time = av_gettime_relative_s();
    ret = transcode();
    if (ret < 0) {
        av_log(NULL, AV_LOG_FATAL, "Conversion failed!\n");
        exit_program(ret & 0xff);
    }
    exit_program(0);
    return 0;
}
