/* polyphase resampler compatible with the default libswresample engine behaviour */
#include "resample.h"

struct Resampler {
    int in_rate, out_rate, ch;
    int fmt;
    int felem_size;
    int filter_shift;
    int phase_count;
    int filter_length;
    int filter_alloc;
    void *filter_bank;
    int src_incr, dst_incr, dst_incr_div, dst_incr_mod;
    int index, frac;
    int linear;
    /* input buffer */
    uint8_t **buf;
    int buf_size;   /* in samples */
    int in_buffer_index, in_buffer_count;
    int resample_in_constraint;
    int flushed;
    int64_t outpts, firstpts;
};

static double bessel(double x)
{
    double lastv = 0;
    double t, v;
    int i;
    static double inv[100];
    static int inited;
    if (!inited) {
        for (int k = 0; k < 100; k++) inv[k] = 1.0 / ((k + 1) * (k + 1));
        inited = 1;
    }
    x = x * x / 4;
    t = x;
    v = 1 + x;
    for (i = 1; v != lastv; i += 2) {
        t *= x * inv[i];
        v += t;
        lastv = v;
        t *= x * inv[i + 1];
        v += t;
    }
    return v;
}

static void build_filter(Resampler *c, void *filter, double factor, int tap_count, int alloc, int phase_count,
                         int scale, double kaiser_beta)
{
    int ph, i;
    int ph_nb = phase_count % 2 ? phase_count : phase_count / 2 + 1;
    double x, y, w, s;
    double *tab = malloc((tap_count + 1) * sizeof(double));
    double *sin_lut = malloc(ph_nb * sizeof(double));
    const int center = (tap_count - 1) / 2;
    double norm = 0;

    if (factor > 1.0) factor = 1.0;
    if (factor == 1.0) {
        for (ph = 0; ph < ph_nb; ph++)
            sin_lut[ph] = sin(M_PI * ph / phase_count) * (center & 1 ? 1 : -1);
    }
    for (ph = 0; ph < ph_nb; ph++) {
        s = factor == 1.0 ? sin_lut[ph] : 0;
        for (i = 0; i < tap_count; i++) {
            x = M_PI * ((double)(i - center) - (double)ph / phase_count) * factor;
            if (x == 0) y = 1.0;
            else if (factor == 1.0) y = s / x;
            else y = sin(x) / x;
            w = 2.0 * x / (factor * tap_count * M_PI);
            y *= bessel(kaiser_beta * sqrt(FFMAX(1 - w * w, 0)));
            tab[i] = y;
            s = -s;
            if (!ph) norm += y;
        }
        switch (c->fmt) {
        case SF_S16P:
            for (i = 0; i < tap_count; i++)
                ((int16_t *)filter)[ph * alloc + i] = av_clip_int16((int)lrintf((float)(tab[i] * scale / norm)));
            if (phase_count % 2) break;
            for (i = 0; i < tap_count; i++)
                ((int16_t *)filter)[(phase_count - ph) * alloc + tap_count - 1 - i] = ((int16_t *)filter)[ph * alloc + i];
            break;
        case SF_S32P:
            for (i = 0; i < tap_count; i++)
                ((int32_t *)filter)[ph * alloc + i] = av_clipl_int32(llrint(tab[i] * scale / norm));
            if (phase_count % 2) break;
            for (i = 0; i < tap_count; i++)
                ((int32_t *)filter)[(phase_count - ph) * alloc + tap_count - 1 - i] = ((int32_t *)filter)[ph * alloc + i];
            break;
        case SF_FLTP:
            for (i = 0; i < tap_count; i++)
                ((float *)filter)[ph * alloc + i] = (float)(tab[i] * scale / norm);
            if (phase_count % 2) break;
            for (i = 0; i < tap_count; i++)
                ((float *)filter)[(phase_count - ph) * alloc + tap_count - 1 - i] = ((float *)filter)[ph * alloc + i];
            break;
        case SF_DBLP:
            for (i = 0; i < tap_count; i++)
                ((double *)filter)[ph * alloc + i] = tab[i] * scale / norm;
            if (phase_count % 2) break;
            for (i = 0; i < tap_count; i++)
                ((double *)filter)[(phase_count - ph) * alloc + tap_count - 1 - i] = ((double *)filter)[ph * alloc + i];
            break;
        }
    }
    free(tab);
    free(sin_lut);
}

static int64_t gcd64(int64_t a, int64_t b) { while (b) { int64_t t = a % b; a = b; b = t; } return a; }

/* simplified av_reduce for exact cases */
static int reduce(int *dst_num, int *dst_den, int64_t num, int64_t den, int64_t max)
{
    int64_t g = gcd64(num < 0 ? -num : num, den < 0 ? -den : den);
    if (g) { num /= g; den /= g; }
    if (num <= max && den <= max) { *dst_num = (int)num; *dst_den = (int)den; return 1; }
    /* continued fraction approximation */
    int64_t a0n = 0, a0d = 1, a1n = 1, a1d = 0;
    int64_t n = num, d = den;
    while (d) {
        int64_t x = n / d;
        int64_t next_den = n - d * x;
        int64_t a2n = x * a1n + a0n, a2d = x * a1d + a0d;
        if (a2n > max || a2d > max) {
            if (a1n) x = (max - a0n) / a1n;
            if (a1d) x = FFMIN(x, (max - a0d) / a1d);
            if (den * (2 * x * a1d + a0d) > num * a1d)
                { a1n = x * a1n + a0n; a1d = x * a1d + a0d; }
            break;
        }
        a0n = a1n; a0d = a1d; a1n = a2n; a1d = a2d;
        n = d; d = next_den;
    }
    *dst_num = (int)a1n; *dst_den = (int)a1d;
    return d == 0;
}

Resampler *resampler_init(int in_rate, int out_rate, int channels, int fmt)
{
    Resampler *c = calloc(1, sizeof(*c));
    int filter_size = 32, phase_shift = 10, linear = 1;
    double cutoff = 0.97, kaiser_beta = 9;
    double factor = FFMIN(out_rate * cutoff / in_rate, 1.0);
    int phase_count = 1 << phase_shift;
    int filter_length = FFMAX((int)ceil(filter_size / factor), 1);
    if (filter_length > 1) filter_length = (filter_length + 1) & ~1;
    {
        int pce, pced;
        reduce(&pce, &pced, out_rate, in_rate, INT_MAX);
        if (pce <= phase_count) phase_count = pce;
    }
    c->in_rate = in_rate;
    c->out_rate = out_rate;
    c->ch = channels;
    c->fmt = fmt;
    c->felem_size = sf_bytes(fmt);
    c->filter_shift = fmt == SF_S16P ? 15 : fmt == SF_S32P ? 30 : 0;
    c->phase_count = phase_count;
    c->linear = linear;
    c->filter_length = filter_length;
    c->filter_alloc = (filter_length + 7) & ~7;
    c->filter_bank = calloc(c->filter_alloc, (size_t)(phase_count + 1) * c->felem_size + 64);
    build_filter(c, c->filter_bank, factor, c->filter_length, c->filter_alloc, phase_count, 1 << c->filter_shift, kaiser_beta);
    uint8_t *fb = c->filter_bank;
    memcpy(fb + (size_t)(c->filter_alloc * phase_count + 1) * c->felem_size, fb, (size_t)(c->filter_alloc - 1) * c->felem_size);
    memcpy(fb + (size_t)(c->filter_alloc * phase_count) * c->felem_size, fb + (size_t)(c->filter_alloc - 1) * c->felem_size, c->felem_size);
    reduce(&c->src_incr, &c->dst_incr, out_rate, (int64_t)in_rate * phase_count, INT32_MAX / 2);
    while (c->dst_incr < (1 << 20) && c->src_incr < (1 << 20)) {
        c->dst_incr *= 2;
        c->src_incr *= 2;
    }
    c->dst_incr_div = c->dst_incr / c->src_incr;
    c->dst_incr_mod = c->dst_incr % c->src_incr;
    c->index = -phase_count * ((c->filter_length - 1) / 2);
    c->frac = 0;
    c->buf = calloc(channels, sizeof(uint8_t *));
    c->firstpts = AV_NOPTS_VALUE;
    c->outpts = AV_NOPTS_VALUE;
    return c;
}

static void buf_realloc(Resampler *c, int size)
{
    if (size <= c->buf_size) return;
    int ns = FFMAX(size, c->buf_size * 2);
    for (int i = 0; i < c->ch; i++) {
        uint8_t *n = calloc((size_t)ns + 8, c->felem_size);
        if (c->buf[i]) memcpy(n, c->buf[i], (size_t)c->buf_size * c->felem_size);
        free(c->buf[i]);
        c->buf[i] = n;
    }
    c->buf_size = ns;
}

/* resample_common / linear for one channel */
static int resample_ch(Resampler *c, void *dest, const void *source, int n, int update_ctx)
{
    int dst_index;
    int index = c->index;
    int frac = c->frac;
    int sample_index = 0;
    int use_linear = c->linear && (c->frac || c->dst_incr_mod);

    while (index >= c->phase_count) {
        sample_index++;
        index -= c->phase_count;
    }
    for (dst_index = 0; dst_index < n; dst_index++) {
        switch (c->fmt) {
        case SF_S16P: {
            const int16_t *src = source;
            int16_t *dst = dest;
            const int16_t *filter = (const int16_t *)c->filter_bank + (size_t)c->filter_alloc * index;
            int64_t v;
            if (!use_linear) {
                int32_t val = 0, val2 = 0;
                int i;
                for (i = 0; i + 1 < c->filter_length; i += 2) {
                    val += src[sample_index + i] * (int32_t)filter[i];
                    val2 += src[sample_index + i + 1] * (int32_t)filter[i + 1];
                }
                if (i < c->filter_length)
                    val += src[sample_index + i] * (int32_t)filter[i];
                v = (int64_t)val + (int64_t)val2;
            } else {
                int32_t val = 0, v2 = 0;
                for (int i = 0; i < c->filter_length; i++) {
                    val += src[sample_index + i] * (int32_t)filter[i];
                    v2 += src[sample_index + i] * (int32_t)filter[i + c->filter_alloc];
                }
                v = val + (int64_t)(v2 - val) * frac / c->src_incr;
            }
            v = (v + (1 << 14)) >> 15;
            dst[dst_index] = (unsigned)(v + 32768) > 65535 ? (int16_t)((v >> 31) ^ 32767) : (int16_t)v;
            break; }
        case SF_S32P: {
            const int32_t *src = source;
            int32_t *dst = dest;
            const int32_t *filter = (const int32_t *)c->filter_bank + (size_t)c->filter_alloc * index;
            int64_t val = 0, val2 = 0;
            int i;
            if (!use_linear) {
                for (i = 0; i + 1 < c->filter_length; i += 2) {
                    val += src[sample_index + i] * (int64_t)filter[i];
                    val2 += src[sample_index + i + 1] * (int64_t)filter[i + 1];
                }
                if (i < c->filter_length) val += src[sample_index + i] * (int64_t)filter[i];
                val += val2;
            } else {
                int64_t v2 = 0;
                for (i = 0; i < c->filter_length; i++) {
                    val += src[sample_index + i] * (int64_t)filter[i];
                    v2 += src[sample_index + i] * (int64_t)filter[i + c->filter_alloc];
                }
                val += (v2 - val) / c->src_incr * frac;
            }
            val = (val + (1 << 29)) >> 30;
            dst[dst_index] = (uint64_t)(val + 0x80000000) > 0xFFFFFFFF ? (int32_t)((val >> 63) ^ 0x7FFFFFFF) : (int32_t)val;
            break; }
        case SF_FLTP: {
            const float *src = source;
            float *dst = dest;
            const float *filter = (const float *)c->filter_bank + (size_t)c->filter_alloc * index;
            float val = 0, val2 = 0;
            int i;
            if (!use_linear) {
                for (i = 0; i + 1 < c->filter_length; i += 2) {
                    val += src[sample_index + i] * filter[i];
                    val2 += src[sample_index + i + 1] * filter[i + 1];
                }
                if (i < c->filter_length) val += src[sample_index + i] * filter[i];
                dst[dst_index] = val + val2;
            } else {
                float v2 = 0;
                double inv_src_incr = 1.0 / c->src_incr;
                for (i = 0; i < c->filter_length; i++) {
                    val += src[sample_index + i] * filter[i];
                    v2 += src[sample_index + i] * filter[i + c->filter_alloc];
                }
                val += (float)((v2 - val) * inv_src_incr * frac);
                dst[dst_index] = val;
            }
            break; }
        case SF_DBLP: {
            const double *src = source;
            double *dst = dest;
            const double *filter = (const double *)c->filter_bank + (size_t)c->filter_alloc * index;
            double val = 0, val2 = 0;
            int i;
            if (!use_linear) {
                for (i = 0; i + 1 < c->filter_length; i += 2) {
                    val += src[sample_index + i] * filter[i];
                    val2 += src[sample_index + i + 1] * filter[i + 1];
                }
                if (i < c->filter_length) val += src[sample_index + i] * filter[i];
                dst[dst_index] = val + val2;
            } else {
                double v2 = 0;
                double inv_src_incr = 1.0 / c->src_incr;
                for (i = 0; i < c->filter_length; i++) {
                    val += src[sample_index + i] * filter[i];
                    v2 += src[sample_index + i] * filter[i + c->filter_alloc];
                }
                val += (v2 - val) * inv_src_incr * frac;
                dst[dst_index] = val;
            }
            break; }
        }
        frac += c->dst_incr_mod;
        index += c->dst_incr_div;
        if (frac >= c->src_incr) {
            frac -= c->src_incr;
            index++;
        }
        while (index >= c->phase_count) {
            sample_index++;
            index -= c->phase_count;
        }
    }
    if (update_ctx) {
        c->frac = frac;
        c->index = index;
    }
    return sample_index;
}

static int multiple_resample(Resampler *c, uint8_t **dst, int dst_off, int dst_size,
                             uint8_t **src, int src_off, int src_size, int *consumed)
{
    int64_t max_src_size = (INT64_MAX / 2 / c->phase_count) / c->src_incr;
    src_size = (int)FFMIN(src_size, max_src_size);
    *consumed = 0;
    int64_t end_index = (1LL + src_size - c->filter_length) * c->phase_count;
    int64_t delta_frac = (end_index - c->index) * c->src_incr - c->frac;
    int delta_n = (int)((delta_frac + c->dst_incr - 1) / c->dst_incr);
    dst_size = FFMAX(FFMIN(dst_size, delta_n), 0);
    if (dst_size > 0) {
        for (int i = 0; i < c->ch; i++)
            *consumed = resample_ch(c, dst[i] + (size_t)dst_off * c->felem_size,
                                    src[i] + (size_t)src_off * c->felem_size, dst_size, i + 1 == c->ch);
    }
    return dst_size;
}

/* invert_initial_buffer emulation; returns border or INT_MAX */
static int invert_initial_buffer(Resampler *c, uint8_t **src, int src_off, int in_count)
{
    int n, ch, num = FFMIN(in_count + c->in_buffer_count, c->filter_length + 1), res;
    if (c->index >= 0) return 0;
    buf_realloc(c, c->filter_length * 2 + 1);
    for (n = c->in_buffer_count; n < num; n++)
        for (ch = 0; ch < c->ch; ch++)
            memcpy(c->buf[ch] + (size_t)(c->filter_length + n) * c->felem_size,
                   src[ch] + (size_t)(src_off + n - c->in_buffer_count) * c->felem_size, c->felem_size);
    if (num < c->filter_length + 1) {
        c->in_buffer_count = num;
        c->in_buffer_index = c->filter_length;
        return INT_MAX;
    }
    for (n = 1; n <= c->filter_length; n++)
        for (ch = 0; ch < c->ch; ch++)
            memcpy(c->buf[ch] + (size_t)(c->filter_length - n) * c->felem_size,
                   c->buf[ch] + (size_t)(c->filter_length + n) * c->felem_size, c->felem_size);
    res = num - c->in_buffer_count;
    c->in_buffer_index = c->filter_length;
    while (c->index < 0) {
        --c->in_buffer_index;
        c->index += c->phase_count;
    }
    c->in_buffer_count = FFMAX(c->in_buffer_count + c->filter_length, 1 + c->filter_length * 2) - c->in_buffer_index;
    return FFMAX(res, 0);
}

static void flush_buffer(Resampler *c)
{
    int reflection = (FFMIN(c->in_buffer_count, c->filter_length) + 1) / 2;
    buf_realloc(c, c->in_buffer_index + c->in_buffer_count + reflection);
    for (int i = 0; i < c->ch; i++)
        for (int j = 0; j < reflection; j++)
            memcpy(c->buf[i] + (size_t)(c->in_buffer_index + c->in_buffer_count + j) * c->felem_size,
                   c->buf[i] + (size_t)(c->in_buffer_index + c->in_buffer_count - j - 1) * c->felem_size, c->felem_size);
    c->in_buffer_count += reflection;
}

int resampler_convert(Resampler *s, void **outv, int out_count, void **inv, int in_count)
{
    uint8_t **out = (uint8_t **)outv;
    uint8_t **in = (uint8_t **)inv;
    uint8_t *empty[64];
    int in_off = 0, out_off = 0;
    int ret_sum = 0;
    int border = 0;
    int padless = 1;

    if (!in) {
        if (!s->flushed) flush_buffer(s);
        s->resample_in_constraint = 0;
        s->flushed = 1;
        for (int i = 0; i < s->ch; i++) empty[i] = NULL;
        in = empty;
        in_count = 0;
    }

    if (in_count || s->index < 0) {
        if (in_count) {
            border = invert_initial_buffer(s, in, in_off, in_count);
            if (border == INT_MAX) return 0;
            if (border) {
                in_off += border;
                in_count -= border;
                s->resample_in_constraint = 0;
            }
        }
    }

    for (;;) {
        int ret, size, consumed;
        if (!s->resample_in_constraint && s->in_buffer_count) {
            ret = multiple_resample(s, out, out_off, out_count, s->buf, s->in_buffer_index, s->in_buffer_count, &consumed);
            out_count -= ret;
            ret_sum += ret;
            out_off += ret;
            s->in_buffer_count -= consumed;
            s->in_buffer_index += consumed;
            if (!in_count) break;
            if (s->in_buffer_count <= border) {
                in_off -= s->in_buffer_count;
                in_count += s->in_buffer_count;
                s->in_buffer_count = 0;
                s->in_buffer_index = 0;
                border = 0;
            }
        }
        if ((s->flushed || in_count > padless) && !s->in_buffer_count) {
            s->in_buffer_index = 0;
            ret = multiple_resample(s, out, out_off, out_count, in, in_off, FFMAX(in_count - padless, 0), &consumed);
            out_count -= ret;
            ret_sum += ret;
            out_off += ret;
            in_count -= consumed;
            in_off += consumed;
        }
        size = s->in_buffer_index + s->in_buffer_count + in_count;
        if (size > s->buf_size && s->in_buffer_count + in_count <= s->in_buffer_index) {
            for (int i = 0; i < s->ch; i++)
                memmove(s->buf[i], s->buf[i] + (size_t)s->in_buffer_index * s->felem_size, (size_t)s->in_buffer_count * s->felem_size);
            s->in_buffer_index = 0;
        } else
            buf_realloc(s, size);
        if (in_count) {
            int count = in_count;
            if (s->in_buffer_count && s->in_buffer_count + 2 < count && out_count) count = s->in_buffer_count + 2;
            for (int i = 0; i < s->ch; i++)
                memcpy(s->buf[i] + (size_t)(s->in_buffer_index + s->in_buffer_count) * s->felem_size,
                       in[i] + (size_t)in_off * s->felem_size, (size_t)count * s->felem_size);
            s->in_buffer_count += count;
            in_count -= count;
            border += count;
            in_off += count;
            s->resample_in_constraint = 0;
            if (s->in_buffer_count != count || in_count) continue;
            if (padless) { padless = 0; continue; }
        }
        break;
    }
    s->resample_in_constraint = !!out_count;
    if (ret_sum > 0) s->outpts += ret_sum * (int64_t)s->in_rate;
    return ret_sum;
}

int64_t resampler_get_delay(Resampler *c, int64_t base)
{
    int64_t num = c->in_buffer_count - (c->filter_length - 1) / 2;
    num *= c->phase_count;
    num -= c->index;
    num *= c->src_incr;
    num -= c->frac;
    return av_rescale(num, base, c->in_rate * (int64_t)c->src_incr * c->phase_count);
}

int64_t resampler_next_pts(Resampler *s, int64_t pts)
{
    if (pts == INT64_MIN) return s->outpts;
    if (s->firstpts == AV_NOPTS_VALUE) s->outpts = s->firstpts = pts;
    return (s->outpts = pts - resampler_get_delay(s, s->in_rate * (int64_t)s->out_rate));
}

void resampler_free(Resampler *c)
{
    if (!c) return;
    for (int i = 0; i < c->ch; i++) free(c->buf[i]);
    free(c->buf);
    free(c->filter_bank);
    free(c);
}
