static int queue_cb(void *opaque, Frame *f)
{
    LavfiSource *s = opaque;
    if (!f) return 0;
    if (s->nq == s->qcap) { s->qcap = s->qcap * 2 + 4; s->queue = realloc(s->queue, sizeof(Frame *) * s->qcap); }
