int lavfi_read(LavfiSource *s, Packet *pkt)
{
    if (!s->fc) return lavfi_read_src(s, pkt);
    while (!s->nq) {
        if (s->src_eof) return AVERROR_EOF;
        Packet sp;
        packet_init(&sp);
        int r = lavfi_read_src(s, &sp);
        if (r < 0) {
            s->src_eof = 1;
            filterchain_push(s->fc, NULL, queue_cb, s);
            continue;
        }
        int bps = sf_bytes(s->sample_fmt) * s->layout.nb_channels;
        Frame *f = frame_alloc(s->sample_fmt, sp.size / bps, &s->layout, s->sample_rate);
        memcpy(f->data, sp.data, sp.size);
        f->pts = sp.pts;
        packet_free(&sp);
        filterchain_push(s->fc, f, queue_cb, s);
    }
    Frame *f = s->queue[0];
    memmove(s->queue, s->queue + 1, sizeof(Frame *) * (s->nq - 1));
    s->nq--;
    pkt->size = frame_bytes(f);
    pkt->data = malloc(pkt->size + 64);
    memcpy(pkt->data, f->data, pkt->size);
    memset(pkt->data + pkt->size, 0, 64);
    pkt->pts = pkt->dts = f->pts;
    pkt->duration = f->nb_samples;
    pkt->flags = PKT_FLAG_KEY;
    pkt->stream_index = 0;
    frame_free(f);
    return 0;
}

