typedef struct NCtx { const LogClass *cls; char name[96]; void *parent; } NCtx;
static const char *nctx_name(void *c) { return ((NCtx *)c)->name; }
static void *nctx_parent(void *c) { return ((NCtx *)c)->parent; }
static const LogClass nctx_class = { "filter", nctx_name, nctx_parent };

static int parse_value(NCtx *fctx, const FOpt *o, const char *key, const char *val, FVals *out)
{
    int slot = o->slot;
    switch (o->type) {
    case FT_DUR: {
        int64_t us;
        if (parse_time(&us, val, 1) < 0) {
            av_log(fctx, AV_LOG_ERROR, "Unable to parse \"%s\" option value \"%s\" as duration\n", key, val);
            return AVERROR(22);
        }
        if (us < o->min || us > o->max) {
            av_log(fctx, AV_LOG_ERROR, "Value %f for parameter '%s' out of range [%g - %g]\n", (double)us, key, o->min, o->max);
            return AVERROR(34);
        }
        out->i64[slot] = us;
        break; }
    case FT_STR:
        snprintf(out->s[slot], sizeof(out->s[slot]), "%s", val);
        break;
    case FT_CHLAYOUT: {
        ChLayout l;
        if (chl_from_string(&l, val) < 0) {
            av_log(fctx, AV_LOG_ERROR, "Unable to parse \"%s\" option value \"%s\" as channel layout\n", key, val);
            return AVERROR(22);
        }
        out->l[slot] = l;
        break; }
    case FT_BOOL: {
        int n = -2;
        if (!strcmp(val, "auto")) n = -1;
        else if (!strcasecmp(val, "true") || !strcasecmp(val, "y") || !strcasecmp(val, "yes") || !strcasecmp(val, "enable") || !strcasecmp(val, "enabled") || !strcasecmp(val, "on")) n = 1;
        else if (!strcasecmp(val, "false") || !strcasecmp(val, "n") || !strcasecmp(val, "no") || !strcasecmp(val, "disable") || !strcasecmp(val, "disabled") || !strcasecmp(val, "off")) n = 0;
        else {
            char *end;
            n = (int)strtol(val, &end, 10);
            if (*end || end == val) n = -3;
        }
        if (n < o->min || n > o->max) {
            av_log(fctx, AV_LOG_ERROR, "Unable to parse \"%s\" option value \"%s\" as boolean\n", key, val);
            return AVERROR(22);
        }
        out->i64[slot] = n;
        break; }
    default: {
        double d;
        int found = 0;
        if (o->consts) {
            char buf[512];
            snprintf(buf, sizeof(buf), "%s", o->consts);
            char *save, *tok = strtok_r(buf, ",", &save);
            while (tok) {
                char *eq = strchr(tok, '=');
                if (eq) {
                    *eq = 0;
                    if (!strcmp(tok, val)) { d = atof(eq + 1); found = 1; break; }
                }
                tok = strtok_r(NULL, ",", &save);
            }
        }
        if (!found) {
            if (!strcmp(val, "max")) d = o->max;
            else if (!strcmp(val, "min")) d = o->min;
            else if (expr_parse_and_eval(&d, val) < 0) {
                NCtx ectx = { &nctx_class, "Eval", fctx };
                av_log(&ectx, AV_LOG_ERROR, "Undefined constant or missing '(' in '%s'\n", val);
                av_log(fctx, AV_LOG_ERROR, "Unable to parse \"%s\" option value \"%s\"\n", key, val);
                return AVERROR(22);
            }
        }
        if (d < o->min || d > o->max) {
            av_log(fctx, AV_LOG_ERROR, "Value %f for parameter '%s' out of range [%g - %g]\n", d, key, o->min, o->max);
            return AVERROR(34);
        }
        out->d[slot] = d;
        out->i64[slot] = (o->type == FT_INT || o->type == FT_INT64 || o->type == FT_CONSTINT) ? llrint(d) : (int64_t)d;
        break; }
    }
    out->set[slot] = 1;
    return 0;
}

int fopts_parse(const char *fname, int fidx, const FOpt *opts, const char *const *shorthand,
                const char *args, FVals *out, int mode)
{
    char keys[32][64], vals[32][256];
    int n = args ? parse_filter_opts(args, shorthand, keys, vals, 32) : 0;
    NCtx fctx = { &nctx_class, "", NULL };
    NCtx gctx = { &nctx_class, "AVFilterGraph", NULL };
    NCtx fcctx = { &nctx_class, "fc#-1", NULL };
    snprintf(fctx.name, sizeof(fctx.name), "Parsed_%s_%d", fname, fidx);
    if (n < 0) {
        av_log(&gctx, AV_LOG_ERROR, "No option name near '%s'\n", args);
        return AVERROR(22);
    }
    for (int i = 0; i < n; i++) {
        const FOpt *o = NULL;
        for (int k = 0; opts[k].name; k++) if (!strcmp(opts[k].name, keys[i])) { o = &opts[k]; break; }
        if (!o) {
            if (mode == 1) {
                av_log(&fctx, AV_LOG_ERROR, "Could not set non-existent option '%s' to value '%s'\n", keys[i], vals[i]);
                av_log(&gctx, AV_LOG_ERROR, "Error processing filtergraph: %s\n", av_err2str_buf(AVERROR_OPTION_NOT_FOUND));
            } else {
                av_log(&fcctx, AV_LOG_ERROR, "Error applying option '%s' to filter '%s': %s\n", keys[i], fname, av_err2str_buf(AVERROR_OPTION_NOT_FOUND));
            }
            return AVERROR_OPTION_NOT_FOUND;
        }
        int r = parse_value(&fctx, o, keys[i], vals[i], out);
        if (r < 0) {
            if (mode == 1) {
                av_log(&fctx, AV_LOG_ERROR, "Error setting option %s to value %s.\n", keys[i], vals[i]);
                av_log(&gctx, AV_LOG_ERROR, "Error processing filtergraph: %s\n", av_err2str_buf(r));
            } else {
                av_log(&fcctx, AV_LOG_ERROR, "Error applying option '%s' to filter '%s': %s\n", keys[i], fname, av_err2str_buf(r));
            }
            return r;
        }
    }
    return 0;
}
EOF
