static int lavfi_open_src(LavfiSource **out, const char *spec, void *logctx)
{
    LavfiSource *s = calloc(1, sizeof(*s));
    char name[64];
    const char *args = strchr(spec, '=');
    int nl = args ? (int)(args - spec) : (int)strlen(spec);
    if (nl >= 64) nl = 63;
    memcpy(name, spec, nl); name[nl] = 0;
    if (args) args++;
    FVals v;
    memset(&v, 0, sizeof(v));
    int r;
    s->nb_samples = 1024;
    typedef struct { const LogClass *cls; char name[32]; void *p; } GC;
    if (!strcmp(name, "sine")) {
        r = fopts_parse("sine", 0, sine_opts, sine_sh, args, &v, 1);
        if (r < 0) { free(s); return r; }
        double freq = v.set[0] ? v.d[0] : 440, beep = v.set[1] ? v.d[1] : 0;
        int64_t dur = v.set[3] ? v.i64[3] : 0;
        s->type = SRC_SINE;
        s->sample_rate = v.set[2] ? (int)v.i64[2] : 44100;
        if (v.set[4]) {
            double d;
            if (expr_parse_and_eval(&d, v.s[4]) == 0) s->nb_samples = (int)d;
        }
        chl_default(&s->layout, 1);
        s->sin = malloc(sizeof(int16_t) << LOG_PERIOD);
        make_sin_table(s->sin);
        s->dphi = (uint32_t)(int64_t)(ldexp(freq, 32) / s->sample_rate + 0.5);
        to_rational(freq, &s->fnum, &s->fden);
        if (beep) {
            s->beep_period = s->sample_rate;
            s->beep_length = s->beep_period / 25;
            s->dphi_beep = (uint32_t)(int64_t)(ldexp(beep * freq, 32) / s->sample_rate + 0.5);
            to_rational(beep * freq, &s->bnum, &s->bden);
        }
        s->duration = dur ? av_rescale(dur, s->sample_rate, AV_TIME_BASE) : 0;
        s->sample_fmt = SF_S16;
    } else if (!strcmp(name, "anullsrc")) {
        r = fopts_parse("anullsrc", 0, anull_opts, anull_sh, args, &v, 1);
        if (r < 0) { free(s); return r; }
        s->type = SRC_ANULL;
        s->sample_rate = v.set[1] ? (int)v.i64[1] : 44100;
        if (v.set[0]) s->layout = v.l[0];
        else chl_default(&s->layout, 2);
        if (v.set[2]) s->nb_samples = (int)v.i64[2];
        int64_t dur = v.set[3] ? v.i64[3] : -1;
        s->duration = dur >= 0 ? av_rescale(dur, s->sample_rate, AV_TIME_BASE) : 0;
        if (dur == 0) s->duration = -1;
        s->sample_fmt = SF_U8;
    } else if (!strcmp(name, "aevalsrc")) {
        r = fopts_parse("aevalsrc", 0, aeval_opts, aeval_sh, args, &v, 1);
        if (r < 0) { free(s); return r; }
        s->type = SRC_AEVAL;
        s->sample_rate = 44100;
        if (v.set[2]) s->sample_rate = atoi(v.s[2]);
        if (v.set[1]) s->nb_samples = (int)v.i64[1];
        int64_t dur = v.set[3] ? v.i64[3] : -1;
        char exprs[1024];
        snprintf(exprs, sizeof(exprs), "%s", v.set[0] ? v.s[0] : "");
        char *save, *tok = strtok_r(exprs, "|", &save);
        while (tok && s->nb_exprs < 8) {
            static const char *const vars[] = { "ch", "n", "s", "t", NULL };
            if (expr_parse(&s->exprs[s->nb_exprs], tok, vars) < 0) {
                GC gc = { NULL, "", NULL };
                (void)gc;
                av_log(NULL, AV_LOG_ERROR, "Undefined constant or missing '(' in '%s'\n", tok);
                free(s);
                return AVERROR(22);
            }
            s->nb_exprs++;
            tok = strtok_r(NULL, "|", &save);
        }
        if (!s->nb_exprs) { free(s); return AVERROR(22); }
        if (v.set[4]) chl_from_string(&s->layout, v.s[4]);
        else chl_default(&s->layout, s->nb_exprs);
        s->duration = dur >= 0 ? av_rescale(dur, s->sample_rate, AV_TIME_BASE) : 0;
        s->sample_fmt = SF_DBL;
    } else {
        static const LogClass gcls = { "AVFilterGraph", NULL, NULL };
        struct { const LogClass *cls; } g = { &gcls };
        av_log(&g, AV_LOG_ERROR, "No such filter: '%s'\n", name);
        av_log(&g, AV_LOG_ERROR, "Error processing filtergraph: %s\n", av_err2str_buf(AVERROR_FILTER_NOT_FOUND));
        free(s);
        return AVERROR_FILTER_NOT_FOUND;
    }
    (void)logctx;
    *out = s;
    return 0;
}

