    { "c", FT_CONSTINT, -1, 22, 5, "nofade=-1,tri=0,qsin=1,esin=2,hsin=3,log=4,ipar=5,qua=6,cub=7,squ=8,cbr=9,par=10,exp=11,iqsin=12,ihsin=13,dese=14,desi=15,losi=16,sinc=17,isinc=18,quat=19,quatr=20,qsin2=21,hsin2=22" },
    { "silence", FT_DOUBLE, 0, 1, 6, NULL }, { "unity", FT_DOUBLE, 0, 1, 7, NULL },
    { NULL }
};
static const char *const afade_sh[] = { "type", "start_sample", "nb_samples", "start_time", "duration", "curve", "silence", "unity", NULL };
static const FOpt aformat_opts[] = {
    { "sample_fmts", FT_STR, 0, 0, 0, NULL }, { "f", FT_STR, 0, 0, 0, NULL },
    { "sample_rates", FT_STR, 0, 0, 1, NULL }, { "r", FT_STR, 0, 0, 1, NULL },
    { "channel_layouts", FT_STR, 0, 0, 2, NULL }, { "cl", FT_STR, 0, 0, 2, NULL },
    { NULL }
};
static const char *const aformat_sh[] = { "sample_fmts", "sample_rates", "channel_layouts", NULL };
static const FOpt aresample_opts[] = {
    { "sample_rate", FT_INT, 0, INT_MAX, 0, NULL }, { "osr", FT_INT, 0, INT_MAX, 0, NULL },
    { "out_sample_rate", FT_INT, 0, INT_MAX, 0, NULL }, { "isr", FT_INT, 0, INT_MAX, 1, NULL },
    { NULL }
};
static const char *const aresample_sh[] = { "sample_rate", NULL };
static const FOpt anull_fopts[] = { { NULL } };

typedef struct LC { const LogClass *cls; char name[64]; void *p; } LC;
static const char *lc_name(void *c) { return ((LC *)c)->name; }
static const LogClass lc_class = { "LC", lc_name, NULL };

static AFilter *make_filter(const char *name, const char *args, int idx, int mode, int *err)
{
    AFilter *f = calloc(1, sizeof(*f));
    FVals v;
    memset(&v, 0, sizeof(v));
    *err = 0;
    snprintf(f->name, sizeof(f->name), "%s", name);
    int r = 0;
    if (!strcmp(name, "anull") || !strcmp(name, "acopy")) {
        f->type = F_ANULL;
        r = fopts_parse(name, idx, anull_fopts, NULL, args, &v, mode);
    } else if (!strcmp(name, "volume")) {
        f->type = F_VOLUME;
        r = fopts_parse(name, idx, volume_opts, volume_sh, args, &v, mode);
        if (r >= 0) {
            f->volume = 1.0;
            f->precision = v.set[1] ? (int)v.i64[1] : 1;
            if (v.set[0] && parse_volume_expr(v.s[0], &f->volume) < 0) {
                LC fc = { &lc_class, "", NULL };
                LC ec = { &lc_class, "Eval", NULL };
                snprintf(fc.name, sizeof(fc.name), "Parsed_volume_%d", idx);
                /* nested prefix */
                char pre[160];
                snprintf(pre, sizeof(pre), "%s", fc.name);
                (void)pre;
                struct { const LogClass *cls; char name[64]; void *p; } *dummy = NULL;
                (void)dummy;
                av_log(&fc, AV_LOG_ERROR, "%s", "");
                (void)ec;
                r = AVERROR(22);
                f->volume_err = 1;
                snprintf(f->volume_expr, sizeof(f->volume_expr), "%s", v.s[0]);
            }
            if (f->precision == 0) {
                f->volume_i = (int)(f->volume * 256 + 0.5);
                f->volume = f->volume_i / 256.0;
            }
        }
    } else if (!strcmp(name, "atrim")) {
        f->type = F_ATRIM;
        r = fopts_parse(name, idx, atrim_opts, atrim_sh, args, &v, mode);
        f->start_us = v.set[0] ? v.i64[0] : INT64_MAX;
        f->end_us = v.set[1] ? v.i64[1] : INT64_MAX;
        f->dur_us = v.set[4] ? v.i64[4] : INT64_MAX;
        f->start_sample = v.set[5] ? v.i64[5] : -1;
        f->end_sample = v.set[6] ? v.i64[6] : -1;
    } else if (!strcmp(name, "apad")) {
        f->type = F_APAD;
        r = fopts_parse(name, idx, apad_opts, apad_sh, args, &v, mode);
        f->packet_size = v.set[0] ? (int)v.i64[0] : 4096;
        f->pad_len = v.set[1] ? v.i64[1] : -1;
        f->whole_len = v.set[2] ? v.i64[2] : -1;
        f->pad_dur_us = v.set[3] ? v.i64[3] : -1;
        f->whole_dur_us = v.set[4] ? v.i64[4] : -1;
    } else if (!strcmp(name, "aformat")) {
        f->type = F_AFORMAT;
        r = fopts_parse(name, idx, aformat_opts, aformat_sh, args, &v, mode);
        if (r >= 0) {
            char tmp[512], *save, *tok;
            if (v.set[0]) {
                snprintf(tmp, sizeof(tmp), "%s", v.s[0]);
                for (tok = strtok_r(tmp, "|", &save); tok; tok = strtok_r(NULL, "|", &save)) {
                    int sf = sf_from_name(tok);
                    if (sf < 0) { r = AVERROR(22); break; }
                    if (f->nb_fmts < 16) f->fmts[f->nb_fmts++] = sf;
                }
            }
            if (v.set[1]) {
                snprintf(tmp, sizeof(tmp), "%s", v.s[1]);
                for (tok = strtok_r(tmp, "|", &save); tok; tok = strtok_r(NULL, "|", &save))
                    if (f->nb_rates < 16) f->rates[f->nb_rates++] = atoi(tok);
            }
            if (v.set[2]) {
                snprintf(tmp, sizeof(tmp), "%s", v.s[2]);
                for (tok = strtok_r(tmp, "|", &save); tok; tok = strtok_r(NULL, "|", &save)) {
                    ChLayout l;
                    if (chl_from_string(&l, tok) < 0) { r = AVERROR(22); break; }
                    if (f->nb_layouts < 16) f->layouts[f->nb_layouts++] = l;
                }
            }
        }
    } else if (!strcmp(name, "afade")) {
        f->type = F_AFADE;
        r = fopts_parse(name, idx, afade_opts, afade_sh, args, &v, mode);
        f->fade_type = v.set[0] ? (int)v.i64[0] : 0;
        f->fade_start_sample = v.set[1] ? v.i64[1] : 0;
        f->fade_nb_samples = v.set[2] ? v.i64[2] : 44100;
        f->fade_st_us = v.set[3] ? v.i64[3] : 0;
        f->fade_d_us = v.set[4] ? v.i64[4] : 0;
        f->curve = v.set[5] ? (int)v.i64[5] : 0;
    } else if (!strcmp(name, "aresample")) {
        f->type = F_ARESAMPLE;
        r = fopts_parse(name, idx, aresample_opts, aresample_sh, args, &v, mode);
        f->rs_rate = v.set[0] ? (int)v.i64[0] : 0;
    } else {
        static const LogClass gcls = { "AVFilterGraph", NULL, NULL };
        struct { const LogClass *cls; } g = { &gcls };
        av_log(&g, AV_LOG_ERROR, "No such filter: '%s'\n", name);
        if (mode == 1) av_log(&g, AV_LOG_ERROR, "Error processing filtergraph: %s\n", av_err2str_buf(AVERROR_FILTER_NOT_FOUND));
        free(f);
        *err = AVERROR_FILTER_NOT_FOUND;
        return NULL;
    }
    if (r < 0) { *err = r; if (!f->volume_err) { free(f); return NULL; } }
    return f;
}

