int filterchain_parse(FilterChain *fc, const char *desc, void *logctx)
{
    char *dup = av_strdup(desc);
    char *names[64], *argsv[64];
    int n = 0;
    char *p = dup;
    static const LogClass gcls = { "AVFilterGraph", NULL, NULL };
    struct { const LogClass *cls; } g = { &gcls };
    (void)logctx;
    while (p && *p && n < 64) {
        char *start = p;
        int q = 0;
        while (*p && (q || *p != ',')) {
            if (*p == '\'') q = !q;
            if (*p == '\\' && p[1]) p++;
            p++;
        }
        if (*p == ',') *p++ = 0;
        while (*start == ' ') start++;
        char *eq = strchr(start, '=');
        char *args = NULL;
        if (eq) { *eq = 0; args = eq + 1; }
        names[n] = start;
        argsv[n] = args;
        n++;
    }
    /* pass 1: syntax */
    for (int i = 0; i < n; i++) {
        if (!known_filter(names[i]) && argsv[i] && *argsv[i]) {
            const char *a = argsv[i];
            const char *colon = strchr(a, ':');
            const char *eq = strchr(a, '=');
            if (!eq || (colon && colon < eq)) {
                av_log(&g, AV_LOG_ERROR, "No option name near '%s'\n", a);
                av_log(&g, AV_LOG_ERROR, "Error parsing a filter description around: \n");
                if (fc->mode == 1) {
                    /* full chain including the source */
                    av_log(&g, AV_LOG_ERROR, "Error parsing filterchain '%s' around: \n", fc->full_desc ? fc->full_desc : desc);
                    av_log(&g, AV_LOG_ERROR, "Error processing filtergraph: %s\n", av_err2str_buf(AVERROR(22)));
                } else
                    av_log(&g, AV_LOG_ERROR, "Error parsing filterchain '%s' around: \n", desc);
                free(dup);
                return AVERROR(22);
            }
        }
    }
    /* pass 2: existence */
    for (int i = 0; i < n; i++) {
        if (!known_filter(names[i])) {
            av_log(&g, AV_LOG_ERROR, "No such filter: '%s'\n", names[i]);
            if (fc->mode == 1) av_log(&g, AV_LOG_ERROR, "Error processing filtergraph: %s\n", av_err2str_buf(AVERROR_FILTER_NOT_FOUND));
            free(dup);
            return AVERROR_FILTER_NOT_FOUND;
        }
    }
    /* pass 3: options */
    for (int i = 0; i < n; i++) {
