/* Ogg container (FLAC mapping) */
#include "format.h"
#include "flacdec.h"
#include <fcntl.h>
#include <unistd.h>
#include <sys/time.h>

#define MAX_PAGE_SIZE 65025

typedef struct OggPage {
    int64_t start_granule;
    int64_t granule;
    int flags;
    uint8_t segments[255];
    int segments_count;
    uint8_t data[MAX_PAGE_SIZE];
    int size;
} OggPage;

typedef struct OggPageList { OggPage page; struct OggPageList *next; } OggPageList;

typedef struct OggMux {
    OggPage page;
    uint32_t serial;
    uint32_t page_counter;
    int page_count;
    int64_t last_granule;
    uint8_t *header[2];
    int header_len[2];
    OggPageList *list;
    int64_t pref_size, pref_duration;
    Rational tb;
} OggMux;

static const FmtOpt ogg_mux_opts[] = {
    { "serial_offset", 0, "0", 0, INT_MAX },
    { "oggpagesize", 0, "0", 0, 65025 },
    { "pagesize", 0, "0", 0, 65025 },
    { "page_duration", 4, "1000000", 0, (double)INT64_MAX },
    { NULL }
};

static int ogg_init(FormatContext *s)
{
    if (s->nb_streams != 1 || s->streams[0]->par.codec_id != CID_FLAC) {
        const CodecDesc *d = codec_desc(s->streams[0]->par.codec_id);
        av_log(s->log_ctx, AV_LOG_ERROR, "Unsupported codec id in stream %d\n", 0);
        (void)d;
        return AVERROR(22);
    }
    OggMux *o = calloc(1, sizeof(*o));
    s->priv = o;
    Stream *st = s->streams[0];
    st->time_base = (Rational){ 1, st->par.sample_rate };
    o->tb = st->time_base;
    int64_t serial_offset = fmt_opt_int(s, ogg_mux_opts, "serial_offset");
    if (s->bitexact) o->serial = (uint32_t)serial_offset;
    else {
        uint32_t seed = 0;
        int fd = open("/dev/urandom", O_RDONLY);
        if (fd >= 0) { if (read(fd, &seed, 4) != 4) seed = 0; close(fd); }
        if (!seed) { struct timeval tv; gettimeofday(&tv, NULL); seed = (uint32_t)(tv.tv_sec ^ tv.tv_usec); }
        o->serial = seed;
    }
    o->pref_size = fmt_opt_int(s, ogg_mux_opts, "oggpagesize");
    if (!o->pref_size) o->pref_size = fmt_opt_int(s, ogg_mux_opts, "pagesize");
    o->pref_duration = fmt_opt_int(s, ogg_mux_opts, "page_duration");
    o->page.granule = -1;
    return 0;
}

static void vc_conv(Dict *m)
{
    static const char *conv[][2] = { { "ALBUMARTIST", "album_artist" }, { "TRACKNUMBER", "track" },
                                     { "DISCNUMBER", "disc" }, { "DESCRIPTION", "comment" } };
    Dict out = { 0 };
    for (int i = 0; i < m->count; i++) {
        const char *k = m->e[i].key;
        for (int j = 0; j < 4; j++)
            if (!strcasecmp(k, conv[j][1])) { k = conv[j][0]; break; }
        dict_set(&out, k, m->e[i].value);
    }
    dict_free(m);
    *m = out;
}

static void put_le32(uint8_t **p, uint32_t v) { (*p)[0] = v; (*p)[1] = v >> 8; (*p)[2] = v >> 16; (*p)[3] = v >> 24; *p += 4; }

static void ogg_buffer_page(OggMux *o)
{
    OggPageList *l = calloc(1, sizeof(*l));
    l->page = o->page;
    o->page.start_granule = o->page.granule;
    o->page_count++;
    OggPageList **p = &o->list;
    while (*p) p = &(*p)->next;
    *p = l;
    o->page.segments_count = 0;
    o->page.size = 0;
    o->page.flags = 0;
}

static void ogg_buffer_data(OggMux *o, const uint8_t *data, int size, int64_t granule, int header)
{
    int total_segments = size / 255 + 1;
    const uint8_t *p = data;
    int i, segments, len;
    if (!header && o->page.size > 0 && MAX_PAGE_SIZE - o->page.size < size)
        ogg_buffer_page(o);
    for (i = 0; i < total_segments; ) {
        OggPage *page = &o->page;
        segments = FFMIN(total_segments - i, 255 - page->segments_count);
        if (i && !page->segments_count) page->flags |= 1;
        memset(page->segments + page->segments_count, 255, segments - 1);
        page->segments_count += segments - 1;
        len = FFMIN(size, segments * 255);
        page->segments[page->segments_count++] = len - (segments - 1) * 255;
        if (len) memcpy(page->data + page->size, p, len);
        p += len;
        size -= len;
        i += segments;
        page->size += len;
        if (i == total_segments) page->granule = granule;
        int64_t start = av_rescale_q(page->start_granule, o->tb, (Rational){ 1, AV_TIME_BASE });
        int64_t next = av_rescale_q(page->granule, o->tb, (Rational){ 1, AV_TIME_BASE });
        if (page->segments_count == 255) {
            ogg_buffer_page(o);
        } else if (!header) {
            if ((o->pref_size > 0 && page->size >= o->pref_size) ||
                (o->pref_duration > 0 && next - start >= o->pref_duration))
                ogg_buffer_page(o);
        }
    }
}

static void ogg_write_page(FormatContext *s, OggPage *page, int extra_flags)
{
    OggMux *o = s->priv;
    uint8_t buf[27 + 255], *ptr = buf, *crc_pos;
    memcpy(ptr, "OggS", 4); ptr += 4;
    *ptr++ = 0;
    *ptr++ = page->flags | extra_flags;
    for (int i = 0; i < 8; i++) *ptr++ = (uint8_t)((uint64_t)page->granule >> (8 * i));
    put_le32(&ptr, o->serial);
    put_le32(&ptr, o->page_counter++);
    crc_pos = ptr;
    put_le32(&ptr, 0);
    *ptr++ = page->segments_count;
    memcpy(ptr, page->segments, page->segments_count);
    ptr += page->segments_count;
    uint32_t crc = crc32_ieee(0, buf, ptr - buf);
    crc = crc32_ieee(crc, page->data, page->size);
    put_le32(&crc_pos, crc);
    avio_write(s->pb, buf, (int)(ptr - buf));
    avio_write(s->pb, page->data, page->size);
}

static void ogg_write_pages(FormatContext *s, int flush)
{
    OggMux *o = s->priv;
    OggPageList *p = o->list, *next;
    while (p) {
        if (o->page_count < 2 && !flush) break;
        ogg_write_page(s, &p->page, flush == 1 && o->page_count == 1 ? 4 : 0);
        o->page_count--;
        next = p->next;
        free(p);
        p = next;
    }
    o->list = p;
}

static int ogg_write_header(FormatContext *s)
{
    OggMux *o = s->priv;
    Stream *st = s->streams[0];
    if (!st->par.extradata || st->par.extradata_size < 34) return AVERROR(22);
    o->header_len[0] = 51;
    o->header[0] = calloc(1, 51);
    uint8_t *p = o->header[0];
    *p++ = 0x7F; memcpy(p, "FLAC", 4); p += 4;
    *p++ = 1; *p++ = 0;
    *p++ = 0; *p++ = 1;
    memcpy(p, "fLaC", 4); p += 4;
    *p++ = 0; *p++ = 0; *p++ = 0; *p++ = 34;
    memcpy(p, st->par.extradata, 34);
    /* vorbis comment from stream metadata */
    const char *vendor = s->bitexact ? "ffmpeg" : LIBAVFORMAT_IDENT;
    vc_conv(&st->metadata);
    int len = 4 + 4 + (int)strlen(vendor) + 4;
    for (int i = 0; i < st->metadata.count; i++)
        len += 4 + (int)strlen(st->metadata.e[i].key) + 1 + (int)strlen(st->metadata.e[i].value);
    o->header_len[1] = len;
    o->header[1] = calloc(1, len);
    p = o->header[1];
    *p++ = 0x84;
    *p++ = (uint8_t)((len - 4) >> 16); *p++ = (uint8_t)((len - 4) >> 8); *p++ = (uint8_t)(len - 4);
    put_le32(&p, (uint32_t)strlen(vendor)); memcpy(p, vendor, strlen(vendor)); p += strlen(vendor);
    put_le32(&p, st->metadata.count);
    for (int i = 0; i < st->metadata.count; i++) {
        size_t l1 = strlen(st->metadata.e[i].key), l2 = strlen(st->metadata.e[i].value);
        put_le32(&p, (uint32_t)(l1 + 1 + l2));
        memcpy(p, st->metadata.e[i].key, l1); p += l1;
        *p++ = '=';
        memcpy(p, st->metadata.e[i].value, l2); p += l2;
    }
    ogg_buffer_data(o, o->header[0], o->header_len[0], 0, 1);
    o->page.flags |= 2;
    ogg_buffer_page(o);
    ogg_buffer_data(o, o->header[1], o->header_len[1], 0, 1);
    ogg_buffer_page(o);
    o->page.start_granule = 0;
    ogg_write_pages(s, 2);
    return 0;
}

static int ogg_write_packet(FormatContext *s, Packet *pkt)
{
    OggMux *o = s->priv;
    if (!pkt->size && pkt->new_extradata) return 0;
    int64_t granule = pkt->pts + pkt->duration;
    o->last_granule = granule;
    ogg_buffer_data(o, pkt->data, pkt->size, granule, 0);
    ogg_write_pages(s, 0);
    return 0;
}

static int ogg_write_trailer(FormatContext *s)
{
    OggMux *o = s->priv;
    if (o->page.size > 0) ogg_buffer_page(o);
    ogg_write_pages(s, 1);
    return 0;
}

static void ogg_deinit(FormatContext *s)
{
    OggMux *o = s->priv;
    if (!o) return;
    free(o->header[0]);
    free(o->header[1]);
    while (o->list) { OggPageList *n = o->list->next; free(o->list); o->list = n; }
    free(o);
    s->priv = NULL;
}

const OutputFormat ff_ogg_muxer = {
    "ogg", "Ogg", "application/ogg", "ogg", CID_FLAC, CID_NONE, 0,
    ogg_init, ogg_write_header, ogg_write_packet, ogg_write_trailer, ogg_deinit, ogg_mux_opts, 0
};
const OutputFormat ff_oga_muxer = {
    "oga", "Ogg Audio", "audio/ogg", "oga", CID_FLAC, CID_NONE, 0,
    ogg_init, ogg_write_header, ogg_write_packet, ogg_write_trailer, ogg_deinit, ogg_mux_opts, 0
};

/* ---------------- demuxer ---------------- */
typedef struct OggDemux {
    uint8_t *data;
    int64_t size;
    int64_t pos;
    /* packets */
    uint8_t *pkt;
    int pkt_len, pkt_cap;
    int nheaders;
    int64_t next_pts;
    FlacStreamInfo si;
    int64_t page_granule;
} OggDemux;

static int ogg_probe(const uint8_t *p, int size)
{
    if (size >= 4 && !memcmp(p, "OggS", 4)) return 100;
    return 0;
}

/* reads the next complete packet; returns 0 or AVERROR_EOF */
static int ogg_next_packet(OggDemux *d, uint8_t **out, int *out_len, int64_t *granule, int *last_on_page)
{
    static int seg_idx, nsegs;
    static const uint8_t *segtab;
    static const uint8_t *pdata;
    static int64_t cur_gran;
    d->pkt_len = 0;
    for (;;) {
        if (seg_idx >= nsegs) {
            /* next page */
            if (d->pos + 27 > d->size) return AVERROR_EOF;
            if (memcmp(d->data + d->pos, "OggS", 4)) {
                /* resync */
                int64_t k;
                for (k = d->pos + 1; k + 4 <= d->size; k++) if (!memcmp(d->data + k, "OggS", 4)) break;
                if (k + 4 > d->size) return AVERROR_EOF;
                d->pos = k;
                continue;
            }
            const uint8_t *h = d->data + d->pos;
            nsegs = h[26];
            if (d->pos + 27 + nsegs > d->size) return AVERROR_EOF;
            segtab = h + 27;
            int total = 0;
            for (int i = 0; i < nsegs; i++) total += segtab[i];
            if (d->pos + 27 + nsegs + total > d->size) return AVERROR_EOF;
            cur_gran = 0;
            for (int i = 7; i >= 0; i--) cur_gran = (cur_gran << 8) | h[6 + i];
            pdata = h + 27 + nsegs;
            d->pos += 27 + nsegs + total;
            seg_idx = 0;
            if (!nsegs) continue;
        }
        int l = segtab[seg_idx++];
        if (d->pkt_len + l > d->pkt_cap) { d->pkt_cap = (d->pkt_len + l) * 2 + 1024; d->pkt = realloc(d->pkt, d->pkt_cap); }
        memcpy(d->pkt + d->pkt_len, pdata, l);
        pdata += l;
        d->pkt_len += l;
        if (l < 255) {
            *out = d->pkt;
            *out_len = d->pkt_len;
            *granule = cur_gran;
            *last_on_page = seg_idx >= nsegs;
            return 0;
        }
    }
}

static void parse_vc(FormatContext *s, Dict *m, const uint8_t *p, int len)
{
    const uint8_t *end = p + len;
    (void)s;
    if (end - p < 4) return;
    uint32_t vl = p[0] | (p[1] << 8) | (p[2] << 16) | ((uint32_t)p[3] << 24);
    p += 4;
    if (vl > (uint32_t)(end - p)) return;
    p += vl;
    if (end - p < 4) return;
    uint32_t n = p[0] | (p[1] << 8) | (p[2] << 16) | ((uint32_t)p[3] << 24);
    p += 4;
    for (uint32_t i = 0; i < n && end - p >= 4; i++) {
        uint32_t l = p[0] | (p[1] << 8) | (p[2] << 16) | ((uint32_t)p[3] << 24);
        p += 4;
        if (l > (uint32_t)(end - p)) break;
        char *kv = calloc(1, l + 1);
        memcpy(kv, p, l);
        p += l;
        char *eq = strchr(kv, '=');
        if (eq && eq != kv) {
            *eq = 0;
            const char *k = kv;
            if (!strcasecmp(k, "TRACKNUMBER")) k = "track";
            else if (!strcasecmp(k, "DISCNUMBER")) k = "disc";
            else if (!strcasecmp(k, "DESCRIPTION")) k = "comment";
            else if (!strcasecmp(k, "ALBUMARTIST")) k = "album_artist";
            dict_set(m, k, eq + 1);
        }
        free(kv);
    }
}

static int ogg_read_header(FormatContext *s)
{
    OggDemux *d = calloc(1, sizeof(*d));
    s->priv = d;
    int64_t cap = 65536, len = 0;
    d->data = malloc(cap);
    for (;;) {
        if (len + 65536 > cap) { cap *= 2; d->data = realloc(d->data, cap); }
        int r = avio_read(s->pb, d->data + len, 65536);
        if (r <= 0) break;
        len += r;
    }
    d->size = len;
    uint8_t *pk; int pl; int64_t g; int last;
    if (ogg_next_packet(d, &pk, &pl, &g, &last) < 0) return AVERROR_INVALIDDATA;
    if (pl < 51 || pk[0] != 0x7F || memcmp(pk + 1, "FLAC", 4)) return AVERROR_INVALIDDATA;
    Stream *st = format_new_stream(s);
    st->par.codec_type = MT_AUDIO;
    st->par.codec_id = CID_FLAC;
    st->par.extradata = malloc(34 + 64);
    memcpy(st->par.extradata, pk + 17, 34);
    memset(st->par.extradata + 34, 0, 64);
    st->par.extradata_size = 34;
    flac_parse_streaminfo(&d->si, st->par.extradata);
    st->par.sample_rate = d->si.samplerate;
    {
        static const uint64_t flac_layouts[8] = { 0x4, 0x3, 0x7, 0x33, 0x607, 0x60f, 0x70f, 0x63f };
        st->par.ch_layout.order = 1;
        st->par.ch_layout.nb_channels = d->si.channels;
        st->par.ch_layout.mask = flac_layouts[(d->si.channels - 1) & 7];
    }
    st->par.bits_per_raw_sample = d->si.bps;
    st->par.format = d->si.bps > 16 ? SF_S32 : SF_S16;
    st->time_base = (Rational){ 1, d->si.samplerate ? d->si.samplerate : 1 };
    int nh = (pk[7] << 8) | pk[8];
    for (int i = 0; i < nh; i++) {
        if (ogg_next_packet(d, &pk, &pl, &g, &last) < 0) break;
        if (pl >= 4 && (pk[0] & 0x7f) == 4)
            parse_vc(s, &st->metadata, pk + 4, pl - 4);
    }
    {
        const char *cm = dict_get(&st->metadata, "WAVEFORMATEXTENSIBLE_CHANNEL_MASK");
        if (cm) {
            uint64_t m = strtoull(cm, NULL, 0);
