            int64_t gg = 0;
            for (int i = 7; i >= 0; i--) gg = (gg << 8) | d->data[k + 6 + i];
            lastg = gg;
            break;
        }
    }
    if (lastg > 0 && s->pb->seekable) st->duration = lastg;
    st->start_time = 0;
    d->next_pts = 0;
    return 0;
}

static int ogg_read_packet(FormatContext *s, Packet *pkt)
{
    OggDemux *d = s->priv;
    uint8_t *pk; int pl; int64_t g; int last;
    for (;;) {
        int r = ogg_next_packet(d, &pk, &pl, &g, &last);
        if (r < 0) return r;
        if (!pl) continue;
        FlacFrameInfo fi;
        int dur = 0;
        if (flac_parse_frame_header(pk, pl, &fi) > 0) dur = fi.blocksize;
        pkt->data = malloc(pl + 64);
        memcpy(pkt->data, pk, pl);
        memset(pkt->data + pl, 0, 64);
        pkt->size = pl;
        pkt->pts = pkt->dts = d->next_pts;
        pkt->duration = dur;
        pkt->flags = PKT_FLAG_KEY;
        pkt->stream_index = 0;
        d->next_pts += dur;
        return 0;
    }
}

static void ogg_close(FormatContext *s)
{
    OggDemux *d = s->priv;
    if (!d) return;
    free(d->data);
    free(d->pkt);
    free(d);
    s->priv = NULL;
}

