new=r'''/* frame table used to emulate the reference binary-search seeking behaviour */
typedef struct FlacFrameEnt { int64_t pos; int64_t ts; } FlacFrameEnt;

static int flac_build_frames(FlacDemux *f, int64_t data_offset, FlacFrameEnt **out)
{
    int n = 0, cap = 64;
    FlacFrameEnt *e = malloc(sizeof(*e) * cap);
    int64_t q = data_offset;
    while (q < f->size) {
        FlacFrameInfo fi;
        int r = flac_decode_frame(f->data + q, (int)(f->size - q), &f->si, &fi, NULL);
        if (r < -1) r = -2 - r;
        if (r <= 0) break;
        if (n == cap) { cap *= 2; e = realloc(e, sizeof(*e) * cap); }
        e[n].pos = q;
        e[n].ts = fi.blocking_strategy ? fi.frame_or_sample_num : fi.frame_or_sample_num * fi.blocksize;
        n++;
        q += r;
    }
    *out = e;
    return n;
}

static int64_t flac_emu_read_ts(FlacFrameEnt *e, int n, int64_t *ppos)
{
    int i = 0;
    while (i < n && e[i].pos < *ppos) i++;
    int avail = n - i;
    if (avail >= 10) { *ppos = e[i].pos; return e[i].ts; }
    if (avail >= 3) { *ppos = e[i + 1].pos; return e[i + 1].ts; }
    return AV_NOPTS_VALUE;
}

static int flac_read_seek(FormatContext *s, int64_t ts_us)
{
    FlacDemux *f = s->priv;
    Stream *st = s->streams[0];
    int64_t target = av_rescale(ts_us, st->time_base.den, AV_TIME_BASE * (int64_t)st->time_base.num);
    FlacFrameEnt *e;
    int n = flac_build_frames(f, s->data_offset, &e);
    int64_t filesize = f->size;
    int64_t pos_min, pos_max, pos_limit, ts_min, ts_max, pos, ts, start_pos;
    int no_change;
    int ret = -1;
    if (n <= 0) goto fail;
    /* index contains the first frame only */
    pos_min = e[0].pos;
    ts_min = e[0].ts;
    if (ts_min >= target) { pos = pos_min; goto done; }
    /* find last ts */
    {
        int64_t step = 1024, limit;
        int64_t pm = filesize - 1;
        int64_t tm;
        do {
            limit = pm;
            pm = FFMAX(0, pm - step);
            int64_t pp = pm;
            tm = flac_emu_read_ts(e, n, &pp);
            if (tm != AV_NOPTS_VALUE) pm = pp;
            step += step;
        } while (tm == AV_NOPTS_VALUE && 2 * limit > step);
        if (tm == AV_NOPTS_VALUE) goto fail;
        for (;;) {
            int64_t tmp_pos = pm + 1;
            int64_t tmp_ts = flac_emu_read_ts(e, n, &tmp_pos);
            if (tmp_ts == AV_NOPTS_VALUE) break;
            tm = tmp_ts;
            pm = tmp_pos;
            if (tmp_pos >= filesize) break;
        }
        ts_max = tm;
        pos_max = pm;
        pos_limit = pos_max;
    }
    if (ts_max <= target) { pos = pos_max; goto done; }
    no_change = 0;
    while (pos_min < pos_limit) {
        if (no_change == 0) {
            int64_t akd = pos_max - pos_limit;
            pos = av_rescale(target - ts_min, pos_max - pos_min, ts_max - ts_min) + pos_min - akd;
        } else if (no_change == 1) {
            pos = (pos_min + pos_limit) >> 1;
        } else {
            pos = pos_min;
        }
        if (pos <= pos_min) pos = pos_min + 1;
        else if (pos > pos_limit) pos = pos_limit;
        start_pos = pos;
        ts = flac_emu_read_ts(e, n, &pos);
        if (pos == pos_max) no_change++;
        else no_change = 0;
        if (ts == AV_NOPTS_VALUE) goto fail;
        if (target <= ts) {
            pos_limit = start_pos - 1;
            pos_max = pos;
            ts_max = ts;
        }
        if (target >= ts) {
            pos_min = pos;
            ts_min = ts;
        }
    }
    pos = pos_min;
done:
    f->pos = pos;
    ret = 0;
    free(e);
    return ret;
fail:
    free(e);
    f->pos = f->size; /* reading position is left at the end */
    return -1;
}

