static int ffmeta_probe(const uint8_t *p, int size)
{
    if (size >= 11 && !memcmp(p, ";FFMETADATA", 11)) return 100;
    return 0;
}

static char *unescape_until(const char **pp, char stop)
{
    const char *p = *pp;
    size_t cap = strlen(p) + 1, n = 0;
    char *out = malloc(cap);
    while (*p && *p != '\\n' && (!stop || *p != stop)) {
        if (*p == '\\\\' && p[1]) p++;
        out[n++] = *p++;
    }
    out[n] = 0;
    *pp = p;
    return out;
}

static int ffmeta_read_header(FormatContext *s)
{
    uint8_t *data; int64_t size;
    read_all(s->pb, &data, &size);
    char *text = malloc(size + 1);
    memcpy(text, data, size);
    text[size] = 0;
    free(data);
    const char *p = text;
    Dict *m = &s->metadata;
    int first = 1;
    while (*p) {
        const char *ls = p;
        if (first) { first = 0; while (*p && *p != '\\n') p++; if (*p) p++; continue; }
        if (*ls == ';' || *ls == '#' || *ls == '\\n' || *ls == '\\r') {
            while (*p && *p != '\\n') p++;
            if (*p) p++;
            continue;
        }
        if (!strncmp(ls, "[STREAM]", 8)) {
            Stream *st = format_new_stream(s);
            st->par.codec_type = MT_DATA;
            st->par.codec_id = CID_NONE;
            st->time_base = (Rational){ 1, 1000 };
            st->start_time = 0;
            m = &st->metadata;
            while (*p && *p != '\\n') p++;
            if (*p) p++;
            continue;
        }
        if (!strncmp(ls, "[CHAPTER]", 9)) {
            static Dict dummy;
            m = &dummy;
            while (*p && *p != '\\n') p++;
            if (*p) p++;
            continue;
        }
        char *key = unescape_until(&p, '=');
        if (*p == '=') {
            p++;
            char *val = unescape_until(&p, 0);
            if (*key) dict_set(m, key, val);
            free(val);
        }
        free(key);
        while (*p && *p != '\\n') p++;
        if (*p) p++;
    }
    free(text);
    return 0;
}

