/* AIFF and Sun AU containers */
#include "format.h"

static uint32_t mktag(const char *t) { return (uint8_t)t[0] | ((uint8_t)t[1] << 8) | ((uint8_t)t[2] << 16) | ((uint32_t)(uint8_t)t[3] << 24); }

/* ------------------------------------------------------------------ */
/* AIFF muxer                                                          */
typedef struct AiffMux { int64_t form, frames, ssnd; } AiffMux;

static uint32_t aiff_tag(int id)
{
    switch (id) {
    case CID_PCM_S16BE: case CID_PCM_S8: case CID_PCM_S24BE: case CID_PCM_S32BE: return mktag("NONE");
    case CID_PCM_U8: return mktag("raw ");
    case CID_PCM_F32BE: return mktag("fl32");
    case CID_PCM_F64BE: return mktag("fl64");
    case CID_PCM_ALAW: return mktag("alaw");
    case CID_PCM_MULAW: return mktag("ulaw");
    case CID_PCM_S16LE: return mktag("sowt");
    }
    return 0;
}

static int aiff_init(FormatContext *s)
{
    if (s->nb_streams != 1 || s->streams[0]->par.codec_type != MT_AUDIO) {
        av_log(s->log_ctx, AV_LOG_ERROR, "AIFF allows only one audio stream and a picture.\n");
        return AVERROR(22);
    }
    Stream *st = s->streams[0];
    st->par.codec_tag = aiff_tag(st->par.codec_id);
    if (!st->par.codec_tag) {
        const CodecDesc *d = codec_desc(st->par.codec_id);
        av_log(s->log_ctx, AV_LOG_ERROR, "Tag %s incompatible with output codec id '%d' ([0][0][0][0])\n", "[0][0][0][0]", d ? d->id : 0);
        return AVERROR(22);
    }
    st->time_base = (Rational){ 1, st->par.sample_rate };
    s->priv = calloc(1, sizeof(AiffMux));
    return 0;
}

static void aiff_put_meta(FormatContext *s, const char *key, const char *id)
{
    const char *v = dict_get(&s->metadata, key);
    if (!v) return;
    size_t size = strlen(v);
    avio_write(s->pb, (const uint8_t *)id, 4);
    avio_wb32(s->pb, (unsigned)((size + 1) & ~1));
    avio_write(s->pb, (const uint8_t *)v, (int)size);
    if (size & 1) avio_w8(s->pb, 0);
}

static int aiff_write_header(FormatContext *s)
{
    AiffMux *a = s->priv;
    AVIO *pb = s->pb;
    CodecPar *par = &s->streams[0]->par;
    int aifc = par->codec_tag != mktag("NONE");
    avio_write(pb, (const uint8_t *)"FORM", 4);
    a->form = avio_wtell(pb);
    avio_wb32(pb, 0);
    avio_write(pb, (const uint8_t *)(aifc ? "AIFC" : "AIFF"), 4);
    if (aifc) {
        avio_write(pb, (const uint8_t *)"FVER", 4);
        avio_wb32(pb, 4);
        avio_wb32(pb, 0xA2805140);
    }
    aiff_put_meta(s, "title", "NAME");
    aiff_put_meta(s, "author", "AUTH");
    aiff_put_meta(s, "copyright", "(c) ");
    aiff_put_meta(s, "comment", "ANNO");
    avio_write(pb, (const uint8_t *)"COMM", 4);
    avio_wb32(pb, aifc ? 24 : 18);
    avio_wb16(pb, par->ch_layout.nb_channels);
    a->frames = avio_wtell(pb);
    avio_wb32(pb, 0);
    int bps = par->bits_per_coded_sample ? par->bits_per_coded_sample : get_bits_per_sample(par->codec_id);
    if (!par->block_align) par->block_align = (bps * par->ch_layout.nb_channels) >> 3;
    avio_wb16(pb, bps);
    double sr = par->sample_rate;
    uint64_t bits;
    memcpy(&bits, &sr, 8);
    avio_wb16(pb, (unsigned)((bits >> 52) + (16383 - 1023)));
    avio_wb64(pb, (UINT64_C(1) << 63) | (bits << 11));
    if (aifc) {
        avio_wl32(pb, par->codec_tag);
        avio_wb16(pb, 0);
    }
    avio_write(pb, (const uint8_t *)"SSND", 4);
    a->ssnd = avio_wtell(pb);
    avio_wb32(pb, 0);
    avio_wb32(pb, 0);
    avio_wb32(pb, 0);
    return 0;
}

static int aiff_write_packet(FormatContext *s, Packet *pkt)
{
    avio_write(s->pb, pkt->data, pkt->size);
    return 0;
}

static int aiff_write_trailer(FormatContext *s)
{
    AiffMux *a = s->priv;
    AVIO *pb = s->pb;
    CodecPar *par = &s->streams[0]->par;
    int64_t data_size = avio_wtell(pb);
    if (data_size & 1) avio_w8(pb, 0);
    if (pb->seekable) {
        int64_t file_size = avio_wtell(pb);
        avio_wseek(pb, a->form);
        avio_wb32(pb, (uint32_t)(file_size - a->form - 4));
        avio_wseek(pb, a->frames);
        avio_wb32(pb, (uint32_t)((data_size - a->ssnd - 12) / par->block_align));
        avio_wseek(pb, a->ssnd);
        avio_wb32(pb, (uint32_t)(data_size - a->ssnd - 4));
        avio_wseek(pb, file_size);
    }
    return 0;
}

static void aiff_deinit(FormatContext *s) { free(s->priv); s->priv = NULL; }

static const FmtOpt aiff_mux_opts[] = {
    { "write_id3v2", 2, "false", 0, 1, NULL },
    { "id3v2_version", 0, "4", 3, 4, NULL },
    { NULL }
};

const OutputFormat ff_aiff_muxer = {
    "aiff", "Audio IFF", "audio/aiff", "aif,aiff,afc,aifc", CID_PCM_S16BE, CID_PNG, 0,
    aiff_init, aiff_write_header, aiff_write_packet, aiff_write_trailer, aiff_deinit, aiff_mux_opts, 0
};

/* ------------------------------------------------------------------ */
/* AIFF demuxer                                                        */
typedef struct AiffDemux { int64_t data_end; } AiffDemux;

static int aiff_probe(const uint8_t *p, int size)
{
    if (size >= 12 && !memcmp(p, "FORM", 4) && (!memcmp(p + 8, "AIFF", 4) || !memcmp(p + 8, "AIFC", 4)))
        return 100;
    return 0;
}

static int aiff_read_header(FormatContext *s)
{
    AVIO *pb = s->pb;
    AiffDemux *a = calloc(1, sizeof(*a));
    s->priv = a;
    uint8_t tag[4];
    avio_read(pb, tag, 4);
    avio_rb32(pb);
    avio_read(pb, tag, 4);
    int aifc = !memcmp(tag, "AIFC", 4);
    Stream *st = NULL;
    int got_ssnd = 0;
    uint32_t nframes = 0;
    int bps = 0;
    while (!got_ssnd) {
        if (avio_read(pb, tag, 4) != 4) break;
        uint32_t size = avio_rb32(pb);
        int64_t start = avio_tell(pb);
        int64_t next = start + size + (size & 1);
        if (!memcmp(tag, "COMM", 4)) {
            st = format_new_stream(s);
            st->par.codec_type = MT_AUDIO;
            int ch = avio_rb16(pb);
            nframes = avio_rb32(pb);
            bps = avio_rb16(pb);
            int exp = avio_rb16(pb);
            uint64_t val = avio_rb64(pb);
            int sign = exp & 0x8000;
            exp &= 0x7fff;
            double sr = ldexp((double)val, exp - 16383 - 63);
            if (sign) sr = -sr;
            st->par.sample_rate = (int)sr;
            st->par.ch_layout.order = 0;
            st->par.ch_layout.nb_channels = ch;
            st->par.bits_per_coded_sample = bps;
            int id = CID_NONE;
            if (aifc && size >= 22) {
                uint8_t ct[4];
                avio_read(pb, ct, 4);
                if (!memcmp(ct, "NONE", 4) || !memcmp(ct, "twos", 4)) id = CID_NONE;
                else if (!memcmp(ct, "sowt", 4)) id = CID_PCM_S16LE;
                else if (!memcmp(ct, "fl32", 4) || !memcmp(ct, "FL32", 4)) id = CID_PCM_F32BE;
                else if (!memcmp(ct, "fl64", 4) || !memcmp(ct, "FL64", 4)) id = CID_PCM_F64BE;
                else if (!memcmp(ct, "alaw", 4) || !memcmp(ct, "ALAW", 4)) id = CID_PCM_ALAW;
                else if (!memcmp(ct, "ulaw", 4) || !memcmp(ct, "ULAW", 4)) id = CID_PCM_MULAW;
                else if (!memcmp(ct, "raw ", 4)) id = CID_PCM_U8;
                st->par.codec_tag = ct[0] | (ct[1] << 8) | (ct[2] << 16) | ((uint32_t)ct[3] << 24);
            }
            if (id == CID_NONE) {
                if (bps <= 8) id = CID_PCM_S8;
                else if (bps <= 16) id = CID_PCM_S16BE;
                else if (bps <= 24) id = CID_PCM_S24BE;
                else id = CID_PCM_S32BE;
            }
            st->par.codec_id = id;
            int ebps = get_bits_per_sample(id);
            st->par.block_align = ebps * ch / 8;
            st->par.bit_rate = (int64_t)ebps * ch * st->par.sample_rate;
            st->time_base = (Rational){ 1, st->par.sample_rate ? st->par.sample_rate : 1 };
            if (id == CID_PCM_S24BE || id == CID_PCM_S32BE) st->par.bits_per_raw_sample = ebps;
            avio_seek(pb, next);
        } else if (!memcmp(tag, "SSND", 4)) {
            uint32_t offset = avio_rb32(pb);
            avio_rb32(pb);
            avio_skip(pb, offset);
            s->data_offset = avio_tell(pb);
            a->data_end = start + size;
            got_ssnd = 1;
        } else if (!memcmp(tag, "NAME", 4) || !memcmp(tag, "AUTH", 4) || !memcmp(tag, "(c) ", 4) || !memcmp(tag, "ANNO", 4)) {
            char *v = calloc(1, size + 1);
            avio_read(pb, (uint8_t *)v, size);
            const char *k = !memcmp(tag, "NAME", 4) ? "title" : !memcmp(tag, "AUTH", 4) ? "author" : !memcmp(tag, "(c) ", 4) ? "copyright" : "comment";
            dict_set(&s->metadata, k, v);
            free(v);
            avio_seek(pb, next);
        } else {
            if (avio_seek(pb, next) < 0) break;
        }
    }
    if (!st || !got_ssnd) return AVERROR_INVALIDDATA;
    if (nframes) st->duration = nframes;
    st->start_time = 0;
    return 0;
}

static int aiff_read_packet(FormatContext *s, Packet *pkt)
{
    AiffDemux *a = s->priv;
    Stream *st = s->streams[0];
    int64_t pos = avio_tell(s->pb);
    int64_t left = a->data_end - pos;
    if (left <= 0) return AVERROR_EOF;
    int size = 1024 * st->par.block_align;
    if (size > left) size = (int)left;
    pkt->data = malloc(size + 64);
    int r = avio_read(s->pb, pkt->data, size);
    if (r <= 0) { free(pkt->data); pkt->data = NULL; return AVERROR_EOF; }
    r -= r % st->par.block_align;
    if (r <= 0) { free(pkt->data); pkt->data = NULL; return AVERROR_EOF; }
    memset(pkt->data + r, 0, 64);
    pkt->size = r;
    pkt->pos = pos;
    pkt->flags = PKT_FLAG_KEY;
    pkt->pts = pkt->dts = (pos - s->data_offset) / st->par.block_align;
    pkt->duration = r / st->par.block_align;
    return 0;
}

static int aiff_read_seek(FormatContext *s, int64_t ts_us)
{
    Stream *st = s->streams[0];
    int64_t sample = av_rescale_rnd(ts_us, st->par.sample_rate, AV_TIME_BASE, AV_ROUND_DOWN);
    if (sample < 0) sample = 0;
    return avio_seek(s->pb, s->data_offset + sample * st->par.block_align) < 0 ? -1 : 0;
}

static void aiff_close(FormatContext *s) { free(s->priv); s->priv = NULL; }

const InputFormat ff_aiff_demuxer = {
    "aiff", "Audio IFF", "aif,aiff,aifc", 0, aiff_probe, aiff_read_header, aiff_read_packet, aiff_read_seek, aiff_close, NULL
};

/* ------------------------------------------------------------------ */
/* AU                                                                  */
typedef struct AuMux { int header_size; } AuMux;

static uint32_t au_tag(int id)
{
    switch (id) {
    case CID_PCM_MULAW: return 1;
    case CID_PCM_S8: return 2;
    case CID_PCM_S16BE: return 3;
    case CID_PCM_S24BE: return 4;
    case CID_PCM_S32BE: return 5;
    case CID_PCM_F32BE: return 6;
    case CID_PCM_F64BE: return 7;
    case CID_PCM_ALAW: return 27;
    }
    return 0;
}

static int au_init(FormatContext *s)
{
    if (s->nb_streams != 1) {
        av_log(s->log_ctx, AV_LOG_ERROR, "only one stream is supported\n");
        return AVERROR(22);
    }
    Stream *st = s->streams[0];
    st->par.codec_tag = au_tag(st->par.codec_id);
    if (!st->par.codec_tag) {
        av_log(s->log_ctx, AV_LOG_ERROR, "unsupported codec\n");
        return AVERROR(22);
    }
    st->time_base = (Rational){ 1, st->par.sample_rate };
    s->priv = calloc(1, sizeof(AuMux));
    return 0;
}

static int au_write_header(FormatContext *s)
{
    AuMux *a = s->priv;
    AVIO *pb = s->pb;
    CodecPar *par = &s->streams[0]->par;
    char ann[4096];
    int len = 0;
    static const char *keys[] = { "Title", "Artist", "Album", "Track", "Genre" };
    for (int i = 0; i < 5; i++) {
        const char *v = dict_get(&s->metadata, keys[i]);
        if (v) {
            if (len) ann[len++] = '\n';
            len += snprintf(ann + len, sizeof(ann) - len, "%s=%s", keys[i], v);
        }
    }
    a->header_size = 24 + len + (8 - (len & 7));
    avio_write(pb, (const uint8_t *)".snd", 4);
    avio_wb32(pb, a->header_size);
    avio_wb32(pb, 0xFFFFFFFF);
    avio_wb32(pb, par->codec_tag);
    avio_wb32(pb, par->sample_rate);
    avio_wb32(pb, par->ch_layout.nb_channels);
    avio_write(pb, (const uint8_t *)ann, len);
    for (int i = 0; i < 8 - (len & 7); i++) avio_w8(pb, 0);
    return 0;
}

static int au_write_trailer(FormatContext *s)
{
    AuMux *a = s->priv;
    AVIO *pb = s->pb;
    int64_t file_size = avio_wtell(pb);
    if (pb->seekable && file_size < INT32_MAX) {
        avio_wseek(pb, 8);
        avio_wb32(pb, (uint32_t)(file_size - a->header_size));
        avio_wseek(pb, file_size);
    }
    return 0;
}

static void au_deinit(FormatContext *s) { free(s->priv); s->priv = NULL; }

const OutputFormat ff_au_muxer = {
    "au", "Sun AU", "audio/basic", "au", CID_PCM_S16BE, CID_NONE, 0,
    au_init, au_write_header, aiff_write_packet, au_write_trailer, au_deinit, NULL, 0
};

typedef struct AuDemux { int64_t data_end; } AuDemux;

static int au_probe(const uint8_t *p, int size)
{
    if (size >= 24 && !memcmp(p, ".snd", 4)) return 100;
    return 0;
}

static int au_read_header(FormatContext *s)
{
    AVIO *pb = s->pb;
    AuDemux *a = calloc(1, sizeof(*a));
    s->priv = a;
    uint8_t tag[4];
    avio_read(pb, tag, 4);
    uint32_t off = avio_rb32(pb);
    uint32_t size = avio_rb32(pb);
    uint32_t id = avio_rb32(pb);
    uint32_t rate = avio_rb32(pb);
    uint32_t ch = avio_rb32(pb);
    int cid = CID_NONE;
    switch (id) {
    case 1: cid = CID_PCM_MULAW; break;
    case 2: cid = CID_PCM_S8; break;
    case 3: cid = CID_PCM_S16BE; break;
    case 4: cid = CID_PCM_S24BE; break;
    case 5: cid = CID_PCM_S32BE; break;
    case 6: cid = CID_PCM_F32BE; break;
    case 7: cid = CID_PCM_F64BE; break;
    case 27: cid = CID_PCM_ALAW; break;
    }
    if (cid == CID_NONE || !rate || !ch || off < 24) return AVERROR_INVALIDDATA;
    if (off > 24) {
        char *ann = calloc(1, off - 24 + 1);
        avio_read(pb, (uint8_t *)ann, off - 24);
        char *save, *line = strtok_r(ann, "\n", &save);
        while (line) {
            char *eq = strchr(line, '=');
            if (eq) {
                *eq = 0;
                const char *k = line;
                char lk[64];
                snprintf(lk, sizeof(lk), "%s", k);
                for (char *q = lk; *q; q++) *q = (char)tolower((unsigned char)*q);
                if (!strcmp(lk, "title") || !strcmp(lk, "artist") || !strcmp(lk, "album") || !strcmp(lk, "track") || !strcmp(lk, "genre"))
                    dict_set(&s->metadata, lk, eq + 1);
            }
            line = strtok_r(NULL, "\n", &save);
        }
        free(ann);
    }
    Stream *st = format_new_stream(s);
    st->par.codec_type = MT_AUDIO;
    st->par.codec_id = cid;
    st->par.codec_tag = id;
    st->par.sample_rate = rate;
    st->par.ch_layout.order = 0;
    st->par.ch_layout.nb_channels = ch;
    int bps = get_bits_per_sample(cid);
    st->par.bits_per_coded_sample = bps;
    st->par.block_align = bps * ch / 8;
    st->par.bit_rate = (int64_t)bps * ch * rate;
    st->time_base = (Rational){ 1, rate };
    if (cid == CID_PCM_S24BE || cid == CID_PCM_S32BE) st->par.bits_per_raw_sample = bps;
    s->data_offset = off;
    a->data_end = size != 0xFFFFFFFF ? off + (int64_t)size : INT64_MAX;
    if (size != 0xFFFFFFFF && st->par.block_align) st->duration = size / st->par.block_align;
    st->start_time = 0;
    avio_seek(pb, off);
    return 0;
}

static int au_read_packet(FormatContext *s, Packet *pkt)
{
    AuDemux *a = s->priv;
    AiffDemux tmp = { a->data_end };
    void *save = s->priv;
    s->priv = &tmp;
    int r = aiff_read_packet(s, pkt);
    s->priv = save;
    return r;
}

static void au_close(FormatContext *s) { free(s->priv); s->priv = NULL; }

const InputFormat ff_au_demuxer = {
    "au", "Sun AU", "au", 0, au_probe, au_read_header, au_read_packet, aiff_read_seek, au_close, NULL
};
