/* AIFF and Sun AU containers */
#include "format.h"

static uint32_t mktag(const char *t) { return (uint8_t)t[0] | ((uint8_t)t[1] << 8) | ((uint8_t)t[2] << 16) | ((uint32_t)(uint8_t)t[3] << 24); }

/* ------------------------------------------------------------------ */
/* AIFF muxer                                                          */
typedef struct AiffMux { int64_t form, frames, ssnd; } AiffMux;

static uint32_t aiff_tag(int id)
{
    switch (id) {
    case CID_PCM_S16BE: case CID_PCM_S8: case CID_PCM_S24BE: case CID_PCM_S32BE: return mktag("NONE");
    case CID_PCM_U8: return mktag("raw ");
    case CID_PCM_F32BE: return mktag("fl32");
    case CID_PCM_F64BE: return mktag("fl64");
    case CID_PCM_ALAW: return mktag("alaw");
    case CID_PCM_MULAW: return mktag("ulaw");
    case CID_PCM_S16LE: return mktag("sowt");
    }
    return 0;
}

static int aiff_init(FormatContext *s)
{
    if (s->nb_streams != 1 || s->streams[0]->par.codec_type != MT_AUDIO) {
        av_log(s->log_ctx, AV_LOG_ERROR, "AIFF allows only one audio stream and a picture.\n");
        return AVERROR(22);
    }
    Stream *st = s->streams[0];
    st->par.codec_tag = aiff_tag(st->par.codec_id);
    if (!st->par.codec_tag) {
        const CodecDesc *d = codec_desc(st->par.codec_id);
        av_log(s->log_ctx, AV_LOG_ERROR, "Tag %s incompatible with output codec id '%d' ([0][0][0][0])\n", "[0][0][0][0]", d ? d->id : 0);
        return AVERROR(22);
    }
    st->time_base = (Rational){ 1, st->par.sample_rate };
    s->priv = calloc(1, sizeof(AiffMux));
    return 0;
}

static void aiff_put_meta(FormatContext *s, const char *key, const char *id)
{
    const char *v = dict_get(&s->metadata, key);
    if (!v) return;
    size_t size = strlen(v);
    avio_write(s->pb, (const uint8_t *)id, 4);
    avio_wb32(s->pb, (unsigned)((size + 1) & ~1));
    avio_write(s->pb, (const uint8_t *)v, (int)size);
    if (size & 1) avio_w8(s->pb, 0);
}

static int aiff_write_header(FormatContext *s)
{
    AiffMux *a = s->priv;
    AVIO *pb = s->pb;
    CodecPar *par = &s->streams[0]->par;
    int aifc = par->codec_tag != mktag("NONE");
    avio_write(pb, (const uint8_t *)"FORM", 4);
    a->form = avio_wtell(pb);
    avio_wb32(pb, 0);
    avio_write(pb, (const uint8_t *)(aifc ? "AIFC" : "AIFF"), 4);
    if (aifc) {
        avio_write(pb, (const uint8_t *)"FVER", 4);
        avio_wb32(pb, 4);
        avio_wb32(pb, 0xA2805140);
    }
    aiff_put_meta(s, "title", "NAME");
    aiff_put_meta(s, "author", "AUTH");
    aiff_put_meta(s, "copyright", "(c) ");
    aiff_put_meta(s, "comment", "ANNO");
    avio_write(pb, (const uint8_t *)"COMM", 4);
    avio_wb32(pb, aifc ? 24 : 18);
    avio_wb16(pb, par->ch_layout.nb_channels);
    a->frames = avio_wtell(pb);
    avio_wb32(pb, 0);
    int bps = par->bits_per_coded_sample ? par->bits_per_coded_sample : get_bits_per_sample(par->codec_id);
    if (!par->block_align) par->block_align = (bps * par->ch_layout.nb_channels) >> 3;
    avio_wb16(pb, bps);
    double sr = par->sample_rate;
    uint64_t bits;
    memcpy(&bits, &sr, 8);
    avio_wb16(pb, (unsigned)((bits >> 52) + (16383 - 1023)));
    avio_wb64(pb, (UINT64_C(1) << 63) | (bits << 11));
    if (aifc) {
        avio_wl32(pb, par->codec_tag);
        avio_wb16(pb, 0);
    }
    avio_write(pb, (const uint8_t *)"SSND", 4);
    a->ssnd = avio_wtell(pb);
    avio_wb32(pb, 0);
    avio_wb32(pb, 0);
    avio_wb32(pb, 0);
    return 0;
}

static int aiff_write_packet(FormatContext *s, Packet *pkt)
{
    avio_write(s->pb, pkt->data, pkt->size);
    return 0;
}

static int aiff_write_trailer(FormatContext *s)
{
    AiffMux *a = s->priv;
    AVIO *pb = s->pb;
    CodecPar *par = &s->streams[0]->par;
    int64_t data_size = avio_wtell(pb);
    if (data_size & 1) avio_w8(pb, 0);
    if (pb->seekable) {
        int64_t file_size = avio_wtell(pb);
        avio_wseek(pb, a->form);
        avio_wb32(pb, (uint32_t)(file_size - a->form - 4));
        avio_wseek(pb, a->frames);
        avio_wb32(pb, (uint32_t)((data_size - a->ssnd - 12) / par->block_align));
        avio_wseek(pb, a->ssnd);
        avio_wb32(pb, (uint32_t)(data_size - a->ssnd - 4));
        avio_wseek(pb, file_size);
    }
    return 0;
}

static void aiff_deinit(FormatContext *s) { free(s->priv); s->priv = NULL; }

static const FmtOpt aiff_mux_opts[] = {
    { "write_id3v2", 2, "false", 0, 1, NULL },
