    aiff_init, aiff_write_header, aiff_write_packet, aiff_write_trailer, aiff_deinit, aiff_mux_opts, 0
};

/* ------------------------------------------------------------------ */
/* AIFF demuxer                                                        */
typedef struct AiffDemux { int64_t data_end; } AiffDemux;

static int aiff_probe(const uint8_t *p, int size)
{
    if (size >= 12 && !memcmp(p, "FORM", 4) && (!memcmp(p + 8, "AIFF", 4) || !memcmp(p + 8, "AIFC", 4)))
        return 100;
    return 0;
}

static int aiff_read_header(FormatContext *s)
{
    AVIO *pb = s->pb;
    AiffDemux *a = calloc(1, sizeof(*a));
    s->priv = a;
    uint8_t tag[4];
    avio_read(pb, tag, 4);
    avio_rb32(pb);
    avio_read(pb, tag, 4);
    int aifc = !memcmp(tag, "AIFC", 4);
    Stream *st = NULL;
    int got_ssnd = 0;
    uint32_t nframes = 0;
    int bps = 0;
    while (!got_ssnd) {
        if (avio_read(pb, tag, 4) != 4) break;
        uint32_t size = avio_rb32(pb);
        int64_t start = avio_tell(pb);
        int64_t next = start + size + (size & 1);
        if (!memcmp(tag, "COMM", 4)) {
            st = format_new_stream(s);
            st->par.codec_type = MT_AUDIO;
            int ch = avio_rb16(pb);
            nframes = avio_rb32(pb);
            bps = avio_rb16(pb);
            int exp = avio_rb16(pb);
            uint64_t val = avio_rb64(pb);
            int sign = exp & 0x8000;
            exp &= 0x7fff;
            double sr = ldexp((double)val, exp - 16383 - 63);
            if (sign) sr = -sr;
            st->par.sample_rate = (int)sr;
            st->par.ch_layout.order = 0;
            st->par.ch_layout.nb_channels = ch;
            st->par.bits_per_coded_sample = bps;
            int id = CID_NONE;
            if (aifc && size >= 22) {
                uint8_t ct[4];
                avio_read(pb, ct, 4);
                if (!memcmp(ct, "NONE", 4) || !memcmp(ct, "twos", 4)) id = CID_NONE;
                else if (!memcmp(ct, "sowt", 4)) id = CID_PCM_S16LE;
                else if (!memcmp(ct, "fl32", 4) || !memcmp(ct, "FL32", 4)) id = CID_PCM_F32BE;
                else if (!memcmp(ct, "fl64", 4) || !memcmp(ct, "FL64", 4)) id = CID_PCM_F64BE;
                else if (!memcmp(ct, "alaw", 4) || !memcmp(ct, "ALAW", 4)) id = CID_PCM_ALAW;
                else if (!memcmp(ct, "ulaw", 4) || !memcmp(ct, "ULAW", 4)) id = CID_PCM_MULAW;
                else if (!memcmp(ct, "raw ", 4)) id = CID_PCM_U8;
                st->par.codec_tag = ct[0] | (ct[1] << 8) | (ct[2] << 16) | ((uint32_t)ct[3] << 24);
            }
            if (id == CID_NONE) {
                if (bps <= 8) id = CID_PCM_S8;
                else if (bps <= 16) id = CID_PCM_S16BE;
                else if (bps <= 24) id = CID_PCM_S24BE;
                else id = CID_PCM_S32BE;
            }
            st->par.codec_id = id;
            int ebps = get_bits_per_sample(id);
            st->par.block_align = ebps * ch / 8;
            st->par.bit_rate = (int64_t)ebps * ch * st->par.sample_rate;
            st->time_base = (Rational){ 1, st->par.sample_rate ? st->par.sample_rate : 1 };
            if (id == CID_PCM_S24BE || id == CID_PCM_S32BE) st->par.bits_per_raw_sample = ebps;
            avio_seek(pb, next);
        } else if (!memcmp(tag, "SSND", 4)) {
            uint32_t offset = avio_rb32(pb);
            avio_rb32(pb);
            avio_skip(pb, offset);
            s->data_offset = avio_tell(pb);
            a->data_end = start + size;
            got_ssnd = 1;
        } else if (!memcmp(tag, "NAME", 4) || !memcmp(tag, "AUTH", 4) || !memcmp(tag, "(c) ", 4) || !memcmp(tag, "ANNO", 4)) {
            char *v = calloc(1, size + 1);
            avio_read(pb, (uint8_t *)v, size);
            const char *k = !memcmp(tag, "NAME", 4) ? "title" : !memcmp(tag, "AUTH", 4) ? "author" : !memcmp(tag, "(c) ", 4) ? "copyright" : "comment";
            dict_set(&s->metadata, k, v);
            free(v);
            avio_seek(pb, next);
        } else {
            if (avio_seek(pb, next) < 0) break;
        }
    }
    if (!st || !got_ssnd) return AVERROR_INVALIDDATA;
    if (nframes) st->duration = nframes;
    st->start_time = 0;
    return 0;
}

static int aiff_read_packet(FormatContext *s, Packet *pkt)
{
    AiffDemux *a = s->priv;
    Stream *st = s->streams[0];
    int64_t pos = avio_tell(s->pb);
    int64_t left = a->data_end - pos;
    if (left <= 0) return AVERROR_EOF;
    int size = 1024 * st->par.block_align;
    if (size > left) size = (int)left;
    pkt->data = malloc(size + 64);
    int r = avio_read(s->pb, pkt->data, size);
    if (r <= 0) { free(pkt->data); pkt->data = NULL; return AVERROR_EOF; }
    r -= r % st->par.block_align;
    if (r <= 0) { free(pkt->data); pkt->data = NULL; return AVERROR_EOF; }
    memset(pkt->data + r, 0, 64);
    pkt->size = r;
    pkt->pos = pos;
    pkt->flags = PKT_FLAG_KEY;
    pkt->pts = pkt->dts = (pos - s->data_offset) / st->par.block_align;
    pkt->duration = r / st->par.block_align;
    return 0;
}

static int aiff_read_seek(FormatContext *s, int64_t ts_us)
{
    Stream *st = s->streams[0];
    int64_t sample = av_rescale_rnd(ts_us, st->par.sample_rate, AV_TIME_BASE, AV_ROUND_DOWN);
    if (sample < 0) sample = 0;
    return avio_seek(s->pb, s->data_offset + sample * st->par.block_align) < 0 ? -1 : 0;
}

static void aiff_close(FormatContext *s) { free(s->priv); s->priv = NULL; }

