    "aiff", "Audio IFF", "aif,aiff,aifc", 0, aiff_probe, aiff_read_header, aiff_read_packet, aiff_read_seek, aiff_close, NULL
};

/* ------------------------------------------------------------------ */
/* AU                                                                  */
typedef struct AuMux { int header_size; } AuMux;

static uint32_t au_tag(int id)
{
    switch (id) {
    case CID_PCM_MULAW: return 1;
    case CID_PCM_S8: return 2;
    case CID_PCM_S16BE: return 3;
    case CID_PCM_S24BE: return 4;
    case CID_PCM_S32BE: return 5;
    case CID_PCM_F32BE: return 6;
    case CID_PCM_F64BE: return 7;
    case CID_PCM_ALAW: return 27;
    }
    return 0;
}

static int au_init(FormatContext *s)
{
    if (s->nb_streams != 1) {
        av_log(s->log_ctx, AV_LOG_ERROR, "only one stream is supported\n");
        return AVERROR(22);
    }
    Stream *st = s->streams[0];
    st->par.codec_tag = au_tag(st->par.codec_id);
    if (!st->par.codec_tag) {
        av_log(s->log_ctx, AV_LOG_ERROR, "unsupported codec\n");
        return AVERROR(22);
    }
    st->time_base = (Rational){ 1, st->par.sample_rate };
    s->priv = calloc(1, sizeof(AuMux));
    return 0;
}

static int au_write_header(FormatContext *s)
{
    AuMux *a = s->priv;
    AVIO *pb = s->pb;
    CodecPar *par = &s->streams[0]->par;
    char ann[4096];
    int len = 0;
    static const char *keys[] = { "Title", "Artist", "Album", "Track", "Genre" };
    for (int i = 0; i < 5; i++) {
        const char *v = dict_get(&s->metadata, keys[i]);
        if (v) {
            if (len) ann[len++] = '\n';
            len += snprintf(ann + len, sizeof(ann) - len, "%s=%s", keys[i], v);
        }
    }
    a->header_size = 24 + len + (8 - (len & 7));
    avio_write(pb, (const uint8_t *)".snd", 4);
    avio_wb32(pb, a->header_size);
    avio_wb32(pb, 0xFFFFFFFF);
    avio_wb32(pb, par->codec_tag);
    avio_wb32(pb, par->sample_rate);
    avio_wb32(pb, par->ch_layout.nb_channels);
    avio_write(pb, (const uint8_t *)ann, len);
    for (int i = 0; i < 8 - (len & 7); i++) avio_w8(pb, 0);
    return 0;
}

static int au_write_trailer(FormatContext *s)
{
    AuMux *a = s->priv;
    AVIO *pb = s->pb;
    int64_t file_size = avio_wtell(pb);
    if (pb->seekable && file_size < INT32_MAX) {
        avio_wseek(pb, 8);
        avio_wb32(pb, (uint32_t)(file_size - a->header_size));
        avio_wseek(pb, file_size);
    }
    return 0;
}

static void au_deinit(FormatContext *s) { free(s->priv); s->priv = NULL; }

const OutputFormat ff_au_muxer = {
    "au", "Sun AU", "audio/basic", "au", CID_PCM_S16BE, CID_NONE, 0,
    au_init, au_write_header, aiff_write_packet, au_write_trailer, au_deinit, NULL, 0
};

typedef struct AuDemux { int64_t data_end; } AuDemux;

static int au_probe(const uint8_t *p, int size)
{
    if (size >= 24 && !memcmp(p, ".snd", 4)) return 100;
    return 0;
}

static int au_read_header(FormatContext *s)
{
    AVIO *pb = s->pb;
    AuDemux *a = calloc(1, sizeof(*a));
    s->priv = a;
    uint8_t tag[4];
    avio_read(pb, tag, 4);
    uint32_t off = avio_rb32(pb);
    uint32_t size = avio_rb32(pb);
    uint32_t id = avio_rb32(pb);
    uint32_t rate = avio_rb32(pb);
    uint32_t ch = avio_rb32(pb);
    int cid = CID_NONE;
    switch (id) {
    case 1: cid = CID_PCM_MULAW; break;
    case 2: cid = CID_PCM_S8; break;
    case 3: cid = CID_PCM_S16BE; break;
    case 4: cid = CID_PCM_S24BE; break;
    case 5: cid = CID_PCM_S32BE; break;
    case 6: cid = CID_PCM_F32BE; break;
    case 7: cid = CID_PCM_F64BE; break;
    case 27: cid = CID_PCM_ALAW; break;
    }
    if (cid == CID_NONE || !rate || !ch || off < 24) return AVERROR_INVALIDDATA;
    if (off > 24) {
        char *ann = calloc(1, off - 24 + 1);
        avio_read(pb, (uint8_t *)ann, off - 24);
        char *save, *line = strtok_r(ann, "\n", &save);
        while (line) {
            char *eq = strchr(line, '=');
            if (eq) {
                *eq = 0;
                const char *k = line;
                char lk[64];
                snprintf(lk, sizeof(lk), "%s", k);
                for (char *q = lk; *q; q++) *q = (char)tolower((unsigned char)*q);
                if (!strcmp(lk, "title") || !strcmp(lk, "artist") || !strcmp(lk, "album") || !strcmp(lk, "track") || !strcmp(lk, "genre"))
                    dict_set(&s->metadata, lk, eq + 1);
            }
            line = strtok_r(NULL, "\n", &save);
        }
        free(ann);
    }
    Stream *st = format_new_stream(s);
    st->par.codec_type = MT_AUDIO;
    st->par.codec_id = cid;
    st->par.codec_tag = id;
    st->par.sample_rate = rate;
    st->par.ch_layout.order = 0;
    st->par.ch_layout.nb_channels = ch;
    int bps = get_bits_per_sample(cid);
    st->par.bits_per_coded_sample = bps;
    st->par.block_align = bps * ch / 8;
    st->par.bit_rate = (int64_t)bps * ch * rate;
    st->time_base = (Rational){ 1, rate };
    if (cid == CID_PCM_S24BE || cid == CID_PCM_S32BE) st->par.bits_per_raw_sample = bps;
    s->data_offset = off;
    a->data_end = size != 0xFFFFFFFF ? off + (int64_t)size : INT64_MAX;
    if (size != 0xFFFFFFFF && st->par.block_align) st->duration = size / st->par.block_align;
    st->start_time = 0;
    avio_seek(pb, off);
    return 0;
}

static int au_read_packet(FormatContext *s, Packet *pkt)
{
    AuDemux *a = s->priv;
    AiffDemux tmp = { a->data_end };
    void *save = s->priv;
    s->priv = &tmp;
    int r = aiff_read_packet(s, pkt);
    s->priv = save;
    return r;
}

static void au_close(FormatContext *s) { free(s->priv); s->priv = NULL; }

const InputFormat ff_au_demuxer = {
    "au", "Sun AU", "au", 0, au_probe, au_read_header, au_read_packet, aiff_read_seek, au_close, NULL
};
