# processing function
old='''/* run frame through filters starting at index i; NULL frame = EOF */'''
new='''static void biquad_setup(AFilter *f, int sr)
{
    double w0 = 2 * M_PI * f->bq_freq / sr;
    double alpha = 0;
    switch (f->bq_width_type) {
    case 1: alpha = sin(w0) / (2 * f->bq_freq / f->bq_width); break;
    case 5: alpha = sin(w0) / (2 * f->bq_freq / (f->bq_width * 1000)); break;
    case 2: alpha = sin(w0) * sinh(log(2.) / 2 * f->bq_width * w0 / sin(w0)); break;
    case 3: alpha = sin(w0) / (2 * f->bq_width); break;
    case 4: { double A = 1; alpha = sin(w0) / 2 * sqrt((A + 1 / A) * (1 / f->bq_width - 1) + 2); break; }
    }
    double a0, a1, a2, b0, b1, b2;
    if (!f->bq_kind) {
        if (f->bq_poles == 1) { a0 = 1; a1 = -exp(-w0); a2 = 0; b0 = (1 - a1) / 2; b1 = -b0; b2 = 0; }
        else { a0 = 1 + alpha; a1 = -2 * cos(w0); a2 = 1 - alpha; b0 = (1 + cos(w0)) / 2; b1 = -(1 + cos(w0)); b2 = (1 + cos(w0)) / 2; }
    } else {
        if (f->bq_poles == 1) { a0 = 1; a1 = -exp(-w0); a2 = 0; b0 = 1 + a1; b1 = 0; b2 = 0; }
        else { a0 = 1 + alpha; a1 = -2 * cos(w0); a2 = 1 - alpha; b0 = (1 - cos(w0)) / 2; b1 = 1 - cos(w0); b2 = (1 - cos(w0)) / 2; }
    }
    a1 /= a0; a2 /= a0; b0 /= a0; b1 /= a0; b2 /= a0; a0 /= a0;
    f->bq_a[0] = a0; f->bq_a[1] = a1; f->bq_a[2] = a2;
    f->bq_b[0] = b0; f->bq_b[1] = b1; f->bq_b[2] = b2;
    f->bq_ready = 1;
}

static void apply_biquad(AFilter *f, Frame *fr)
{
    if (!f->bq_ready) biquad_setup(f, fr->sample_rate);
    int ch = fr->ch_layout.nb_channels, n = fr->nb_samples;
    int pf = sf_packed(fr->format);
    for (int c = 0; c < ch && c < 64; c++) {
        double *cache = f->bq_cache[c];
        if (pf == SF_S16 || pf == SF_FLT) {
            float a1 = (float)-f->bq_a[1], a2 = (float)-f->bq_a[2];
            float b0 = (float)f->bq_b[0], b1 = (float)f->bq_b[1], b2 = (float)f->bq_b[2];
            float in1 = (float)cache[0], in2 = (float)cache[1], out1 = (float)cache[2], out2 = (float)cache[3];
            float wet = (float)f->bq_mix, dry = 1.f - wet;
            for (int i = 0; i < n; i++) {
                size_t k = (size_t)i * ch + c;
                float in = pf == SF_S16 ? ((int16_t *)fr->data)[k] : ((float *)fr->data)[k];
                float out = in * b0 + in1 * b1 + in2 * b2 + out1 * a1 + out2 * a2;
                in2 = in1; in1 = in; out2 = out1; out1 = out;
                out = out * wet + in * dry;
                if (pf == SF_S16) {
                    if (out < INT16_MIN) ((int16_t *)fr->data)[k] = INT16_MIN;
                    else if (out > INT16_MAX) ((int16_t *)fr->data)[k] = INT16_MAX;
                    else ((int16_t *)fr->data)[k] = (int16_t)out;
                } else ((float *)fr->data)[k] = out;
            }
            cache[0] = in1; cache[1] = in2; cache[2] = out1; cache[3] = out2;
        } else {
            double a1 = -f->bq_a[1], a2 = -f->bq_a[2];
            double b0 = f->bq_b[0], b1 = f->bq_b[1], b2 = f->bq_b[2];
            double in1 = cache[0], in2 = cache[1], out1 = cache[2], out2 = cache[3];
            double wet = f->bq_mix, dry = 1. - wet;
            for (int i = 0; i < n; i++) {
                size_t k = (size_t)i * ch + c;
                double in = pf == SF_S32 ? ((int32_t *)fr->data)[k] : ((double *)fr->data)[k];
                double out = in * b0 + in1 * b1 + in2 * b2 + out1 * a1 + out2 * a2;
                in2 = in1; in1 = in; out2 = out1; out1 = out;
                out = out * wet + in * dry;
                if (pf == SF_S32) {
                    if (out < INT32_MIN) ((int32_t *)fr->data)[k] = INT32_MIN;
                    else if (out > INT32_MAX) ((int32_t *)fr->data)[k] = INT32_MAX;
                    else ((int32_t *)fr->data)[k] = (int32_t)out;
                } else ((double *)fr->data)[k] = out;
            }
            cache[0] = in1; cache[1] = in2; cache[2] = out1; cache[3] = out2;
        }
    }
}

