def load(fn,ch):
    d=open(fn,'rb').read(); i=12
    while i<len(d):
        tag=d[i:i+4]; sz=struct.unpack('<I',d[i+4:i+8])[0]
        if tag==b'data': data=d[i+8:i+8+sz]; break
        i+=8+sz+(sz&1)
    x=struct.unpack('<%dh'%(len(data)//2),data); return x,len(x)//ch
